    def stage_object(self, chunks, *, expected_digest=None):
        return self.cas.stage(chunks, self.store.staging_root,
                              max_bytes=self.max_object_bytes, expected_digest=expected_digest)

    def ingest(self, project, data, *, media_type="application/octet-stream", original_name=None,
               expected_digest=None, idempotency_key=None):
        return self._ingest_transfer(project, data, media_type=media_type, original_name=original_name,
                                     expected_digest=expected_digest, idempotency_key=idempotency_key)

    def _ingest_transfer(self, project, data, *, media_type, original_name, expected_digest,
                         idempotency_key, identity=None, upload_binding=None):
        idempotency_key = require_idempotency_key(idempotency_key)
        owned_stage = not isinstance(data, StagedObject)
        if owned_stage:
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise InvalidRequestError("object body must be bytes or a runtime staged transfer")
            if len(data) > self.max_object_bytes:
                raise ValidationError(f"object exceeds {self.max_object_bytes} byte limit")
            data = self.stage_object((data,), expected_digest=expected_digest)
        try:
            if data.size > self.max_object_bytes:
                raise ValidationError(f"object exceeds {self.max_object_bytes} byte limit")
            expected = (expected_digest or "").removeprefix("sha256:") or None
            if expected and expected != data.digest:
                raise ConflictError("content hash does not match expected digest")
            # The store mutex is the only publication/journal/receipt serializer.
            # Binary handlers verify before acquiring it; pinned stat tokens fence
            # reuse. A second upload lock would invert callers' existing store lock
            # (for example create_timeline_view -> ingest).
            existing = self.cas.existing_identity(data.digest, data.size)
            with self.store._mutex:
                self._assert_mutation_admitted()
                project_row = self.store.get_project(project) if project is not None else None
                project_id = project_row["id"] if project_row else "unscoped"
                aggregate_id = project_id if project_row else "objects"
                binding = dict(upload_binding) if upload_binding is not None else None
                request = {"content_digest": data.digest, "media_type": media_type,
                           "original_name": original_name, "expected_digest": expected}
                if project_row:
                    request["project_id"] = project_id
                if binding is not None:
                    request["publication_binding"] = binding
                request_hash = hashlib.sha256(canonical_json(request).encode()).hexdigest()
                replay = self._command_replay("object.ingest", aggregate_id, idempotency_key,
                                              request_hash, project_id=project_id)
                if replay is not None:
                    return replay
                if binding is not None:
                    self._validate_generic_output_binding(binding, identity=identity,
                        digest=data.digest, size=data.size, media_type=media_type,
                        original_name=original_name, idempotency_key=idempotency_key)
                if existing is None:
                    self._begin_cas_publication_journal("ingest", [{"digest": data.digest}], project_id=project_id)
                try:
                    self.cas.publish(data, existing_identity=existing)
                    data.discard()  # Drop the staging link before receipt/stat proofs.
                    with self.cas.open(data.digest) as published:
                        self._verified_cas_objects[data.digest] = file_identity(os.fstat(published.fileno()))
                    with self.store._transaction():
                        timestamp = now()
                        self.store.conn.execute(
                            "INSERT OR IGNORE INTO objects(digest, size, media_type, original_name, created_at) VALUES (?, ?, ?, ?, ?)",
                            (data.digest, data.size, media_type, original_name, timestamp))
                        if project_row:
                            self.store.conn.execute(
                                "INSERT OR IGNORE INTO project_objects(project_id, digest, relation, created_at) VALUES (?, ?, 'managed', ?)",
                                (project_id, data.digest, timestamp))
                        row = dict(self.store.conn.execute("SELECT * FROM objects WHERE digest=?", (data.digest,)).fetchone())
                        result = self._object_resource(row)
                        if project_row:
                            result["relation"] = "managed"
                        result = self._command_record("object.ingest", aggregate_id, idempotency_key,
                                                      request_hash, result, project_id=project_id)
                except BaseException:
                    self._recover_cas_publication_journals()
                    raise
                self._recover_cas_publication_journals()
                return result
        finally:
            if owned_stage:
                data.discard()

    @staticmethod
    def _media_import_operation_id(project_id, idempotency_key):
        # The caller persists this key before sending bytes, so it remains a
        # usable recovery identity even when the first acknowledgement is
        # lost. Project scoping is carried by every ledger lookup below.
        _ = project_id
        return str(idempotency_key)

    @staticmethod
    def _media_import_aggregate_id(project_id, operation_id):
        return f"{project_id}:{operation_id}"

    @staticmethod
    def _media_import_subkey(operation_id, purpose):
        return "media-import-" + purpose + "-" + hashlib.sha256(
            str(operation_id).encode()
        ).hexdigest()

    @staticmethod
    def _media_import_optional_integer(value, field):
        if value is None:
            return None
        if isinstance(value, str) and value.isdecimal():
            value = int(value)
        if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
            raise ValidationError(f"{field} must be a positive integer")
        return value

    @staticmethod
    def _media_import_optional_duration(value):
        if value is None:
            return None
        try:
            normalized = float(value)
        except (TypeError, ValueError) as exc:
            raise ValidationError("duration_seconds must be a positive finite number") from exc
        if not math.isfinite(normalized) or normalized <= 0:
            raise ValidationError("duration_seconds must be a positive finite number")
        return normalized

    def _media_import_request(self, project, data, *, media_type, original_name,
                              expected_digest, actor_id, width, height,
                              duration_seconds, idempotency_key):
        idempotency_key = require_idempotency_key(idempotency_key)
        if not isinstance(data, StagedObject):
            raise InvalidRequestError("media import body must be a runtime staged transfer")
        if data.size > self.max_object_bytes:
            raise ValidationError(f"object exceeds {self.max_object_bytes} byte limit")
        project_row = self.store.get_project(project)
        if not isinstance(media_type, str) or not media_type or len(media_type) > 255:
            raise ValidationError("media import Content-Type is invalid")
        content_type = media_type.lower().split("/", 1)[0]
        if content_type not in {"image", "video", "audio"} or "/" not in media_type:
            raise ValidationError("media import Content-Type must be image/*, video/* or audio/*")
        if original_name is not None:
            original_name = _canonical_managed_output_filename(original_name)
        if not isinstance(actor_id, str) or not actor_id:
            raise ValidationError("media import actor is required")
        width = self._media_import_optional_integer(width, "width")
        height = self._media_import_optional_integer(height, "height")
        duration_seconds = self._media_import_optional_duration(duration_seconds)
        if content_type == "audio" and (width is not None or height is not None):
            raise ValidationError("audio imports must not declare visual dimensions")
        if content_type == "image" and duration_seconds is not None:
            raise ValidationError("image imports must not declare duration_seconds")
        expected = (expected_digest or "").removeprefix("sha256:") or None
        digest = data.digest
        operation_id = self._media_import_operation_id(project_row["id"], idempotency_key)
        request = {
            "project_id": project_row["id"],
            "content_digest": digest,
            "media_type": media_type,
            "original_name": original_name,
            "expected_digest": expected,
            "actor_id": actor_id,
            "width": width,
            "height": height,
            "duration_seconds": duration_seconds,
        }
        return {
            "data": data,
            "project": project_row,
            "content_type": content_type,
            "digest": digest,
            "operation_id": operation_id,
            "idempotency_key": idempotency_key,
            "request": request,
            "request_hash": hashlib.sha256(canonical_json(request).encode()).hexdigest(),
        }

    def _claim_media_import_task(self, task_id):
        """Claim one exact private import task through the normal lease fence."""
        epoch = self.store._current_runtime_epoch()
        self.store.upsert_executor(
            MEDIA_IMPORT_EXECUTOR,
            [{
                "capability_id": MEDIA_IMPORT_CAPABILITY,
                "definition_digest": MEDIA_IMPORT_CAPABILITY_DIGEST,
                "status": "ready",
                "required_resource_keys": [],
                "estimated_scratch_bytes": 0,
                "estimated_output_bytes": 0,
            }],
            max_concurrency=1,
            runtime_epoch=epoch,
        )
        lease_id = new_id()
        claimed = self.store._claim_task(
            task_id, MEDIA_IMPORT_EXECUTOR, lease_id,
            runtime_epoch=epoch, _transactional=False,
        )
        task = claimed["task"]
        if task.get("status") != "running" or task.get("lease_token") != lease_id:
            raise ConflictError(
                "runtime host could not claim media import task",
                details={"task_id": task_id, "status": task.get("status")},
            )
        attempt_id = new_id()
        fence = int(task["lease_fence"])
        expires = task["lease_expires_at"]
        self.store.conn.execute(
            "INSERT INTO attempts(id, task_id, lease_id, fence, executor_id, lease_expires_at, settled, runtime_epoch) VALUES (?, ?, ?, ?, ?, ?, 0, ?)",
            (attempt_id, task_id, lease_id, fence, MEDIA_IMPORT_EXECUTOR, expires, epoch),
        )
        self.store.conn.execute(
            "UPDATE tasks SET attempt_id=? WHERE id=?", (attempt_id, task_id)
        )
        return {
            "attempt_id": attempt_id,
            "lease_id": lease_id,
            "fence": fence,
            "runtime_epoch": epoch,
        }

    @_durable_mutation
    def _settle_media_import_catalog(self, prepared, object_resource, verified_objects):
        """Atomically settle the host-owned task and publish one catalog pair."""
        project = prepared["project"]
        operation_id = prepared["operation_id"]
        idempotency_key = prepared["idempotency_key"]
        replay = self._command_replay(
            "media.import",
            self._media_import_aggregate_id(project["id"], operation_id),
            idempotency_key,
            prepared["request_hash"], project_id=project["id"],
        )
        if replay is not None:
            return replay

        object_id = object_resource["digest"]
        details = {
            "filename": prepared["request"]["original_name"],
            "mime_type": prepared["request"]["media_type"],
            "size": int(object_resource["size"]),
            "width": prepared["request"]["width"],
            "height": prepared["request"]["height"],
            "duration_seconds": prepared["request"]["duration_seconds"],
        }
        provenance = {
            "source": "external_upload",
            "origin": "imported",
            "actor_id": prepared["request"]["actor_id"],
            "import_operation_id": operation_id,
        }
        effect = {
            "effect_type": "generation.create_with_variant",
            "target_id": project["id"],
            "payload": {
                "generation_type": prepared["content_type"],
                "metadata": {
                    "provenance": provenance,
                    "params": {"content_type": prepared["content_type"], **details},
                },
                "variant_type": "original",
                "output_name": "original",
                "output_ordinal": 0,
                "primary_policy": "preserve",
            },
        }
        task = self.create_task({
            "capability_id": MEDIA_IMPORT_CAPABILITY,
            "capability_digest": MEDIA_IMPORT_CAPABILITY_DIGEST,
            "project": project["id"],
            "input_object_ids": [object_id],
            "settlement_effect": effect,
            "spec": {
                "operation": "media_import",
                "import_operation_id": operation_id,
            },
            "idempotency_key": self._media_import_subkey(operation_id, "task"),
        }, _host_owned=True)
        task_id = task["task"]["id"]
        attempt = self._claim_media_import_task(task_id)
        output = {
            "name": "original",
            "filename": prepared["request"]["original_name"] or "original",
            "kind": "object",
            "digest": object_id,
            "media_type": prepared["request"]["media_type"],
            "size": int(object_resource["size"]),
            "ordinal": 0,
            "role": "primary",
            "is_primary": True,
            "producer": {"kind": "runtime_host_import"},
            "provenance": provenance,
        }
        if prepared["request"]["duration_seconds"] is not None:
            output["duration_seconds"] = prepared["request"]["duration_seconds"]
        settled = self.settle_attempt(
            attempt["attempt_id"],
            {
                "lease_id": attempt["lease_id"],
                "fence": attempt["fence"],
                "runtime_epoch": attempt["runtime_epoch"],
                "outputs": [output],
                "effect": effect,
            },
            idempotency_key=self._media_import_subkey(operation_id, "settle"),
            _verified_objects=verified_objects,
        )
        generation_variant = settled["data"]["result"]["generation_variant"]
        result = {
            "provider": "runtime",
            "project": project["id"],
            "import_operation_id": operation_id,
            "status": "completed",
            "task_id": task_id,
            "generation_id": generation_variant["generation_id"],
            "variant_id": generation_variant["variant_id"],
            "asset_id": object_id,
            "entry": {
                "object_id": object_id,
                "media_type": prepared["request"]["media_type"],
                "size": int(object_resource["size"]),
                "filename": prepared["request"]["original_name"],
            },
            "provenance": provenance,
            "actor_id": prepared["request"]["actor_id"],
            **details,
        }
        return self._command_record(
            "media.import",
            self._media_import_aggregate_id(project["id"], operation_id),
            idempotency_key,
            prepared["request_hash"], result, project_id=project["id"],
        )

    @staticmethod
    def _validate_media_file(staged, media_type):
        """Bounded local decode check; forced demuxers cannot open playlists/URLs."""
        demuxers = {
            "image/png": "png_pipe", "image/jpeg": "jpeg_pipe", "image/webp": "webp_pipe",
            "image/gif": "gif", "image/bmp": "bmp_pipe", "image/tiff": "tiff_pipe",
            "image/avif": "mov", "video/mp4": "mov", "video/quicktime": "mov",
            "video/webm": "matroska", "video/x-matroska": "matroska", "video/x-msvideo": "avi",
            "video/mpeg": "mpeg", "video/mp2t": "mpegts", "audio/wav": "wav",
            "audio/x-wav": "wav", "audio/mpeg": "mp3", "audio/ogg": "ogg",
            "audio/flac": "flac", "audio/aac": "aac", "audio/mp4": "mov", "audio/webm": "matroska",
        }
        normalized = media_type.lower().split(";", 1)[0].strip()
        demuxer = demuxers.get(normalized)
        if demuxer is None:
            raise ValidationError("media import type has no supported local decoder")
        common = ["-v", "error", "-max_alloc", "67108864", "-protocol_whitelist", "file,pipe",
                  "-probesize", "8388608", "-analyzeduration", "5000000", "-f", demuxer]
        try:
            kind = "audio" if normalized.startswith("audio/") else "video"
            probe = subprocess.run(["ffprobe", *common, "-select_streams", "a:0" if kind == "audio" else "v:0", "-show_entries",
                "stream=codec_type,codec_name,width,height,duration:format=duration", "-of", "json", str(staged.path)],
                stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, timeout=30, check=True)
            info = json.loads(probe.stdout)
            streams = [item for item in info.get("streams", []) if item.get("codec_type") == kind]
            if not streams or any(int(item.get("width", 0)) * int(item.get("height", 0)) > 67108864 for item in streams):
                raise ValidationError("media import bytes do not match declared media type or dimensions exceed decoder limit")
            # Decode at least one frame/sample, beyond a merely recognizable header.
            decoded = subprocess.run(["ffmpeg", *common, "-threads", "1", "-i", str(staged.path),
                "-map", "0:a:0" if kind == "audio" else "0:v:0", "-frames:a" if kind == "audio" else "-frames:v", "1",
                "-threads", "1", "-f", "framehash", "-"], stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, timeout=30, check=True)
            if not any(line and not line.startswith(b"#") for line in decoded.stdout.splitlines()):
                raise ValidationError("media import has no decodable media frames")
        except (OSError, ValueError, subprocess.SubprocessError) as exc:
            raise ValidationError("media import is not locally decodable (ffprobe and ffmpeg are required)") from exc

    def import_media(self, project, data, *, media_type, original_name=None,
                     expected_digest=None, actor_id, width=None, height=None,
                     duration_seconds=None, idempotency_key=None):
        """Transfer/decode outside SQLite, then reuse fenced host settlement."""
        owned_stage = not isinstance(data, StagedObject)
        if owned_stage:
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise InvalidRequestError("media import body must be bytes")
            if len(data) > self.max_object_bytes:
                raise ValidationError(f"object exceeds {self.max_object_bytes} byte limit")
            data = self.stage_object((data,), expected_digest=expected_digest)
        try:
            with self.store._mutex:
                self._assert_mutation_admitted()
                prepared = self._media_import_request(
                    project, data, media_type=media_type, original_name=original_name,
                    expected_digest=expected_digest, actor_id=actor_id, width=width, height=height,
                    duration_seconds=duration_seconds, idempotency_key=idempotency_key)
            self._validate_media_file(data, media_type)
            ingested = self.ingest(prepared["project"]["id"], data,
                media_type=prepared["request"]["media_type"], original_name=prepared["request"]["original_name"],
                expected_digest=prepared["request"]["expected_digest"],
                idempotency_key=self._media_import_subkey(prepared["operation_id"], "object"))
            verified = self.cas.existing_identity(data.digest, data.size)
            if verified is None:
                raise ConflictError("imported CAS object is missing")
            return self._settle_media_import_catalog(prepared, ingested["data"], {data.digest: verified})
        finally:
            if owned_stage:
                data.discard()

    def get_media_import(self, project, operation_id):
        """Recover a completed import or its durable pre-settlement ingest."""
        if not isinstance(operation_id, str) or not IDEMPOTENCY_KEY_RE.fullmatch(operation_id):
            raise NotFoundError("media import operation not found")
        project_row = self.store.get_project(project)
        completed = self.store.conn.execute(
            "SELECT result_json FROM command_idempotency WHERE command_kind='media.import' AND aggregate_id=?",
            (self._media_import_aggregate_id(project_row["id"], operation_id),),
        ).fetchone()
        if completed:
            result = json.loads(completed["result_json"])
            if result.get("project") != project_row["id"]:
                raise NotFoundError("media import operation not found")
            return result
        pending = self.store.conn.execute(
            "SELECT result_json FROM command_idempotency WHERE command_kind='object.ingest' AND aggregate_id=? AND idempotency_key=?",
            (
                project_row["id"],
                self._media_import_subkey(operation_id, "object"),
            ),
        ).fetchone()
        if not pending:
            raise NotFoundError("media import operation not found")
        object_resource = json.loads(pending["result_json"])
        return {
            "provider": "runtime",
            "project": project_row["id"],
            "import_operation_id": operation_id,
            "status": "pending",
            "task_id": None,
            "generation_id": None,
            "variant_id": None,
            "asset_id": object_resource["digest"],
            "entry": {
                "object_id": object_resource["digest"],
                "media_type": object_resource["media_type"],
                "size": int(object_resource["size"]),
                "filename": object_resource.get("filename"),
            },
        }

    @staticmethod
    def _generic_output_idempotency_key(binding):
        return "output-" + hashlib.sha256(canonical_json(binding).encode()).hexdigest()

    def _validate_generic_output_binding(self, binding, *, identity, digest, size, media_type, original_name, idempotency_key):
        """Validate the explicit attempt identity carried by an output upload."""
        if not isinstance(binding, dict):
            raise ValidationError("output upload binding must be an object")
        required = {
            "project_id", "run_id", "task_id", "attempt_id", "executor_id",
            "lease_id", "fence", "runtime_epoch", "output_key", "output_port",
            "filename", "digest", "size", "media_type",
        }
        if set(binding) != required:
            raise ValidationError("output upload binding has unsupported or missing fields")
        if binding["project_id"] is not None and (not isinstance(binding["project_id"], str) or not binding["project_id"]):
            raise ValidationError("output upload binding project_id is invalid")
        for field in ("run_id", "task_id", "attempt_id", "executor_id", "lease_id", "output_key", "output_port", "filename", "media_type"):
            if not isinstance(binding[field], str) or not binding[field]:
                raise ValidationError(f"output upload binding {field} is invalid")
        for field in ("fence", "runtime_epoch", "size"):
            if isinstance(binding[field], bool) or not isinstance(binding[field], int) or binding[field] < 0:
                raise ValidationError(f"output upload binding {field} is invalid")
        if binding["runtime_epoch"] < 1 or binding["size"] > OBJECT_MAX_BYTES:
            raise ValidationError("output upload binding numeric fields are invalid")
        if binding["digest"] != "sha256:" + digest or binding["size"] != int(size) or binding["media_type"] != media_type:
            raise ConflictError("output upload binding does not match object bytes")
        if binding["filename"] != original_name:
            raise ConflictError("output upload binding does not match object filename")
        if idempotency_key != self._generic_output_idempotency_key(binding):
            raise ConflictError("output upload idempotency key is not bound to its provenance")
        if identity is not None and identity.get("actor") != binding["executor_id"]:
            raise AuthorizationError("output upload worker is not bound to the upload executor")
        row = self.store.conn.execute(
            "SELECT a.id AS attempt_id, a.task_id, a.executor_id, a.lease_id, a.fence, a.runtime_epoch, a.settled, "
            "t.run_id, t.status, t.attempt_id AS current_attempt_id, t.executor_id AS task_executor_id, "
            "t.lease_token, t.lease_fence, t.runtime_epoch AS task_runtime_epoch, r.project_id "
            "FROM attempts AS a JOIN tasks AS t ON t.id=a.task_id JOIN runs AS r ON r.id=t.run_id "
            "WHERE a.id=?",
            (binding["attempt_id"],),
        ).fetchone()
        if not row or row["settled"] != 0 or row["status"] != "running" or row["current_attempt_id"] != row["attempt_id"]:
            raise LeaseError("output upload attempt is stale")
        if (
            row["task_id"] != binding["task_id"]
            or row["run_id"] != binding["run_id"]
            or row["project_id"] != binding["project_id"]
            or row["executor_id"] != binding["executor_id"]
            or row["task_executor_id"] != binding["executor_id"]
            or row["lease_id"] != binding["lease_id"]
            or int(row["fence"]) != int(binding["fence"])
            or int(row["lease_fence"]) != int(binding["fence"])
            or int(row["runtime_epoch"]) != int(binding["runtime_epoch"])
            or int(row["task_runtime_epoch"]) != int(binding["runtime_epoch"])
            or int(row["runtime_epoch"]) != int(self.store._current_runtime_epoch())
        ):
            raise LeaseError("output upload provenance does not match the live attempt")

    @staticmethod
    def _generic_output_request_hash(digest, media_type, original_name, expected_digest, binding):
        request = {
            "content_digest": digest,
            "media_type": media_type,
            "original_name": original_name,
            "expected_digest": expected_digest,
        }
        if binding is not None:
            request["publication_binding"] = binding
        return hashlib.sha256(canonical_json(request).encode()).hexdigest()

    def ingest_object(self, data, *, media_type="application/octet-stream", original_name=None,
                      expected_digest=None, idempotency_key=None, identity=None, upload_binding=None):
        return self._ingest_transfer(None, data, media_type=media_type, original_name=original_name,
            expected_digest=expected_digest, idempotency_key=idempotency_key,
            identity=identity, upload_binding=upload_binding)

    def _discard_published_digest(self, digest):
        """Remove a newly published CAS file after a failed metadata commit."""
        try:
            self._unlink_cas_destination(digest)
        except (FileNotFoundError, OSError, ConflictError):
            # A failed cleanup is reconciled from the publication journal.
            pass

    def _object_resource(self, row):
        return {"object_id": "sha256:" + row["digest"], "digest": "sha256:" + row["digest"], "media_type": row["media_type"], "size": int(row["size"]), "version": 1, "created_at": row["created_at"], **({"filename": row["original_name"]} if row.get("original_name") else {})}

    def object(self, digest):
        digest = digest.removeprefix("sha256:")
        row = self.store.conn.execute("SELECT * FROM objects WHERE digest=?", (digest,)).fetchone()
        if not row:
            from .errors import NotFoundError
            raise NotFoundError("object not found")
        return dict(row), self.cas.read(digest)

    def open_object(self, digest):
        normalized = str(digest).removeprefix("sha256:")
        with self.store._mutex:
            row = self.store.conn.execute("SELECT * FROM objects WHERE digest=?", (normalized,)).fetchone()
            if not row:
                raise NotFoundError("object not found")
            metadata = dict(row)
            stream = self.cas.open(normalized)
        try:
            value = os.fstat(stream.fileno())
            if value.st_size != int(metadata["size"]):
                raise ConflictError("CAS object size does not match metadata")
            token = file_identity(value)
            # Verify once per immutable file identity, including after restart.
            # Repeated byte-range seeks do not scan the entire large object.
            if self._verified_cas_objects.get(normalized) != token:
                verified = self._verify_open_file(stream.fileno(), normalized, int(metadata["size"]), label="CAS object")
                self._verified_cas_objects[normalized] = file_identity(verified)
            stream.seek(0)
            return metadata, stream
        except BaseException:
            stream.close()
            raise

    def object_location(self, project, digest):
        """Verify project-owned bytes and return their current local CAS path.

        This separate local-host lookup is not a portable output receipt.
        Verification describes the file at lookup time, not a path lease.
        """
        with self.store._mutex:
            project_id = self.store.get_project(project)["id"]
            match = OBJECT_ID_RE.fullmatch(str(digest))
            if not match:
                raise ValidationError("object_id must be a canonical SHA-256 object id")
            normalized = match.group(1)
            row = self.store.conn.execute(
                "SELECT o.* FROM objects o JOIN project_objects po ON po.digest=o.digest "
                "WHERE o.digest=? AND po.project_id=? AND po.relation='managed'",
                (normalized, project_id),
            ).fetchone()
            if not row:
                raise NotFoundError("object is not owned by project")
        root_fd = prefix_fd = file_fd = None
        try:
            root_fd, prefix_fd = self._cas_prefix_fds(normalized, create=False)
            file_fd = os.open(
                normalized[2:], os.O_RDONLY | os.O_NONBLOCK | getattr(os, "O_NOFOLLOW", 0),
                dir_fd=prefix_fd,
            )
            self._verify_open_file(file_fd, normalized, int(row["size"]), label="canonical CAS object")
        except FileNotFoundError as exc:
            raise NotFoundError("canonical object bytes are missing", details={"object_id": digest}) from exc
        except OSError as exc:
            raise ConflictError("canonical CAS object is not a regular accessible file") from exc
        finally:
            for fd in (file_fd, prefix_fd, root_fd):
                if fd is not None:
                    os.close(fd)
        return {
            "object_id": "sha256:" + normalized, "digest": "sha256:" + normalized,
            "size": int(row["size"]), "media_type": row["media_type"],
            "filename": row["original_name"] or None,
            "local_path": str(self.cas.path_for(normalized)),
            "storage": "runtime_cas", "verified": True,
        }

    def objects(self, project):
        return self.store.list_project_objects(project)

    def list_project_objects(self, project, *, cursor=None, limit=PAGE_DEFAULT_LIMIT):
        rows = self.store.list_project_objects(project)
        return _page_rows(rows, scope=f"objects:{self.store.get_project(project)['id']}", cursor=cursor, limit=limit,
                          key_fn=lambda row: (str(row["created_at"]), str(row["digest"])),
                          resource_fn=lambda row: self._object_resource(row) | {"relation": row["relation"]})

    @_durable_mutation
    def create_media_relation(self, project, body, *, idempotency_key=None):
        self._require_object_body(body)
        project_id = self.store.get_project(project)["id"]
        allowed = {"derived_from", "variant_of", "uses_as_input", "mask_for", "audio_for"}
        kind = str(body.get("kind") or "")
        if kind not in allowed: raise ValidationError("unsupported media relation kind")
        source = str(body.get("from_object_id") or "").removeprefix("sha256:")
        target = str(body.get("to_object_id") or "").removeprefix("sha256:")
        if not source or not target or source == target: raise ValidationError("media relation requires distinct from_object_id and to_object_id")
        for digest in (source, target):
            if not self.store.conn.execute("SELECT 1 FROM objects WHERE digest=?", (digest,)).fetchone(): raise NotFoundError("object not found")
            if not self.store.conn.execute("SELECT 1 FROM project_objects WHERE project_id=? AND digest=?", (project_id, digest)).fetchone(): raise NotFoundError("object is not in project")
        metadata = body.get("metadata", {})
        if not isinstance(metadata, dict): raise ValidationError("media relation metadata must be an object")
        try:
            ordinal = int(body.get("ordinal", 0))
        except (TypeError, ValueError) as exc:
            raise ValidationError("media relation ordinal must be an integer") from exc
        if ordinal < 0: raise ValidationError("media relation ordinal must be non-negative")
        request_hash = hashlib.sha256(canonical_json({"project_id": project_id, "from_object_id": source, "to_object_id": target, "kind": kind, "ordinal": ordinal, "metadata": metadata}).encode()).hexdigest()
        aggregate_id = "media-relations"
        replay = self._command_replay("media_relation.create", aggregate_id, idempotency_key, request_hash, project_id=project_id)
        if replay is not None:
            return replay
        try:
            self.store.conn.execute("INSERT INTO media_relations VALUES (?, ?, ?, ?, ?, ?, ?)", (project_id, source, target, kind, ordinal, canonical_json(metadata), now()))
        except sqlite3.IntegrityError as exc:
            raise ConflictError("media relation already exists") from exc
        created_at = self.store.conn.execute("SELECT created_at FROM media_relations WHERE project_id=? AND from_digest=? AND to_digest=? AND kind=? AND ordinal=?", (project_id, source, target, kind, ordinal)).fetchone()[0]
        result = {"project_id": project_id, "from_object_id": "sha256:" + source, "to_object_id": "sha256:" + target, "kind": kind, "ordinal": ordinal, "metadata": metadata, "created_at": created_at}
        return self._command_record("media_relation.create", aggregate_id, idempotency_key, request_hash, result, project_id=project_id)

    @staticmethod
    def _source_frame_thumbnail_descriptor(body):
        if not isinstance(body, dict) or set(body) != {"object_id", "source_object_id", "recipe_version", "selection"}:
            raise ValidationError("source-frame thumbnail requires object_id, source_object_id, recipe_version, and selection")
        descriptor = copy.deepcopy(body)
        for field in ("object_id", "source_object_id"):
            value = descriptor[field]
            if not isinstance(value, str) or not OBJECT_ID_RE.fullmatch(value) or not value.startswith("sha256:"):
                raise ValidationError(f"thumbnail {field} must be a canonical sha256 object id")
        if isinstance(descriptor["recipe_version"], bool) or not isinstance(descriptor["recipe_version"], int) or descriptor["recipe_version"] != 1:
            raise ValidationError("thumbnail recipe_version is unsupported")
        selection = descriptor["selection"]
        if not isinstance(selection, dict) or set(selection) != {"kind", "source_time_seconds"} or selection.get("kind") != "source_frame":
            raise ValidationError("thumbnail selection must identify a source_frame and source_time_seconds")
        source_time = selection.get("source_time_seconds")
        if isinstance(source_time, bool) or not isinstance(source_time, (int, float)) or not math.isfinite(float(source_time)) or not 0 <= float(source_time) <= 4_000_000_000:
            raise ValidationError("thumbnail source_time_seconds must be finite and in [0, 4000000000]")
        normalized_time = round(float(source_time), 6)
        if normalized_time != float(source_time):
            raise ValidationError("thumbnail source_time_seconds must be normalized to six decimal places")
        descriptor["selection"]["source_time_seconds"] = normalized_time
        return descriptor

    @staticmethod
    def _source_frame_thumbnail_identity(descriptor):
        time_micros = int(round(float(descriptor["selection"]["source_time_seconds"]) * 1_000_000))
        return (1 << 62) + time_micros * 1_000 + int(descriptor["recipe_version"])

    def get_source_frame_thumbnail(self, project, *, source_object_id, source_time_seconds, recipe_version=1):
        project_id = self.store.get_project(project)["id"]
        if not isinstance(source_object_id, str) or not OBJECT_ID_RE.fullmatch(source_object_id) or not source_object_id.startswith("sha256:"):
            raise ValidationError("thumbnail source_object_id must be a canonical sha256 object id")
        source_digest = source_object_id.removeprefix("sha256:")
        owned = self.store.conn.execute(
            "SELECT 1 FROM project_objects WHERE project_id=? AND digest=?", (project_id, source_digest),
        ).fetchone()
        if not owned:
            raise NotFoundError("thumbnail source object is outside the project")
        descriptor = self._source_frame_thumbnail_descriptor({
            "object_id": "sha256:" + "0" * 64,
            "source_object_id": source_object_id,
            "recipe_version": recipe_version,
            "selection": {"kind": "source_frame", "source_time_seconds": source_time_seconds},
        })
        source = descriptor["source_object_id"].removeprefix("sha256:")
        rows = self.store.conn.execute(
            "SELECT from_digest, metadata_json FROM media_relations "
            "WHERE project_id=? AND to_digest=? AND kind='derived_from' AND ordinal=? "
            "ORDER BY created_at, from_digest",
            (project_id, source, self._source_frame_thumbnail_identity(descriptor)),
        ).fetchall()
        for row in rows:
            metadata = json.loads(row["metadata_json"])
            if metadata.get("thumbnail") == descriptor | {"object_id": "sha256:" + row["from_digest"]}:
                return {"thumbnail": descriptor | {"object_id": "sha256:" + row["from_digest"]}}
        return {"thumbnail": None}

    @_durable_mutation
    def ensure_source_frame_thumbnail(self, project, body, *, idempotency_key=None):
        idempotency_key = require_idempotency_key(idempotency_key)
        project_id = self.store.get_project(project)["id"]
        descriptor = self._source_frame_thumbnail_descriptor(body)
        source = descriptor["source_object_id"].removeprefix("sha256:")
        thumbnail = descriptor["object_id"].removeprefix("sha256:")
        if source == thumbnail:
            raise ValidationError("thumbnail source and image objects must be distinct")
        ordinal = self._source_frame_thumbnail_identity(descriptor)
        for digest in (source, thumbnail):
            if not self.store.conn.execute("SELECT 1 FROM objects WHERE digest=?", (digest,)).fetchone():
                raise NotFoundError("thumbnail source or image object not found")
            if not self.store.conn.execute("SELECT 1 FROM project_objects WHERE project_id=? AND digest=?", (project_id, digest)).fetchone():
                raise NotFoundError("thumbnail source or image object is outside the project")
        source_row = self.store.conn.execute("SELECT media_type FROM objects WHERE digest=?", (source,)).fetchone()
        if not str(source_row["media_type"]).lower().startswith("video/"):
            raise ConflictError("source-frame thumbnail source object must be video")
        image = self.store.conn.execute("SELECT media_type FROM objects WHERE digest=?", (thumbnail,)).fetchone()
        if not image or str(image["media_type"]).lower() != "image/jpeg":
            raise ConflictError("source-frame thumbnail object must be image/jpeg")
        aggregate_id = f"{source}:{ordinal}:{descriptor['recipe_version']}"
        request_hash = hashlib.sha256(canonical_json({"project_id": project_id, "thumbnail": descriptor}).encode()).hexdigest()
        replay = self._command_replay("thumbnail.source_frame.ensure", aggregate_id, idempotency_key, request_hash, project_id=project_id)
        if replay is not None:
            return replay
        candidates = self.store.conn.execute(
            "SELECT from_digest, metadata_json, created_at FROM media_relations "
            "WHERE project_id=? AND to_digest=? AND kind='derived_from' AND ordinal=? "
            "ORDER BY created_at, from_digest",
            (project_id, source, ordinal),
        ).fetchall()
        existing = None
        for candidate in candidates:
            candidate_thumbnail = json.loads(candidate["metadata_json"]).get("thumbnail")
            if isinstance(candidate_thumbnail, dict) and all(
                candidate_thumbnail.get(key) == descriptor.get(key)
                for key in ("source_object_id", "recipe_version", "selection")
            ):
                existing = {"thumbnail": candidate_thumbnail}
                break
        if existing:
            result = existing["thumbnail"]
        else:
            metadata = {"thumbnail": descriptor}
            self.store.conn.execute(
                "INSERT INTO media_relations VALUES (?, ?, ?, 'derived_from', ?, ?, ?)",
                (project_id, thumbnail, source, ordinal, canonical_json(metadata), now()),
            )
            result = descriptor
        return self._command_record("thumbnail.source_frame.ensure", aggregate_id, idempotency_key, request_hash, result, project_id=project_id)

    def list_media_relations(self, project, *, cursor=None, limit=PAGE_DEFAULT_LIMIT):
        project_id = self.store.get_project(project)["id"]
        rows = self.store.conn.execute("SELECT * FROM media_relations WHERE project_id=? ORDER BY created_at, from_digest, to_digest, kind, ordinal", (project_id,)).fetchall()
        return _page_rows(rows, scope=f"media-relations:{project_id}", cursor=cursor, limit=limit,
                          key_fn=lambda row: (str(row["created_at"]), str(row["from_digest"]), str(row["to_digest"]), str(row["kind"]), int(row["ordinal"])),
                          resource_fn=lambda row: {"project_id": row["project_id"], "from_object_id": "sha256:" + row["from_digest"], "to_object_id": "sha256:" + row["to_digest"], "kind": row["kind"], "ordinal": int(row["ordinal"]), "metadata": json.loads(row["metadata_json"]), "created_at": row["created_at"]})

    @staticmethod
    def _child_policy(value):
        required = {"capabilities", "targets", "input_object_ids"}
        if not isinstance(value, dict) or not required.issubset(value) or set(value) - required - {"stages", "final_publication", "limits", "recoverable_outputs", "discovery_grant"}:
            raise ValidationError("child_delegation requires capabilities, targets, and input_object_ids")
        capabilities = value["capabilities"]
        if not isinstance(capabilities, list) or not capabilities or len(capabilities) > 32:
            raise ValidationError("child_delegation.capabilities must be a non-empty bounded list")
        normalized_caps = []
        for item in capabilities:
            if not isinstance(item, dict) or set(item) != {"capability_id", "capability_digest"}:
                raise ValidationError("child_delegation capability must pin id and digest")
            if not isinstance(item["capability_id"], str) or not item["capability_id"] or not isinstance(item["capability_digest"], str) or not re.fullmatch(r"sha256:[0-9a-f]{64}", item["capability_digest"]):
                raise ValidationError("child_delegation capability identity is invalid")
            normalized_caps.append(dict(item))
        targets = value["targets"]
        if not isinstance(targets, list) or not targets or len(targets) > 32:
            raise ValidationError("child_delegation.targets must be a non-empty bounded list")
        normalized_targets = [_normalize_execution_target(target) for target in targets]
        inputs = value["input_object_ids"]
        if not isinstance(inputs, list) or len(inputs) > 256 or any(not isinstance(item, str) or not item.startswith("sha256:") or not OBJECT_ID_RE.fullmatch(item) for item in inputs):
            raise ValidationError("child_delegation.input_object_ids must contain sha256 object IDs")
        if len({canonical_json(item) for item in normalized_targets}) != len(normalized_targets) or len(set(inputs)) != len(inputs) or len({item["capability_id"] for item in normalized_caps}) != len(normalized_caps):
            raise ValidationError("child_delegation entries must be unique")
        policy = {"capabilities": normalized_caps, "targets": normalized_targets, "input_object_ids": inputs}
        limits = value.get("limits", {})
        if (not isinstance(limits, dict) or set(limits) - CHILD_LIMIT_CEILINGS.keys()
                or any(type(n) is not int or n < 1 or n > CHILD_LIMIT_CEILINGS[key] for key, n in limits.items())):
            raise ValidationError("child_delegation.limits must fit the finite Runtime ceilings")
        # Freeze effective defaults in the admitted policy. Reading an existing
        # full policy preserves its bounds after future default changes.
        policy["limits"] = CHILD_LIMITS | limits
        if "discovery_grant" in value:
            grant = value["discovery_grant"]
            identities = {"project_id", "run_id", "task_id", "attempt_id", "capability_id"}
            if (not isinstance(grant, dict) or set(grant) != identities | {"capability_digest", "limits"}
                    or any(not isinstance(grant[key], str) or not grant[key] or "*" in grant[key]
                           for key in identities)
                    or not isinstance(grant["capability_digest"], str)
                    or not re.fullmatch(r"sha256:[0-9a-f]{64}", grant["capability_digest"])):
                raise ValidationError("discovery_grant requires one exact project/run/task/attempt and root capability")
            bounds = grant["limits"]
            if (not isinstance(bounds, dict) or set(bounds) != DISCOVERY_GRANT_CEILINGS.keys()
                    or any(type(n) is not int or n < 1 or n > DISCOVERY_GRANT_CEILINGS[key]
                           for key, n in bounds.items())):
                raise ValidationError("discovery_grant.limits requires every finite prototype bound")
            policy["discovery_grant"] = {**grant, "limits": dict(bounds)}
        if "recoverable_outputs" in value:
            grants = value["recoverable_outputs"]
            if not isinstance(grants, list) or len(grants) != 1:
                raise ValidationError("recoverable_outputs requires one exact pinned Human Review grant")
            grant = grants[0]
            if (not isinstance(grant, dict)
                    or set(grant) != {"capability_id", "capability_digest", "output_ports"}
                    or grant.get("capability_id") != "editorial.human_review"
                    or grant.get("output_ports") != ["state_result"]
                    or {key: grant.get(key) for key in ("capability_id", "capability_digest")} not in normalized_caps):
                raise ValidationError("recoverable_outputs must pin editorial.human_review/state_result in capabilities")
            policy["recoverable_outputs"] = [dict(grant)]
        if "stages" in value:
            stages = value["stages"]
            if not isinstance(stages, list) or not stages or len(stages) > 16:
                raise ValidationError("child_delegation.stages must be a non-empty bounded list")
            normalized_stages = []
            preceding = set()
            for stage in stages:
                if not isinstance(stage, dict) or set(stage) != {"name", "capability_id", "capability_digest", "target", "inputs"}:
                    raise ValidationError("each child stage requires name, capability, target, and inputs")
                name = stage["name"]
                if not isinstance(name, str) or not re.fullmatch(r"[A-Za-z][A-Za-z0-9_-]{0,63}", name) or name in preceding:
                    raise ValidationError("child stage name is invalid or repeated")
                capability = {"capability_id": stage["capability_id"], "capability_digest": stage["capability_digest"]}
                target = _normalize_execution_target(stage["target"])
                if capability not in normalized_caps or target not in normalized_targets:
                    raise ValidationError("child stage capability or target is outside policy")
                declared_inputs = stage["inputs"]
                if not isinstance(declared_inputs, list) or len(declared_inputs) > 256:
                    raise ValidationError("child stage inputs must be a bounded ordered list")
                names = set()
                for ref in declared_inputs:
                    if not isinstance(ref, dict) or not isinstance(ref.get("name"), str) or not ref["name"] or len(ref["name"]) > 128 or ref["name"] in names:
                        raise ValidationError("child stage input names must be unique non-empty strings")
                    names.add(ref["name"])
                    if set(ref) == {"name", "root_object_id"}:
                        if ref["root_object_id"] not in inputs:
                            raise ValidationError("child stage root input is outside parent policy")
                    elif set(ref) == {"name", "producer_stage", "output_port"}:
                        if (not isinstance(ref["producer_stage"], str) or ref["producer_stage"] not in preceding
                                or not isinstance(ref["output_port"], str) or not ref["output_port"] or len(ref["output_port"]) > 255):
                            raise ValidationError("child stage producer must be an earlier declared stage and port")
                    else:
                        raise ValidationError("child stage input must name a root object or producer stage and port")
                normalized_stages.append({**stage, "target": target, "inputs": [dict(ref) for ref in declared_inputs]})
                preceding.add(name)
            policy["stages"] = normalized_stages
        if "final_publication" in value:
            final = value["final_publication"]
            if "stages" not in policy or not isinstance(final, dict) or set(final) != {"stage", "verify_stage", "verify_output_port", "effect"}:
                raise ValidationError("final_publication requires a declared stage, verify source, and effect")
            if final["stage"] != policy["stages"][-1]["name"] or final["verify_stage"] not in [stage["name"] for stage in policy["stages"][:-1]]:
                raise ValidationError("final publication must follow its declared verify stage")
            final_inputs = policy["stages"][-1]["inputs"]
            matches = [ref for ref in final_inputs if ref.get("producer_stage") == final["verify_stage"] and ref.get("output_port") == final["verify_output_port"]]
            if len(final_inputs) != 1 or len(matches) != 1:
                raise ValidationError("final publication must consume exactly one declared verify output")
            effect = final["effect"]
            if not isinstance(effect, dict) or effect.get("effect_type") != "generation.publish_v1":
                raise ValidationError("final publication requires generation.publish_v1")
            groups = effect.get("payload", {}).get("groups") if isinstance(effect.get("payload"), dict) else None
            selectors = [selector for group in groups for selector in group.get("selectors", [])] if isinstance(groups, list) and all(isinstance(group, dict) and isinstance(group.get("selectors"), list) for group in groups) else []
            if any(not isinstance(selector, dict) for selector in selectors):
                raise ValidationError("final publication effect selectors must be objects")
            if len(selectors) != 1 or selectors[0].get("output_port") != final["verify_output_port"]:
                raise ValidationError("final publication effect must select the verified output port")
            policy["final_publication"] = dict(final)
        return policy

    def _validate_discovery_grant_binding(self, policy, project, capability, digest):
        grant = policy.get("discovery_grant")
        if grant is None:
            return
        if (project is None or grant["project_id"] != project
                or grant["capability_id"] != capability or grant["capability_digest"] != digest):
            raise AuthorizationError("discovery grant does not match parent project or root capability")
        # The selected attempt is historical and explicit. Never fall back to
        # a current attempt or expand this tuple through ancestry.
        selected = self.store.conn.execute(
            "SELECT 1 FROM runs r JOIN tasks t ON t.run_id=r.id "
            "JOIN attempts a ON a.task_id=t.id "
            "WHERE r.project_id=? AND r.id=? AND t.id=? AND a.id=?",
            (project, grant["run_id"], grant["task_id"], grant["attempt_id"]),
        ).fetchone()
        if selected is None:
            raise AuthorizationError("discovery grant selected project/run/task/attempt association does not match")

    @_verified_mutation
    def create_task(self, body, *, enforce_readiness=False, _host_owned=False, _delegated_lineage=None, _delegated_stage=None, _delegated_inputs=None, _verified_publication_source=None, _recoverable_outputs=None):
        if "capability" in body or "expected_effect" in body:
            raise ValidationError("legacy task body aliases are not supported")
        capability = body.get("capability_id")
        if capability == MEDIA_IMPORT_CAPABILITY and not _host_owned:
            raise AuthorizationError("runtime media import capability is host-owned")
        digest = body.get("capability_digest", "sha256:" + hashlib.sha256(str(capability).encode()).hexdigest())
        execution_request = body.get("execution_request")
        task_spec_value = body.get("spec", {})
        if not isinstance(task_spec_value, dict):
            raise ValidationError("task spec must be an object")
        reserved = {"child_delegation", "delegated_parent", "delegated_stage", "delegated_inputs", "verified_publication_source", "input_refs", "derived_input_registry", "delegation_closed_attempt_id", "delegated_recoverable_outputs", "discovery_grant"}
        if set(task_spec_value) & reserved or set(body) & (reserved - {"child_delegation"}):
            raise ValidationError("delegation fields must use Runtime admission authority")
        if _delegated_lineage is not None and "child_delegation" in body:
            raise ValidationError("delegated children cannot delegate further")
        if isinstance(task_spec_value, dict) and (
            "execution_request" in task_spec_value
            or (
                isinstance(task_spec_value.get("spec"), dict)
                and "execution_request" in task_spec_value["spec"]
            )
        ):
            raise ValidationError("execution_request must be supplied through the first-class admission field")
        if isinstance(task_spec_value, dict) and (
            "execution_binding" in task_spec_value
            or (
                isinstance(task_spec_value.get("spec"), dict)
                and "execution_binding" in task_spec_value["spec"]
            )
        ):
            raise ValidationError("caller-supplied execution_binding is not accepted")
        if isinstance(execution_request, dict) and "execution_binding" in execution_request:
            raise ValidationError("caller-supplied execution_binding is not accepted")
        task_spec = {"input_object_ids": body.get("input_object_ids", []), "schema_version": body.get("schema_version", "1"), "capability_digest": digest, "spec": body.get("spec", {})}
        if "child_delegation" in body:
            task_spec["child_delegation"] = self._child_policy(body["child_delegation"])
            if any(object_id not in task_spec["input_object_ids"] for object_id in task_spec["child_delegation"]["input_object_ids"]):
                raise AuthorizationError("child policy root inputs must be admitted parent inputs")
            if "discovery_grant" in task_spec["child_delegation"]:
                project = self.store.get_project(body.get("project")) if body.get("project") else None
                self._validate_discovery_grant_binding(
                    task_spec["child_delegation"], project["id"] if project else None, capability, digest,
                )
            final = task_spec["child_delegation"].get("final_publication")
            if final is not None:
                project = self.store.get_project(body.get("project")) if body.get("project") else None
                if project is None:
                    raise ValidationError("final publication requires a project-scoped parent")
                self.store._validate_settlement_effect(final["effect"], project_id=project["id"])
        if _delegated_lineage is not None:
            task_spec["delegated_parent"] = dict(_delegated_lineage)
        if _recoverable_outputs is not None:
            task_spec["delegated_recoverable_outputs"] = _recoverable_outputs
        if _delegated_stage is not None:
            task_spec["delegated_stage"] = _delegated_stage
        if _delegated_inputs is not None:
            task_spec["delegated_inputs"] = list(_delegated_inputs or [])
        if _verified_publication_source is not None:
            task_spec["verified_publication_source"] = dict(_verified_publication_source)
        if "generation_intent" in body:
            if not isinstance(body["generation_intent"], dict):
                raise ValidationError("generation_intent must be an object")
            # Runtime owns transport and durability only. GEN owns the
            # meaning of this opaque producer intent and its member fields.
            task_spec[GENERATION_INTENT_STORAGE_KEY] = body["generation_intent"]
        if "required_facts" in body:
            task_spec["required_facts"] = normalize_execution_facts(body["required_facts"], field="required_facts")
        if "storage_estimate" in body:
            task_spec["storage_estimate"] = self.store._validate_storage_estimate(body["storage_estimate"])
        from .capture_validation import validate_capture
        inputs = task_spec_value.get("inputs") if isinstance(task_spec_value.get("inputs"), dict) else {}
        value = self.store.create_task(capability, task_spec, body.get("project"), body.get("idempotency_key"), body.get("settlement_effect"), digest, enforce_readiness=enforce_readiness, execution_request=execution_request,
                                       capture_validator=lambda snapshot, ref: validate_capture(self, snapshot, ref, inputs))
        return value

    def _live_delegating_parent(self, attempt_id, lease, *, identity):
        row = self.store.conn.execute("SELECT * FROM attempts WHERE id=?", (attempt_id,)).fetchone()
        self._assert_attempt_identity(row, identity)
        self._validate_attempt_lease(row, lease, self.store._current_runtime_epoch())
        task = self.store.conn.execute("SELECT * FROM tasks WHERE id=?", (row["task_id"],)).fetchone()
        if (not task or task["status"] != "running" or task["attempt_id"] != attempt_id
                or task["lease_token"] != row["lease_id"] or int(task["lease_fence"]) != int(row["fence"])
                or task["executor_id"] != row["executor_id"] or int(task["runtime_epoch"] or 0) != int(row["runtime_epoch"])):
            raise LeaseError("parent attempt is no longer live")
        if identity is not None and (self._task_requires_remote_activation(task["id"]) or isinstance(identity.get("qualified_activation"), dict)):
            # A draining activation may still finish the parent attempt captured at
            # the cutoff (_assert_attempt_identity enforced it above), so freshness
            # applies only when no drain has begun.
            activation = identity.get("qualified_activation")
            marker = self._remote_drain(activation.get("task_id"), activation.get("activation_id")) if isinstance(activation, dict) else None
            if not self._remote_activation_matches(task["id"], identity, self._trusted_execution_placement(identity), require_fresh=marker is None):
                raise AuthorizationError("parent activation is missing, expired, revoked, or foreign")
        if self.store._spec(task).get("delegated_parent") is not None:
            raise AuthorizationError("delegated children cannot delegate further")
        policy = self.store._spec(task).get("child_delegation")
        if self.store._spec(task).get("delegation_closed_attempt_id") == attempt_id:
            raise AuthorizationError("parent child authority has ended")
        if policy is None:
            raise AuthorizationError("parent task has no child delegation policy")
        policy = self._child_policy(policy)
        project = self.store.conn.execute("SELECT project_id FROM runs WHERE id=?", (task["run_id"],)).fetchone()[0]
        self._validate_discovery_grant_binding(policy, project, task["capability"], task["capability_digest"])
        return row, task, project, policy

    def _child_identity_digest(self, identity):
        if identity is None:
            raise AuthorizationError("authenticated worker identity is required")
        return sha256_bytes(canonical_json({
            "actor": identity.get("actor"),
            "placement": self._trusted_execution_placement(identity),
        }).encode())

    @_durable_mutation
    def issue_child_authority(self, attempt_id, body, *, identity):
        body = _wire_object(body, required=("lease_id", "fence", "runtime_epoch"), allowed=("lease_id", "fence", "runtime_epoch", "child", "derived_inputs"))
        _wire_string(body, "lease_id")
        _wire_integer(body, "fence")
        _wire_integer(body, "runtime_epoch", positive=True)
        row, task, project, policy = self._live_delegating_parent(attempt_id, body, identity=identity)
        recovery = self.store.placement_recovery(task["id"])
        effective_target = self.store.effective_execution_target(task["id"])
        payload = {
            "version": 1, "realm_id": self.realm["id"], "session_id": self.runtime_session_id,
            "parent_task_id": task["id"], "parent_attempt_id": attempt_id,
            "parent_lease_id": row["lease_id"], "parent_fence": int(row["fence"]),
            "runtime_epoch": int(row["runtime_epoch"]), "executor_id": row["executor_id"],
            "project_id": project, "expires_at": row["lease_expires_at"],
            "policy_digest": sha256_bytes(canonical_json(policy).encode()),
            "identity_digest": self._child_identity_digest(identity),
            "effective_target": effective_target,
            "placement_version": int(recovery.get("placement_version", 0)) if recovery else 0,
        }
        if "derived_inputs" in body or "child" in body:
            child = _wire_object(body.get("child"), required=("child_id", "capability_id", "capability_digest"), allowed=("child_id", "capability_id", "capability_digest"))
            require_idempotency_key(child["child_id"])
            capability = {key: child[key] for key in ("capability_id", "capability_digest")}
            if capability not in policy["capabilities"] or "stages" in policy:
                raise AuthorizationError("derived input child must match an unstaged declared capability")
            payload["child"] = dict(child)
            payload["derived_inputs"] = self._register_derived_inputs(
                body.get("derived_inputs", []), row, task, project, policy, body,
            )
        encoded = base64.urlsafe_b64encode(canonical_json(payload).encode()).decode().rstrip("=")
        signature = hmac.new(self._child_authority_key, encoded.encode(), hashlib.sha256).hexdigest()
        return {"authority": encoded + "." + signature, "expires_at": row["lease_expires_at"], "parent_task_id": task["id"], "parent_attempt_id": attempt_id, **({"child": payload["child"], "derived_inputs": payload["derived_inputs"]} if "child" in payload else {})}

    def _verify_derived_association(self, ref, parent, attempt, project):
        association = self.store.get_managed_output(ref["association_id"])
        provenance = association["provenance"]
        if (association["task_id"] != parent["id"] or association["attempt_id"] != attempt["id"]
                or association["project_id"] != project or association["role"] != "derived_input"
                or association["object_id"] != ref["object_id"] or association["size"] != ref["size"]
                or association["media_type"] != ref["media_type"] or association["filename"] != ref["filename"]
                or association["output_port"] != ref["output_port"] or association["durability"] != "durable"
                or association["lifecycle"]["state"] not in {"available", "promoted"}
                or provenance.get("task_id") != parent["id"] or provenance.get("attempt_id") != attempt["id"]
                or provenance.get("executor_id") != attempt["executor_id"]
                or provenance.get("fence") != int(attempt["fence"])
                or provenance.get("runtime_epoch") != int(attempt["runtime_epoch"])):
            raise AuthorizationError("derived input managed association no longer matches its receipt")
        digest = ref["object_id"].removeprefix("sha256:")
        obj = self.store.conn.execute("SELECT size, media_type FROM objects WHERE digest=?", (digest,)).fetchone()
        if (obj is None or int(obj["size"]) != ref["size"] or obj["media_type"] != ref["media_type"]
                or not self.store.conn.execute("SELECT 1 FROM project_objects WHERE project_id=? AND digest=?", (project, digest)).fetchone()):
            raise ConflictError("derived input object metadata or project association changed")
        self._verify_child_object_bytes(digest, ref["size"], label="derived input CAS object")

    def _verify_child_object_bytes(self, digest, size, *, label):
        try:
            root_fd, prefix_fd = self._cas_prefix_fds(digest, create=False)
        except OSError as exc:
            raise ConflictError(f"{label} is unavailable") from exc
        try:
            self._verify_file_at(prefix_fd, digest[2:], digest, size, label=label)
        finally:
            os.close(prefix_fd)
            os.close(root_fd)

    def _register_derived_inputs(self, inputs, attempt, parent, project, policy, lease):
        limits = policy["limits"]
        if not isinstance(inputs, list) or len(inputs) > limits["max_child_inputs"]:
            raise ValidationError("derived_inputs exceeds the child input count limit")
        if inputs and project is None:
            raise ValidationError("derived inputs require a project-scoped parent")
        spec = self.store._spec(parent)
        registry = {key: ref for key, ref in spec.get("derived_input_registry", {}).items() if ref.get("parent_attempt_id") == attempt["id"]}
        normalized = []
        for item in inputs:
            item = _wire_object(item, required=("name", "output_port", "filename", "object_id", "size", "media_type"), allowed=("name", "output_port", "filename", "object_id", "size", "media_type"))
            for key in ("name", "output_port", "media_type"):
                _wire_string(item, key)
                if len(item[key]) > 255 or any(ord(c) < 32 for c in item[key]):
                    raise ValidationError("derived input metadata is invalid")
            _canonical_execution_input_filename(item["filename"], "derived input filename")
            _wire_integer(item, "size")
            if item["size"] < 0 or item["size"] > OBJECT_MAX_BYTES or not isinstance(item["object_id"], str) or not re.fullmatch(r"sha256:[0-9a-f]{64}", item["object_id"]):
                raise ValidationError("derived input identity or size is invalid")
            normalized.append(dict(item))
        if len({item["object_id"] for item in normalized}) != len(normalized) or len({item["name"] for item in normalized}) != len(normalized):
            raise ValidationError("derived input identities and names must be unique")
        if sum(item["size"] for item in normalized) > limits["max_child_bytes"]:
            raise ValidationError("child input byte limit exceeded")
        # Budget the union before checking bytes or associating anything.
        candidate = dict(registry)
        for item in normalized:
            candidate.setdefault(item["object_id"], item)
        if len(candidate) > limits["max_derived_objects"] or sum(item["size"] for item in candidate.values()) > limits["max_derived_bytes"]:
            raise ValidationError("derived input attempt count or byte limit exceeded")
        refs = []
        for item in normalized:
            digest = item["object_id"].removeprefix("sha256:")
            if not self._is_authorized_generic_output(
                digest, item["size"], item["media_type"], name=item["name"], output_port=item["output_port"],
                filename=item["filename"], recorded_filename=item["filename"], attempt_row=attempt,
                task_row=parent, project_id=project, lease_body=lease,
            ):
                raise AuthorizationError("derived input requires this live attempt's authenticated upload receipt")
            previous = registry.get(item["object_id"])
            if previous is not None:
                if any(previous.get(key) != value for key, value in item.items()):
                    raise ConflictError("derived input was already registered with another descriptor")
                ref = previous
            else:
                obj = self.store.conn.execute("SELECT size, media_type FROM objects WHERE digest=?", (digest,)).fetchone()
                if obj is None or int(obj["size"]) != item["size"] or obj["media_type"] != item["media_type"]:
                    raise ConflictError("derived input object metadata does not match upload")
                self._verify_child_object_bytes(digest, item["size"], label="derived input CAS object")
                self.store.conn.execute("INSERT OR IGNORE INTO project_objects(project_id, digest, relation, created_at) VALUES (?, ?, 'managed', ?)", (project, digest, now()))
                output = {**item, "digest": item["object_id"], "kind": "object", "role": "derived_input", "group_key": "derived-input-" + attempt["id"], "variant_key": digest}
                association = self.store._associate_managed_outputs({"outputs": [output]}, task_id=parent["id"], attempt_id=attempt["id"], project_id=project)[0]
                ref = {**item, "association_id": association["association_id"], "parent_attempt_id": attempt["id"]}
                registry[item["object_id"]] = ref
            self._verify_derived_association(ref, parent, attempt, project)
            refs.append(ref)
        spec["derived_input_registry"] = registry
        self.store.conn.execute("UPDATE tasks SET spec_digest=? WHERE id=?", (self.store._store_spec(spec), parent["id"]))
        return refs

    def _decode_child_authority(self, token):
        if not isinstance(token, str) or len(token) > 1024 * 1024 or token.count(".") != 1:
            raise AuthorizationError("invalid child authority")
        encoded, supplied = token.split(".", 1)
        expected = hmac.new(self._child_authority_key, encoded.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(supplied, expected):
            raise AuthorizationError("invalid child authority")
        try:
            payload = json.loads(base64.urlsafe_b64decode(encoded + "=" * (-len(encoded) % 4)))
        except (ValueError, UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise AuthorizationError("invalid child authority") from exc
        if not isinstance(payload, dict) or payload.get("version") != 1 or payload.get("realm_id") != self.realm["id"] or payload.get("session_id") != self.runtime_session_id:
            raise AuthorizationError("child authority belongs to another runtime session")
        return payload

    def _delegated_stage_rows(self, project, lineage):
        """Read the already admitted siblings under the same parent fence."""
        rows = self.store.conn.execute(
            "SELECT t.id, t.status, t.attempt_id, t.spec_digest FROM tasks t "
            "JOIN runs r ON r.id=t.run_id JOIN task_specs s ON s.digest=t.spec_digest WHERE r.project_id IS ? "
            "AND json_extract(s.body_json, '$.delegated_parent.parent_attempt_id')=?",
            (project, lineage["parent_attempt_id"]),
        ).fetchall()
        stages = {}
        for row in rows:
            spec = self.store._spec(row)
            recorded = spec.get("delegated_parent")
            if not isinstance(recorded, dict) or any(recorded.get(key) != lineage[key] for key in ("parent_task_id", "parent_attempt_id", "parent_lease_id", "parent_fence", "runtime_epoch", "executor_id", "parent_placement", "parent_effective_target", "parent_placement_version", "project_id")):
                continue
            name = spec.get("delegated_stage")
            if name in stages:
                raise ConflictError("delegated stage has duplicate admissions")
            if name is not None:
                stages[name] = row
        return stages

    def _resolve_delegated_stage_inputs(self, declared, supplied, *, siblings, project, lineage):
        if not isinstance(supplied, list) or len(supplied) != len(declared):
            raise ValidationError("input_refs must match the declared stage order")
        object_ids, resolved = [], []
        for expected, ref in zip(declared, supplied):
            if not isinstance(ref, dict) or ref.get("name") != expected["name"]:
                raise ValidationError("input_refs must match the declared stage order")
            if "root_object_id" in expected:
                if set(ref) != {"name", "root_object_id"} or ref["root_object_id"] != expected["root_object_id"]:
                    raise AuthorizationError("root input is outside the declared stage policy")
                object_id = expected["root_object_id"]
                resolved.append({"name": ref["name"], "root_object_id": object_id, "object_id": object_id})
            else:
                if set(ref) != {"name", "producer_task_id", "association_id", "output_port"} or ref["output_port"] != expected["output_port"]:
                    raise AuthorizationError("producer input is outside the declared stage policy")
                producer = siblings.get(expected["producer_stage"])
                if producer is None or producer["id"] != ref["producer_task_id"] or producer["status"] != "completed":
                    raise ConflictError("declared producer stage is not settled")
                association = self.store.get_managed_output(ref["association_id"])
                if (association["task_id"] != producer["id"] or association["attempt_id"] != producer["attempt_id"]
                        or association["project_id"] != project or association["output_port"] != expected["output_port"]
                        or association["role"] == "recoverable_snapshot"
                        or association["durability"] != "durable" or association["lifecycle"]["state"] not in {"available", "promoted"}):
                    raise AuthorizationError("managed output does not match the declared live lineage and port")
                attempt = self.store.conn.execute("SELECT settled, runtime_epoch FROM attempts WHERE id=? AND task_id=?", (association["attempt_id"], producer["id"])).fetchone()
                if not attempt or not attempt["settled"] or int(attempt["runtime_epoch"]) != lineage["runtime_epoch"]:
                    raise ConflictError("producer managed output is not settled in the parent epoch")
                object_id = association["object_id"]
                resolved.append({"name": ref["name"], "producer_stage": expected["producer_stage"], "producer_task_id": producer["id"], "producer_attempt_id": producer["attempt_id"], "association_id": association["association_id"], "output_port": association["output_port"], "object_id": object_id})
            object_ids.append(object_id)
        if len(set(object_ids)) != len(object_ids):
            raise ValidationError("resolved delegated inputs must have unique object IDs")
        return object_ids, resolved

    @_durable_mutation
    def admit_delegated_child(self, body, *, idempotency_key, identity):
        body = _wire_object(body, required=("authority", "task"), allowed=("authority", "task"))
        payload = self._decode_child_authority(body["authority"])
        if payload.get("identity_digest") != self._child_identity_digest(identity):
            raise AuthorizationError("child authority is bound to another worker identity")
        lease = {"lease_id": payload.get("parent_lease_id"), "fence": payload.get("parent_fence"), "runtime_epoch": payload.get("runtime_epoch")}
        row, parent, project, policy = self._live_delegating_parent(payload.get("parent_attempt_id"), lease, identity=identity)
        recovery = self.store.placement_recovery(parent["id"])
        placement_version = int(recovery.get("placement_version", 0)) if recovery else 0
        effective_target = self.store.effective_execution_target(parent["id"])
        activation = identity.get("qualified_activation") if isinstance(identity, dict) else None
        if self._task_requires_remote_activation(parent["id"]) or isinstance(activation, dict):
            placement = self._trusted_execution_placement(identity)
            marker = self._remote_drain(parent["id"], activation.get("activation_id") if isinstance(activation, dict) else None)
            cutoff = marker.get("parent_attempt") if marker else None
            if marker is not None and (cutoff is None or any(payload.get(key) != value for key, value in cutoff.items())):
                raise AuthorizationError("child authority is outside remote drain cutoff")
            if not self._remote_activation_matches(
                parent["id"], identity, placement, require_fresh=marker is None
            ):
                raise AuthorizationError("remote activation is missing, expired, revoked, or foreign")
            if not self._activation_allows_child(parent, activation, effective_target, placement_version):
                raise AuthorizationError("qualified credential is not authorized for this child lineage")
        if (payload.get("parent_task_id") != parent["id"] or payload.get("executor_id") != row["executor_id"]
                or payload.get("project_id") != project or payload.get("expires_at") != row["lease_expires_at"]
                or payload.get("policy_digest") != sha256_bytes(canonical_json(policy).encode())
                or payload.get("effective_target") != effective_target
                or payload.get("placement_version") != placement_version):
            raise AuthorizationError("child authority no longer matches parent attempt")
        task = _wire_object(body["task"], required=("capability_id", "capability_digest"), allowed=("capability_id", "capability_digest", "input_object_ids", "input_refs", "stage", "schema_version", "spec", "execution_request", "generation_intent", "required_facts", "storage_estimate"))
        if {"capability_id": task["capability_id"], "capability_digest": task["capability_digest"]} not in policy["capabilities"]:
            raise AuthorizationError("child capability is outside parent policy")
        idempotency_key = require_idempotency_key(idempotency_key)
        stages = policy.get("stages")
        exact_child = payload.get("child")
        derived_refs = payload.get("derived_inputs", [])
        if exact_child is not None and (exact_child["child_id"] != idempotency_key
                or any(exact_child[key] != task[key] for key in ("capability_id", "capability_digest"))):
            raise AuthorizationError("derived input receipt is bound to another exact child")
        limits = policy["limits"]
        accounting = self.store.delegated_child_accounting(parent["id"], row["id"], idempotency_key=idempotency_key)
        if not accounting["replay"]:
            if accounting["lifetime"] >= limits["max_children"]:
                raise ValidationError("parent child count limit exceeded")
            if accounting["active"] >= limits["max_active_children"]:
                raise ValidationError("parent active child count limit exceeded")
        stage_name = task.get("stage")
        request = task.get("execution_request")
        if request is not None and not isinstance(request, dict):
            raise ValidationError("execution_request must be an object")
        resolved_inputs = None
        verified_source = None
        if stages is None:
            if stage_name is not None or "input_refs" in task:
                raise ValidationError("parent policy does not declare child stages")
            inputs = task.get("input_object_ids", [])
            authorized_ids = list(policy["input_object_ids"]) + [ref["object_id"] for ref in derived_refs]
            if not isinstance(inputs, list) or any(item not in authorized_ids for item in inputs):
                raise AuthorizationError("child inputs are outside parent policy")
            if len(inputs) > limits["max_child_inputs"]:
                raise ValidationError("child input count limit exceeded")
            if derived_refs:
                if [item for item in inputs if item in {ref["object_id"] for ref in derived_refs}] != [ref["object_id"] for ref in derived_refs]:
                    raise AuthorizationError("child inputs must consume the exact derived receipt")
                registry = self.store._spec(parent).get("derived_input_registry", {})
                for ref in derived_refs:
                    if registry.get(ref["object_id"]) != ref:
                        raise AuthorizationError("derived input receipt is not registered to the parent")
                    self._verify_derived_association(ref, parent, row, project)
                resolved_inputs = derived_refs
        else:
            if "input_object_ids" in task or not isinstance(stage_name, str):
                raise ValidationError("staged child requires stage and input_refs, not bare input_object_ids")
            stage_by_name = {item["name"]: (index, item) for index, item in enumerate(stages)}
            if stage_name not in stage_by_name:
                raise AuthorizationError("child stage is outside parent policy")
            index, stage = stage_by_name[stage_name]
            if {"capability_id": task["capability_id"], "capability_digest": task["capability_digest"]} != {"capability_id": stage["capability_id"], "capability_digest": stage["capability_digest"]}:
                raise AuthorizationError("child capability does not match declared stage")
            supplied_target = _normalize_execution_target(request.get("target")) if request is not None else {"kind": "default"}
            if supplied_target not in (stage["target"], effective_target):
                raise AuthorizationError("child target does not match declared stage")
            lineage_keys = {"parent_task_id": parent["id"], "parent_attempt_id": row["id"], "parent_lease_id": row["lease_id"], "parent_fence": int(row["fence"]), "runtime_epoch": int(row["runtime_epoch"]), "executor_id": row["executor_id"], "parent_placement": self._trusted_execution_placement(identity), "parent_effective_target": effective_target, "parent_placement_version": placement_version, "project_id": project}
            siblings = self._delegated_stage_rows(project, lineage_keys)
            existing = siblings.get(stage_name)
            if existing is not None:
                old_key = self.store.conn.execute("SELECT r.idempotency_key FROM runs r JOIN tasks t ON t.run_id=r.id WHERE t.id=?", (existing["id"],)).fetchone()[0]
                if old_key != idempotency_key:
                    raise ConflictError("delegated stage was already admitted")
            if any(item["name"] not in siblings or siblings[item["name"]]["status"] != "completed" for item in stages[:index]):
                raise ConflictError("delegated stages must be admitted once and completed in order")
            inputs, resolved_inputs = self._resolve_delegated_stage_inputs(stage["inputs"], task.get("input_refs"), siblings=siblings, project=project, lineage=lineage_keys)
            if len(inputs) > limits["max_child_inputs"]:
                raise ValidationError("child input count limit exceeded")
            final = policy.get("final_publication")
            if final is not None and stage_name == final["stage"]:
                verified_source = next(ref for ref in resolved_inputs if ref.get("producer_stage") == final["verify_stage"] and ref.get("output_port") == final["verify_output_port"])
        target = _normalize_execution_target(request.get("target")) if isinstance(request, dict) else {"kind": "default"}
        derived_object_ids = {ref["object_id"] for ref in (resolved_inputs or []) if "association_id" in ref}
        total_input_bytes = 0
        for object_id in inputs:
            if not isinstance(object_id, str) or not re.fullmatch(r"sha256:[0-9a-f]{64}", object_id):
                raise ValidationError("delegated input object identity is invalid")
            obj = self.store.conn.execute("SELECT size FROM objects WHERE digest=?", (object_id[7:],)).fetchone()
            if obj is None:
                raise ConflictError("delegated input object is unavailable")
            if object_id in derived_object_ids:
                total_input_bytes += int(obj["size"])
        if total_input_bytes > limits["max_child_bytes"]:
            raise ValidationError("child input byte limit exceeded")
        if target not in policy["targets"] and target != effective_target:
            raise AuthorizationError("child target is outside parent policy")
        if stages is not None and request is not None:
            if "inputs" in request:
                raise ValidationError("staged child execution_request.inputs are resolved by Runtime")
            child_spec = task.get("spec", {})
            spec_inputs = child_spec.get("inputs") if isinstance(child_spec, dict) else None
            if not isinstance(spec_inputs, dict):
                raise ValidationError("staged child spec must declare its managed input descriptors")
            canonical_inputs = []
            for ref in resolved_inputs:
                name = ref["name"]
                descriptor = spec_inputs.get(name)
                if not isinstance(descriptor, dict):
                    raise ValidationError(
                        "staged child spec is missing its managed input descriptor",
                        details={"name": name},
                    )
                supplied_object_id = descriptor.get("object_id") or descriptor.get("digest")
                if supplied_object_id != ref["object_id"]:
                    raise AuthorizationError(
                        "staged child input descriptor disagrees with the Runtime-resolved object",
                        details={"name": name},
                    )
                filename = _canonical_execution_input_filename(
                    descriptor.get("filename"),
                    f"staged child input {name!r}.filename",
                )
                required = descriptor.get("required", True)
                if type(required) is not bool:
                    raise ValidationError(
                        f"staged child input {name!r}.required must be a boolean"
                    )
                canonical = {
                    "name": name,
                    "object_id": ref["object_id"],
                    "filename": filename,
                    "required": required,
                }
                digest = descriptor.get("digest")
                if digest is not None:
                    if digest != ref["object_id"]:
                        raise AuthorizationError(
                            "staged child input descriptor digest disagrees with the Runtime-resolved object",
                            details={"name": name},
                        )
                    canonical["digest"] = digest
                canonical_inputs.append(canonical)
            request = dict(request)
            request["inputs"] = canonical_inputs
        if request is not None:
            request = dict(request)
            request["target"] = effective_target or {"kind": "default"}
        elif effective_target is not None:
            request = {"schema_version": 1, "target": effective_target}
        if derived_refs:
            if request is None:
                request = {"schema_version": 1, "target": {"kind": "default"}}
            descriptors = request.get("inputs")
            if not isinstance(descriptors, list):
                raise ValidationError("derived input child requires execution_request.inputs descriptors")
            for ref in derived_refs:
                matches = [item for item in descriptors if isinstance(item, dict) and item.get("object_id") == ref["object_id"]]
                if (len(matches) != 1 or matches[0].get("name") != ref["name"]
                        or matches[0].get("filename") != ref["filename"]
                        or matches[0].get("digest", ref["object_id"]) != ref["object_id"]):
                    raise AuthorizationError("derived execution input descriptor disagrees with its receipt")
        child_spec = task.get("spec", {})
        if not isinstance(child_spec, dict) or "runtime_dependencies" in child_spec:
            raise ValidationError("delegated child spec cannot use runtime_dependencies")
        lineage = {"parent_task_id": parent["id"], "parent_attempt_id": row["id"], "parent_lease_id": row["lease_id"], "parent_fence": int(row["fence"]), "runtime_epoch": int(row["runtime_epoch"]), "executor_id": row["executor_id"], "parent_placement": self._trusted_execution_placement(identity), "parent_effective_target": effective_target, "parent_placement_version": placement_version, "project_id": project}
        lineage["policy_digest"] = payload["policy_digest"]
        admitted = dict(task)
        admitted.pop("stage", None)
        admitted.pop("input_refs", None)
        admitted["input_object_ids"] = inputs
        if request is not None:
            admitted["execution_request"] = request
        if verified_source is not None:
            admitted["settlement_effect"] = policy["final_publication"]["effect"]
        admitted["project"] = project
        admitted["idempotency_key"] = idempotency_key
        recoverable = self._recoverable_child_grant(policy, task, lineage)
        return self.create_task(admitted, enforce_readiness=True, _delegated_lineage=lineage, _delegated_stage=stage_name, _delegated_inputs=resolved_inputs, _verified_publication_source=verified_source, _recoverable_outputs=recoverable)

    @staticmethod
    def _recoverable_child_grant(policy, task, lineage):
        grant = next((item for item in policy.get("recoverable_outputs", [])
                      if all(item[key] == task[key] for key in ("capability_id", "capability_digest"))), None)
        if grant is None:
            return None
        return {**grant, "limits": {key: policy["limits"][key] for key in (
            "max_recoverable_snapshots", "max_recoverable_bytes", "max_snapshot_bytes")},
            "parent_attempt_id": lineage["parent_attempt_id"], "policy_digest": lineage["policy_digest"]}

    @_durable_mutation
    def publish_recoverable_snapshot(self, attempt_id, body, *, idempotency_key, identity):
        """Commit an opaque child draft; this never settles either attempt."""
        body = _wire_object(body, required=("lease_id", "fence", "runtime_epoch", "revision", "output"),
                            allowed=("lease_id", "fence", "runtime_epoch", "revision", "output"))
        _wire_string(body, "lease_id")
        for key in ("fence", "runtime_epoch", "revision"):
            _wire_integer(body, key, positive=True)
        if body["revision"] > 9007199254740991:
            raise ValidationError("snapshot revision exceeds the portable integer bound")
        item = _wire_object(body["output"], required=("name", "output_port", "filename", "object_id", "size", "media_type"),
                            allowed=("name", "output_port", "filename", "object_id", "size", "media_type"))
        for key in ("name", "output_port", "media_type"):
            _wire_string(item, key)
            if len(item[key]) > 255 or any(ord(c) < 32 for c in item[key]):
                raise ValidationError("snapshot metadata is invalid")
        _canonical_execution_input_filename(item["filename"], "snapshot filename")
        _wire_integer(item, "size")
        if (item["size"] < 0 or item["size"] > OBJECT_MAX_BYTES
                or not isinstance(item["object_id"], str) or not re.fullmatch(r"sha256:[0-9a-f]{64}", item["object_id"])):
            raise ValidationError("snapshot object identity or size is invalid")
        idempotency_key = require_idempotency_key(idempotency_key)
        if identity is None:
            raise AuthorizationError("authenticated snapshot worker identity is required")
        attempt = self.store.conn.execute("SELECT * FROM attempts WHERE id=?", (attempt_id,)).fetchone()
        self._assert_attempt_identity(attempt, identity)
        # Historical fence facts remain necessary for receipt recovery, but a
        # replay does not require that the old lease or epoch is still live.
        if (not attempt or attempt["lease_id"] != body["lease_id"]
                or int(attempt["fence"]) != body["fence"] or int(attempt["runtime_epoch"]) != body["runtime_epoch"]):
            raise LeaseError("snapshot attempt fence does not match")
        task = self.store.conn.execute("SELECT * FROM tasks WHERE id=?", (attempt["task_id"],)).fetchone()
        spec = self.store._spec(task)
        project = self.store.conn.execute("SELECT project_id FROM runs WHERE id=?", (task["run_id"],)).fetchone()[0]
        kind = "attempt.recoverable_snapshot.publish"
        request_hash = sha256_bytes(canonical_json(body).encode())
        alias_kind = "attempt.recoverable_snapshot.replay"
        alias = self._command_replay(alias_kind, attempt_id, idempotency_key, request_hash, with_receipt=False)
        if alias is not None:
            return alias
        replay = self._command_replay(kind, attempt_id, idempotency_key, request_hash, project_id=project)
        if replay is not None:
            return replay
        prior = self.store.recoverable_snapshots(attempt_id=attempt_id, output_port=item["output_port"])
        same = next((a for a in prior if a["provenance"]["revision"] == body["revision"]), None)
        if same is not None:
            original_key = same["provenance"]["idempotency_key"]
            original = self._command_replay(kind, attempt_id, original_key, request_hash, project_id=project)
            # Bind an alternate replay key without another publication receipt,
            # event, association or quota charge, even after authority closes.
            return self._command_record(alias_kind, attempt_id, idempotency_key, request_hash, original, with_receipt=False)
        self._validate_attempt_lease(attempt, body, self.store._current_runtime_epoch())
        if (task["status"] != "running" or task["attempt_id"] != attempt_id
                or task["lease_token"] != body["lease_id"] or int(task["lease_fence"]) != body["fence"]
                or task["executor_id"] != attempt["executor_id"] or int(task["runtime_epoch"]) != body["runtime_epoch"]):
            raise LeaseError("snapshot producing child is no longer live")
        lineage = spec.get("delegated_parent")
        frozen = spec.get("delegated_recoverable_outputs")
        if not isinstance(lineage, dict) or not isinstance(frozen, dict) or project is None:
            raise AuthorizationError("child has no admitted recoverable output grant")
        parent_attempt, parent, parent_project, policy = self._live_delegating_parent(
            lineage["parent_attempt_id"], {"lease_id": lineage["parent_lease_id"],
            "fence": lineage["parent_fence"], "runtime_epoch": lineage["runtime_epoch"]}, identity=None)
        recovery = self.store.placement_recovery(parent["id"])
        if (parent["id"] != lineage["parent_task_id"] or parent_project != project or lineage["project_id"] != project
                or parent_attempt["executor_id"] != lineage["executor_id"]
                or self.store.effective_execution_target(parent["id"]) != lineage["parent_effective_target"]
                or int(recovery.get("placement_version", 0) if recovery else 0) != lineage["parent_placement_version"]
                or sha256_bytes(canonical_json(policy).encode()) != lineage["policy_digest"]
                or frozen != self._recoverable_child_grant(policy, {"capability_id": task["capability"],
                    "capability_digest": spec["capability_digest"]}, lineage)
                or item["output_port"] not in frozen["output_ports"]):
            raise AuthorizationError("snapshot grant or parent lineage does not match")
        if prior and body["revision"] <= max(a["provenance"]["revision"] for a in prior):
            raise ConflictError("snapshot revision is stale")
        limits = frozen["limits"]
        committed = self.store.recoverable_snapshots(parent_attempt_id=lineage["parent_attempt_id"])
        if (item["size"] > limits["max_snapshot_bytes"]
                or len(committed) >= limits["max_recoverable_snapshots"]
                or sum(a["size"] for a in committed) + item["size"] > limits["max_recoverable_bytes"]):
            raise ValidationError("recoverable snapshot count or byte limit exceeded")
        digest = item["object_id"][7:]
        if not self._is_authorized_generic_output(digest, item["size"], item["media_type"], name=item["name"],
                output_port=item["output_port"], filename=item["filename"], recorded_filename=item["filename"],
                attempt_row=attempt, task_row=task, project_id=project, lease_body=body):
            raise AuthorizationError("snapshot requires the producing child's authenticated upload receipt")
        obj = self.store.conn.execute("SELECT size, media_type FROM objects WHERE digest=?", (digest,)).fetchone()
        if obj is None or int(obj["size"]) != item["size"] or obj["media_type"] != item["media_type"]:
            raise ConflictError("snapshot object metadata does not match upload")
        self._verify_child_object_bytes(digest, item["size"], label="snapshot CAS object")
        self.store.conn.execute("INSERT OR IGNORE INTO project_objects(project_id, digest, relation, created_at) VALUES (?, ?, 'managed', ?)", (project, digest, now()))
        output = {**item, "digest": item["object_id"], "kind": "object", "role": "recoverable_snapshot",
                  "group_key": "recoverable-" + attempt_id, "variant_key": str(body["revision"]),
                  "provenance": {"parent_attempt_id": lineage["parent_attempt_id"],
                    "revision": body["revision"], "idempotency_key": idempotency_key}}
        association = self.store._associate_managed_outputs({"outputs": [output]}, task_id=task["id"],
                        attempt_id=attempt_id, project_id=project)[0]
        event = self.store._append_event(task["run_id"], task["id"], "attempt.recoverable_snapshot_published",
                        {"association_id": association["association_id"], "revision": body["revision"]})
        return self._command_record(kind, attempt_id, idempotency_key, request_hash, association,
                                    project_id=project, event_ids=(event,))

    def task(self, task_id):
        self.store.reap_overdue_leases()
        return self.store.get_task(task_id)

    def managed_outputs(self, task_id):
        """Read Runtime-owned immutable output associations and lifecycle state."""
        return self.store.list_managed_outputs(task_id)

    def managed_output_page(self, task_id):
        """Return the public task-scoped managed-output collection."""
        self.store.get_task(str(task_id))
        return {"items": self.store.list_managed_outputs(task_id), "next_cursor": None}

    def managed_output(self, association_id):
        """Read one named managed association without exposing CAS or SQLite."""
        return self.store.get_managed_output(association_id)

    def _export_source(self, association_id):
        """Resolve one retained output and validate its historical fence facts."""
        association = self.store.get_managed_output(association_id)
        if association.get("durability") != "durable":
            raise ConflictError("only durable managed outputs may be exported")
        attempt = self.store.conn.execute(
            "SELECT id, task_id, lease_id, fence, executor_id, runtime_epoch, settled FROM attempts WHERE id=?",
            (str(association["attempt_id"]),),
        ).fetchone()
        if not attempt or str(attempt["task_id"]) != str(association["task_id"]):
            raise ConflictError("managed output attempt provenance is unavailable")
        if not int(attempt["settled"]):
            raise ConflictError("managed output attempt is not completed")
        run = self.store.conn.execute(
            "SELECT id, project_id FROM runs WHERE id=?",
            (str(association["run_id"]),),
        ).fetchone()
        if not run or run["project_id"] != association.get("project_id"):
            raise ConflictError("managed output run/project provenance is inconsistent")
        provenance = association.get("provenance") or {}
        if not isinstance(provenance, dict):
            raise ConflictError("managed output provenance is malformed")
        for field, expected in (
            ("task_id", association["task_id"]),
            ("attempt_id", association["attempt_id"]),
            ("executor_id", attempt["executor_id"]),
            ("fence", int(attempt["fence"])),
            ("runtime_epoch", int(attempt["runtime_epoch"])),
        ):
            if field in provenance and provenance[field] != expected:
                raise ConflictError("managed output historical provenance is inconsistent", details={"field": field})
        if not attempt["lease_id"] or not attempt["executor_id"] or int(attempt["fence"]) < 1 or int(attempt["runtime_epoch"]) < 1:
            raise ConflictError("managed output attempt fence provenance is incomplete")
        digest = str(association["digest"])
        if not digest.startswith("sha256:"):
            raise ConflictError("managed output digest is not canonical")
        raw_digest = digest.removeprefix("sha256:")
        object_row = self.store.conn.execute(
            "SELECT size, media_type, original_name FROM objects WHERE digest=?",
            (raw_digest,),
        ).fetchone()
        if not object_row:
            raise ConflictError("managed output CAS object is unavailable")
        data = self.cas.read(raw_digest)
        if len(data) != int(association["size"]) or len(data) != int(object_row["size"]):
            raise ConflictError("managed output CAS size does not match its association")
        if str(object_row["media_type"]) != str(association["media_type"]):
            raise ConflictError("managed output media type does not match its CAS object")
        try:
            export_filename = _canonical_managed_output_filename(str(association["filename"]))
        except ValidationError as exc:
            raise ConflictError("managed output filename is not a direct safe file name") from exc
        return association, attempt, data, export_filename

    def _materialize_export(self, filename, data):
        if self.export_root is None:
            raise ConflictError("managed-output export root is not configured")
        if len(str(filename).encode("utf-8")) > self._export_leaf_max_bytes():
            raise ConflictError("managed-output export destination filename is too long")
        identity, root_fd, _ = _pin_directory(self.export_root)
        temporary = f".{filename}.{os.getpid()}-{uuid.uuid4().hex}.tmp"
        fd = -1
        try:
            fd = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0), 0o600, dir_fd=root_fd)
            view = memoryview(data)
            while view:
                written = os.write(fd, view)
                view = view[written:]
            os.fsync(fd)
            os.close(fd)
            fd = -1
            try:
                os.link(temporary, filename, src_dir_fd=root_fd, dst_dir_fd=root_fd, follow_symlinks=False)
            except FileExistsError as exc:
                raise ConflictError("managed-output export destination already exists") from exc
            os.unlink(temporary, dir_fd=root_fd)
            os.fsync(root_fd)
        finally:
            if fd >= 0:
                os.close(fd)
            try:
                os.unlink(temporary, dir_fd=root_fd)
            except FileNotFoundError:
                pass
            _close_pinned(identity)

    def _export_leaf_max_bytes(self):
        """Return the safe direct-leaf budget including the temporary file name."""
        try:
            name_max = int(os.pathconf(self.export_root, "PC_NAME_MAX"))
        except (OSError, TypeError, ValueError):
            name_max = 255
        # _materialize_export writes .<leaf>.<pid>-<uuid>.tmp before linking
        # the final leaf. Reserve the complete fixed suffix so a valid final
        # name cannot fail only because its private staging sibling is longer.
        temporary_suffix = f"..{os.getpid()}-{'0' * 32}.tmp"
        return max(1, name_max - len(temporary_suffix.encode("utf-8")))

    @staticmethod
    def _truncate_utf8(value, limit):
        raw = str(value).encode("utf-8")
        if len(raw) <= limit:
            return str(value)
        truncated = raw[:limit].decode("utf-8", "ignore")
        return truncated or "output"

    def _collision_safe_export_filename(self, association_id, filename):
        """Return a deterministic direct-leaf fallback under the export root."""
        prefix = f"{association_id}--"
        filename = str(filename)
        if filename.startswith(prefix):
            filename = filename[len(prefix):]
        counter = 1
        while True:
            suffix = "" if counter == 1 else f"--{counter}"
            available = self._export_leaf_max_bytes() - len((prefix + suffix).encode("utf-8"))
            base = self._truncate_utf8(filename, max(1, available))
            candidate = f"{prefix}{base}{suffix}"
            if not os.path.lexists(self.export_root / candidate):
                return candidate
            counter += 1

    @_durable_mutation
    def export_managed_output(self, association_id, body, *, idempotency_key=None):
        """Materialize exact CAS bytes for one completed retained output."""
        idempotency_key = require_idempotency_key(idempotency_key)
        if self.export_root is None:
            raise ConflictError("managed-output export root is not configured")
        body = _wire_object(body, required=("destination_filename",), allowed=("destination_filename", "expected"))
        destination_filename = _wire_string(body, "destination_filename")
        expected = body.get("expected") or {}
        if not isinstance(expected, dict):
            raise ValidationError("expected export identity must be an object")
        allowed_expected = {
            "project_id", "run_id", "task_id", "attempt_id", "executor_id", "lease_id", "fence",
            "runtime_epoch", "association_id", "output_port", "role", "object_id", "digest", "size",
            "filename", "media_type",
        }
        unknown = sorted(set(expected) - allowed_expected)
        if unknown:
            raise ValidationError("expected export identity contains unsupported fields", details={"fields": unknown})
        association, attempt, data, export_filename = self._export_source(association_id)
        if destination_filename not in {association["filename"], export_filename}:
            raise ConflictError("export destination filename must equal managed output filename")
        source = {
            "project_id": association.get("project_id"),
            "run_id": association["run_id"], "task_id": association["task_id"],
            "attempt_id": association["attempt_id"], "executor_id": attempt["executor_id"],
            "lease_id": attempt["lease_id"], "fence": int(attempt["fence"]),
            "runtime_epoch": int(attempt["runtime_epoch"]), "association_id": association["association_id"],
            "output_port": association["output_port"], "role": association["role"],
            "object_id": association["object_id"], "digest": association["digest"],
            "size": int(association["size"]), "filename": association["filename"],
            "media_type": association["media_type"],
        }
        for field, value in expected.items():
            if field == "filename" and value == export_filename:
                continue
            if value != source[field]:
                raise ConflictError("export identity assertion does not match", details={"field": field})
        request_hash = hashlib.sha256(canonical_json({"association_id": str(association_id), "body": body}).encode()).hexdigest()
        project_id = association.get("project_id") or "unscoped"
        replay = self._command_replay("managed_output.export", str(association_id), idempotency_key, request_hash, project_id=project_id)
        if replay is not None:
            return replay
        destination_export_filename = export_filename
        if (
            len(destination_export_filename.encode("utf-8")) > self._export_leaf_max_bytes()
            or os.path.lexists(self.export_root / destination_export_filename)
        ):
            destination_export_filename = self._collision_safe_export_filename(
                association["association_id"], export_filename
            )
        for _attempt in range(100):
            try:
                self._materialize_export(destination_export_filename, data)
                break
            except ConflictError as exc:
                if "destination already exists" not in str(exc):
                    raise
                destination_export_filename = self._collision_safe_export_filename(
                    association["association_id"], export_filename
                )
        else:
            raise ConflictError("managed-output export could not allocate a collision-safe destination")
        result = {
            "export_id": "export-" + new_id(),
            **source,
            "producer": association.get("producer") or {},
            "destination": {"root": str(self.export_root), "filename": destination_export_filename},
            "source_provenance": association.get("provenance") or {},
            "exported_at": now(),
        }
        event_id = self.store._append_event(
            association["run_id"], association["task_id"], "managed_output.exported", result,
        )
        event_seq = self.store.conn.execute("SELECT COUNT(*) FROM events WHERE run_id=?", (association["run_id"],)).fetchone()[0]
        return self._command_record(
            "managed_output.export", str(association_id), idempotency_key, request_hash,
            result, project_id=project_id, event_ids=(event_id,), primary_stream_id=association["run_id"],
            resulting_stream_seq=event_seq,
        )

    @_durable_mutation
    def adopt_managed_output(self, association_id, body=None, *, idempotency_key=None):
        """Acknowledge/adopt an existing immutable association by managed name.

        Adoption never creates a second association or resolves a filesystem
        path. Optional identity fields are equality assertions against the
        Runtime-owned association, making a changed payload a conflict while
        preserving the durable receipt for an exact retry.
        """
        idempotency_key = require_idempotency_key(idempotency_key)
        body = {} if body is None else _wire_object(body, allowed=(
            "association_id", "manifest_ref", "object_id", "digest", "size",
            "filename", "media_type", "output_port", "selector", "ordinal",
            "role", "durability",
        ))
        association = self.store.get_managed_output(association_id)
        if body.get("association_id") is not None and str(body["association_id"]) != str(association_id):
            raise ConflictError("association_id does not match the managed-output path")
        for field in (
            "manifest_ref", "object_id", "digest", "size", "filename", "media_type",
            "output_port", "selector", "ordinal", "role", "durability",
        ):
            if field in body and body[field] != association.get(field):
                raise ConflictError("managed-output adoption identity does not match", details={"field": field})
        request_hash = hashlib.sha256(canonical_json({"association_id": str(association_id), "body": body}).encode()).hexdigest()
        project_id = association.get("project_id") or "unscoped"
        replay = self._command_replay("managed_output.adopt", str(association_id), idempotency_key, request_hash, project_id=project_id)
        if replay is not None:
            return replay
        return self._command_record(
            "managed_output.adopt", str(association_id), idempotency_key, request_hash,
            association, project_id=project_id,
        )

    @_durable_mutation
    def update_managed_output_lifecycle(self, association_id, body, *, idempotency_key=None):
        """Mutate only Runtime lifecycle state for one immutable association."""
        idempotency_key = require_idempotency_key(idempotency_key)
        body = _wire_object(
            body,
            required=("operation", "expected_version"),
            allowed=("operation", "expected_version", "lease_id", "lease_owner", "lease_seconds", "provenance"),
        )
        operation = _wire_string(body, "operation")
        _wire_integer(body, "expected_version", positive=True)
        if "lease_id" in body and (not isinstance(body["lease_id"], str) or not body["lease_id"]):
            raise ValidationError("lease_id must be a non-empty string")
        if "lease_owner" in body and (not isinstance(body["lease_owner"], str) or not body["lease_owner"]):
            raise ValidationError("lease_owner must be a non-empty string")
        if "lease_seconds" in body and (
            isinstance(body["lease_seconds"], bool) or not isinstance(body["lease_seconds"], int)
            or body["lease_seconds"] <= 0
        ):
            raise ValidationError("lease_seconds must be a positive integer")
        if "provenance" in body and not isinstance(body["provenance"], dict):
            raise ValidationError("lifecycle provenance must be an object")
        association = self.store.get_managed_output(association_id)
        project_id = association.get("project_id") or "unscoped"
        request_hash = hashlib.sha256(canonical_json({"association_id": str(association_id), "body": body}).encode()).hexdigest()
        replay = self._command_replay("managed_output.lifecycle", str(association_id), idempotency_key, request_hash, project_id=project_id)
        if replay is not None:
            return replay
        result = self.store.update_managed_output_lifecycle(
            association_id, operation, expected_version=body["expected_version"],
            lease_id=body.get("lease_id"), lease_owner=body.get("lease_owner"),
            lease_seconds=body.get("lease_seconds"),
        )
        if "provenance" in body:
            result["lifecycle_provenance"] = dict(body["provenance"])
        return self._command_record(
            "managed_output.lifecycle", str(association_id), idempotency_key, request_hash,
            result, project_id=project_id,
        )

    def run(self, run_id):
        self.store.reap_overdue_leases()
        row = self.store.conn.execute("SELECT * FROM runs WHERE id=?", (run_id,)).fetchone()
        if not row:
            raise NotFoundError("run not found")
        value = dict(row)
        if value["spec_digest"] is None:
            value["spec_retired"] = True
        value["spec"], generation_intent = public_task_spec(self.store._load_spec(value.pop("spec_digest")))
        if generation_intent is not None:
            value["generation_intent"] = generation_intent
        value["task_ids"] = [task["id"] for task in self.store.conn.execute("SELECT id FROM tasks WHERE run_id=? ORDER BY created_at, id", (run_id,))]
        return value

    def _task_resource(self, value, *, progress=None, related_loaded=False):
        task, run = value["task"], value["run"]
        spec, generation_intent = public_task_spec(task.get("spec", {}))
        if task.get("generation_intent") is not None:
            generation_intent = task["generation_intent"]
        resource = {"task_id": task["id"], "run_id": run["id"], "project_id": run.get("project_id"), "state": "succeeded" if task["status"] == "completed" else ("cancelled" if task["status"] == "cancelled" else task["status"]), "version": int(task.get("attempt", 0)) + 1, "capability_id": task["capability"], "capability_digest": task.get("capability_digest") or spec.get("capability_digest", "sha256:" + hashlib.sha256(task["capability"].encode()).hexdigest()), "schema_version": spec.get("schema_version", "1"), "input_object_ids": spec.get("input_object_ids", []), "spec": spec, "idempotency_key": run.get("idempotency_key") or task["id"], "created_at": task["created_at"], "updated_at": task["updated_at"], "attempt_id": task.get("attempt_id"), "runtime_epoch": int(task.get("runtime_epoch") or self.store._current_runtime_epoch())}
        if task.get("execution_request") is not None:
            resource["execution_request"] = dict(task["execution_request"])
        binding = value.get("execution_binding")
        if binding is None and not related_loaded:
            binding = self.store.execution_binding(task["id"])
        if binding is not None:
            resource["execution_binding"] = binding
        if generation_intent is not None:
            resource["generation_intent"] = generation_intent
        if task.get("expected_effect") is not None:
            resource["expected_effect"] = dict(task["expected_effect"])
        if "required_facts" in spec:
            resource["required_facts"] = dict(spec["required_facts"])
        if "storage_estimate" in spec:
            resource["storage_estimate"] = dict(spec["storage_estimate"])
        if task.get("waiting_reason"):
            resource["waiting_reason"] = task["waiting_reason"]
        if task.get("lease_fence"):
            resource["lease_fence"] = task["lease_fence"]
        if task.get("lease_expires_at"):
            resource["lease_expires_at"] = task["lease_expires_at"]
        if task.get("result") is not None:
            resource["result"] = task["result"]
        if not related_loaded:
            row = self.store.conn.execute(
                "SELECT payload_json FROM events WHERE task_id=? AND kind='task.progress' ORDER BY id DESC LIMIT 1",
                (task["id"],),
            ).fetchone()
            progress = json.loads(row["payload_json"]) if row else None
        if isinstance(progress, dict):
            resource["progress"] = progress
        return resource

    @staticmethod
    def _require_placement_recovery_owner(identity):
        scopes = set(identity.get("scopes", [])) if isinstance(identity, dict) else set()
        actor = identity.get("actor") if isinstance(identity, dict) else None
        if not isinstance(actor, str) or not actor or "admin" not in scopes:
            raise AuthorizationError("placement recovery requires owner authority")
        return actor

    @staticmethod
    def _placement_evidence_digest(value, field):
        if not isinstance(value, str) or not re.fullmatch(r"sha256:[0-9a-f]{64}", value):
            raise ValidationError(f"{field} must be a sha256 digest")
        return value

    def _validate_placement_loss_evidence(self, value, *, current_target):
        value = _wire_object(
            value,
            required=(
                "source", "status", "target", "observed_at",
                "evidence_digest", "no_active_work",
            ),
            allowed=(
                "source", "status", "target", "observed_at",
                "evidence_digest", "no_active_work",
            ),
        )
        if not isinstance(value["source"], str) or not value["source"].strip():
            raise ValidationError("loss_evidence.source is required")
        if value["status"] != "absent":
            raise ConflictError("old placement loss is not established")
        if value["no_active_work"] is not True:
            raise ConflictError("old placement has unknown active work")
        target = _normalize_execution_target(value["target"])
        if target != current_target:
            raise ConflictError(
                "loss evidence does not match the current effective placement",
                details={"expected": current_target, "actual": target},
            )
        observed_at = value["observed_at"]
        if not isinstance(observed_at, str) or not observed_at:
            raise ValidationError("loss_evidence.observed_at is required")
        try:
            observed = datetime.fromisoformat(observed_at.replace("Z", "+00:00"))
        except ValueError as exc:
            raise ValidationError("loss_evidence.observed_at is invalid") from exc
        if observed.tzinfo is None:
            raise ValidationError("loss_evidence.observed_at must include a timezone")
        age = (datetime.now(timezone.utc) - observed.astimezone(timezone.utc)).total_seconds()
        if age < -60 or age > PLACEMENT_LOSS_EVIDENCE_MAX_AGE_SECONDS:
            raise ConflictError(
                "loss evidence is stale",
                details={"maximum_age_seconds": PLACEMENT_LOSS_EVIDENCE_MAX_AGE_SECONDS},
            )
        return {
            "source": value["source"].strip(),
            "status": "absent",
            "target": target,
            "observed_at": observed_at,
            "evidence_digest": self._placement_evidence_digest(
                value["evidence_digest"], "loss_evidence.evidence_digest"
            ),
            "no_active_work": True,
        }

    def _validate_replacement_qualification(self, value, *, replacement_target):
        value = _wire_object(
            value,
            required=("target", "verified", "evidence_digest", "executor_incarnation"),
            allowed=("target", "verified", "evidence_digest", "executor_incarnation"),
        )
        target = _normalize_execution_target(value["target"])
        if target != replacement_target:
            raise ConflictError(
                "replacement qualification targets a different placement",
                details={"expected": replacement_target, "actual": target},
            )
        if value["verified"] is not True:
            raise AuthorizationError("replacement placement is not qualified")
        incarnation = value["executor_incarnation"]
        if not isinstance(incarnation, str) or not incarnation.strip() or len(incarnation) > 256:
            raise ValidationError("qualification.executor_incarnation is invalid")
        return {
            "target": target,
            "verified": True,
            "evidence_digest": self._placement_evidence_digest(
                value["evidence_digest"], "qualification.evidence_digest"
            ),
            "executor_incarnation": incarnation.strip(),
        }

    def _delegated_children(self, parent_task_id):
        children = []
        for row in self.store.conn.execute(
            "SELECT id, run_id, status, waiting_reason, attempt_id, spec_digest "
            "FROM tasks ORDER BY rowid"
        ).fetchall():
            try:
                lineage = self.store._spec(row).get("delegated_parent")
            except (TypeError, json.JSONDecodeError):
                continue
            if isinstance(lineage, dict) and lineage.get("parent_task_id") == parent_task_id:
                children.append((row, lineage))
        return children

    def _assert_placement_recovery_quiescent(self, task, children):
        if task["status"] not in {"failed", "cancelled"}:
            raise ConflictError(
                "task must be terminal before placement recovery",
                details={"status": task["status"]},
            )
        if task["waiting_reason"] == "provider_state_unknown":
            raise ConflictError("old placement has unknown active work")
        unsettled = self.store.conn.execute(
            "SELECT id FROM attempts WHERE task_id=? AND settled=0 ORDER BY rowid",
            (task["id"],),
        ).fetchall()
        if unsettled:
            raise ConflictError(
                "old placement has unknown active work",
                details={"attempt_ids": [row["id"] for row in unsettled]},
            )
        if self.store.conn.execute(
            "SELECT 1 FROM reservations WHERE task_id=? AND released_at IS NULL LIMIT 1",
            (task["id"],),
        ).fetchone():
            raise ConflictError("old placement still owns an active reservation")
        binding = self.store.execution_binding(task["id"])
        if binding is None:
            raise ConflictError("task has no targeted execution binding")
        if binding["status"] == "claimed":
            raise ConflictError("old placement still has a claimed execution binding")
        for child, _lineage in children:
            child_unsettled = self.store.conn.execute(
                "SELECT id FROM attempts WHERE task_id=? AND settled=0 ORDER BY rowid",
                (child["id"],),
            ).fetchall()
            child_binding = self.store.execution_binding(child["id"])
            if (
                child["status"] in {"running", "cancel_requested"}
                or child["waiting_reason"] == "provider_state_unknown"
                or child_unsettled
                or (child_binding is not None and child_binding["status"] == "claimed")
                or self.store.conn.execute(
                    "SELECT 1 FROM reservations WHERE task_id=? AND released_at IS NULL LIMIT 1",
                    (child["id"],),
                ).fetchone()
            ):
                raise ConflictError(
                    "delegated child has unknown active work",
                    details={"child_task_id": child["id"]},
                )
        return binding

    @_durable_mutation
    def recover_task_placement(self, task_id, body, *, idempotency_key=None, identity=None):
        """Authorize one exact effective-placement revision without rewriting admission."""
        actor = self._require_placement_recovery_owner(identity)
        idempotency_key = require_idempotency_key(idempotency_key)
        body = _wire_object(
            body,
            required=(
                "schema_version", "expected_task_version", "expected_placement_version",
                "expected_original_target", "expected_current_target", "replacement_target",
                "reason", "loss_evidence", "qualification",
            ),
            allowed=(
                "schema_version", "expected_task_version", "expected_placement_version",
                "expected_original_target", "expected_current_target", "replacement_target",
                "reason", "loss_evidence", "qualification",
            ),
        )
        if body["schema_version"] != PLACEMENT_RECOVERY_SCHEMA_VERSION:
            raise ValidationError("placement recovery schema_version is unsupported")
        for field in ("expected_task_version", "expected_placement_version"):
            if isinstance(body[field], bool) or not isinstance(body[field], int) or body[field] < 0:
                raise ValidationError(f"{field} must be a non-negative integer")
        reason = body["reason"]
        if not isinstance(reason, str) or not reason.strip() or len(reason) > 1024:
            raise ValidationError("placement recovery reason is invalid")
        request_hash = hashlib.sha256(
            canonical_json({"task_id": str(task_id), "body": body}).encode()
        ).hexdigest()
        current = self.store.get_task(task_id)
        project_id = current["run"].get("project_id") or "unscoped"
        replay = self._command_replay(
            "task.placement_recover", str(task_id), idempotency_key, request_hash,
            project_id=project_id,
        )
        if replay is not None:
            return replay
        task = self.store.conn.execute("SELECT * FROM tasks WHERE id=?", (str(task_id),)).fetchone()
        request = self.store._execution_request_from_row(task)
        if request is None:
            raise ConflictError("placement recovery requires a targeted task")
        original_target = _normalize_execution_target(body["expected_original_target"])
        if original_target != request["target"]:
            raise ConflictError("original immutable placement does not match admission")
        latest = self.store.placement_recovery(task_id)
        placement_version = int(latest.get("placement_version", 0)) if latest else 0
        current_target = self.store.effective_execution_target(task_id)
        expected_current = _normalize_execution_target(body["expected_current_target"])
        if expected_current != current_target:
            raise ConflictError(
                "current effective placement changed",
                details={"expected": expected_current, "actual": current_target},
            )
        if body["expected_placement_version"] != placement_version:
            raise ConflictError(
                "stale placement version",
                details={"expected": body["expected_placement_version"], "actual": placement_version},
            )
        task_version = int(task["attempt"] or 0) + 1
        if body["expected_task_version"] != task_version:
            raise ConflictError(
                "stale task version",
                details={"expected": body["expected_task_version"], "actual": task_version},
            )
        replacement = _normalize_execution_target(body["replacement_target"])
        if current_target.get("kind") != "runpod" or replacement.get("kind") != "runpod":
            raise ValidationError("placement recovery currently supports exact RunPod targets")
        if replacement["provider_account_ref"] != current_target["provider_account_ref"]:
            raise AuthorizationError("replacement target belongs to a different provider account")
        if replacement == current_target:
            raise ConflictError("replacement target must differ from the lost placement")
        loss = self._validate_placement_loss_evidence(
            body["loss_evidence"], current_target=current_target
        )
        qualification = self._validate_replacement_qualification(
            body["qualification"], replacement_target=replacement
        )
        children = self._delegated_children(str(task_id))
        binding = self._assert_placement_recovery_quiescent(task, children)
        timestamp = now()
        decision = {
            "schema_version": PLACEMENT_RECOVERY_SCHEMA_VERSION,
            "placement_version": placement_version + 1,
            "task_id": str(task_id),
            "run_id": current["run"]["id"],
            "task_version": task_version,
            "original_target": request["target"],
            "previous_effective_target": current_target,
            "replacement_target": replacement,
            "reason": reason.strip(),
            "owner_actor": actor,
            "loss_evidence": loss,
            "qualification": qualification,
            "superseded_binding": {
                "binding_id": binding["binding_id"],
                "attempt_id": binding.get("attempt_id"),
                "lease_id": binding.get("lease_id"),
                "fence": int(binding.get("fence") or 0),
                "executor_id": binding.get("executor_id"),
                "executor_incarnation": binding.get("executor_incarnation"),
            },
            "created_at": timestamp,
        }
        decision["decision_digest"] = "sha256:" + sha256_bytes(
            canonical_json(decision).encode()
        )
        event_ids = []
        for child, lineage in children:
            if child["status"] == "queued":
                self.store.conn.execute(
                    "UPDATE tasks SET status='cancelled', waiting_reason='parent_placement_recovered', "
                    "lease_token=NULL, executor_id=NULL, lease_expires_at=NULL, updated_at=? WHERE id=?",
                    (timestamp, child["id"]),
                )
                self.store.conn.execute(
                    "UPDATE runs SET status='cancelled', updated_at=? WHERE id=?",
                    (timestamp, child["run_id"]),
                )
                self.store.conn.execute(
                    "UPDATE execution_bindings SET status='stale', updated_at=? "
                    "WHERE task_id=? AND status='prepared'",
                    (timestamp, child["id"]),
                )
            event_ids.append(self.store._append_event(
                child["run_id"], child["id"], "task.parent_placement_fenced",
                {
                    "parent_task_id": str(task_id),
                    "parent_attempt_id": lineage.get("parent_attempt_id"),
                    "placement_version": placement_version + 1,
                    "replacement_target": replacement,
                },
            ))
        updated = self.store.conn.execute(
            "UPDATE execution_bindings SET attempt_id=NULL, lease_id=NULL, fence=0, "
            "executor_id=NULL, session_id=(SELECT boot_id FROM runtime_lifecycle WHERE id=1), "
            "runtime_epoch=?, resolved_target_json=?, status='prepared', updated_at=? "
            "WHERE task_id=? AND status IN ('prepared', 'released', 'stale')",
            (
                self.store._current_runtime_epoch(),
                canonical_json({"selected": replacement}),
                timestamp,
                str(task_id),
            ),
        )
        if updated.rowcount != 1:
            raise ConflictError("execution binding changed during placement recovery")
        self.store.conn.execute(
            "UPDATE tasks SET updated_at=? WHERE id=?", (timestamp, str(task_id))
        )
        parent_event = self.store._append_event(
            current["run"]["id"], str(task_id), "task.placement_recovered", decision
        )
        event_ids.append(parent_event)
        previous_activation = self._latest_remote_activation(task_id)
        if previous_activation is not None:
            event_ids.append(self.store._append_event(
                current["run"]["id"], str(task_id), "task.remote_activation_revoked",
                {"activation_id": previous_activation["activation_id"],
                 "reason": "placement_recovered", "revoked_at": timestamp},
            ))
        result = {
            "task": self._task_resource(self.store.get_task(task_id)),
            "placement_recovery": decision,
        }
        event_seq = self.store.conn.execute(
            "SELECT COUNT(*) FROM events WHERE run_id=?", (current["run"]["id"],)
        ).fetchone()[0]
        return self._command_record(
            "task.placement_recover", str(task_id), idempotency_key, request_hash, result,
            project_id=project_id, event_ids=event_ids,
            primary_stream_id=current["run"]["id"], resulting_stream_seq=event_seq,
            created_at=timestamp,
        )

    @_verified_mutation
    def cancel(self, task_id):
        return self.store.cancel_task(task_id)

    @_verified_mutation
    def cancel_task_canonical(self, task_id, body=None, *, idempotency_key=None):
        idempotency_key = require_idempotency_key(idempotency_key)
        body = {} if body is None else body
        self._require_object_body(body)
        with self.store._mutex:
            current = self.store.get_task(task_id)
            project_id = current["run"].get("project_id") or "unscoped"
            request_hash = hashlib.sha256(canonical_json({"task_id": task_id, "body": body}).encode()).hexdigest()
            replay = self._command_replay("task.cancel", task_id, idempotency_key, request_hash, project_id=project_id)
            if replay is not None:
                return replay
            expected = body.get("expected_version")
            if expected is not None and int(expected) != int(current["task"].get("attempt", 0)) + 1:
                raise ConflictError("stale task version", details={"expected": expected, "actual": int(current["task"].get("attempt", 0)) + 1})
            with self.store._transaction():
                recorded = None
                def record(value, *, event_ids=(), primary_stream_id=None, resulting_stream_seq=None):
                    nonlocal recorded
                    recorded = self._command_record("task.cancel", task_id, idempotency_key, request_hash, self._task_resource(value), project_id=project_id, event_ids=event_ids, primary_stream_id=primary_stream_id, resulting_stream_seq=resulting_stream_seq)
                self.store.cancel_task(task_id, record=record)
                return recorded

    @_verified_mutation
    def retry_task(self, task_id, body=None, *, idempotency_key=None):
        idempotency_key = require_idempotency_key(idempotency_key)
        body = {} if body is None else body
        self._require_object_body(body)
        with self.store._mutex:
            current = self.store.get_task(task_id)
            project_id = current["run"].get("project_id") or "unscoped"
            request_hash = hashlib.sha256(canonical_json({"task_id": task_id, "body": body}).encode()).hexdigest()
            replay = self._command_replay("task.retry", task_id, idempotency_key, request_hash, project_id=project_id)
            if replay is not None:
                return replay
            if self._task_drain(task_id) is not None:
                raise ConflictError("remote drain blocks fresh task retries")
            status = current["task"]["status"]
            if current["task"].get("waiting_reason") == "provider_state_unknown":
                raise ConflictError(
                    "provider/executor state must be reconciled by authorized checkpoint resume before retry",
                    details={"status": status, "attempt_id": current["task"].get("attempt_id")},
                )
            if status not in {"completed", "cancelled", "failed"}:
                raise ConflictError("task is not retryable", details={"status": status})
            expected = (body or {}).get("expected_version")
            version = int(current["task"].get("attempt", 0)) + 1
            if expected is not None and int(expected) != version:
                raise ConflictError("stale task version", details={"expected": expected, "actual": version})
            with self.store._transaction():
                timestamp = now()
                self.store.assert_delegated_retry_capacity(task_id)
                self.store._release_reservations(task_id, current["task"].get("lease_token"))
                # A retry is a new queue admission attempt for the same
                # immutable task/request.  Keep the task id, spec, and input
                # objects stable, but reset the queue-age anchor so a prior
                # failed wait cannot make every retry fail before execution.
                self.store.conn.execute("UPDATE tasks SET status='queued', lease_token=NULL, executor_id=NULL, lease_expires_at=NULL, waiting_reason=NULL, result_json=NULL, attempt_id=NULL, created_at=?, updated_at=? WHERE id=?", (timestamp, timestamp, task_id))
                self.store.reset_execution_attempt(task_id)
                self.store.conn.execute("UPDATE runs SET status='queued', updated_at=? WHERE id=?", (timestamp, current["run"]["id"]))
                event_id = self.store._append_event(current["run"]["id"], task_id, "task.retried", {"from_status": status, "attempt": version})
                self.store._refresh_continuations_for_predecessor(task_id)
                result = self._task_resource(self.store.get_task(task_id))
                event_seq = self.store.conn.execute("SELECT COUNT(*) FROM events WHERE run_id=?", (current["run"]["id"],)).fetchone()[0]
                return self._command_record("task.retry", task_id, idempotency_key, request_hash, result, project_id=project_id, event_ids=(event_id,), primary_stream_id=current["run"]["id"], resulting_stream_seq=event_seq)

    def events(self, run_id):
        return self.store.list_events(run_id)

    @_verified_mutation
    def cancel_run(self, run_id, body=None, *, idempotency_key=None):
        return self._run_resource(self.store.cancel_run(run_id, idempotency_key=idempotency_key))

    @_verified_mutation
    def retry_run(self, run_id, body=None, *, idempotency_key=None):
        body = body or {}
        return self._run_resource(self.store.retry_run(run_id, selected_task_ids=body.get("selected_task_ids"), idempotency_key=idempotency_key))

    def _run_resource(self, value):
        result = dict(value)
        if result["spec_digest"] is None:
            result["spec_retired"] = True
        result["spec"], generation_intent = public_task_spec(self.store._load_spec(result.pop("spec_digest")))
        if generation_intent is not None:
            result["generation_intent"] = generation_intent
        result["task_ids"] = [task["id"] for task in self.store.conn.execute("SELECT id FROM tasks WHERE run_id=? ORDER BY created_at, id", (result["id"],))]
        return result

    def list_capabilities(self, *, cursor=None, limit=PAGE_DEFAULT_LIMIT):
        # Registration updates capability descriptors and executor visibility
        # in one transaction. Readers share the same fence so the HTTP catalog
        # cannot observe the transaction halfway through.
        with self.store._mutex:
            rows = self.store.conn.execute("SELECT * FROM capabilities ORDER BY id").fetchall()
            return _page_rows(rows, scope="capabilities", cursor=cursor, limit=limit,
                              key_fn=lambda row: (str(row["id"]),),
                              resource_fn=lambda r: self._capability_resource(r))

    def _capability_resource(self, row):
        status = row["status"]
        reason = row["unavailable_reason"]
        if status == "ready" and not self.store.matching_live_executor(row["id"], row["definition_digest"]):
            status, reason = "unavailable", "no_live_matching_executor"
        return {"capability_id": row["id"], "definition_digest": row["definition_digest"], "status": status, "required_resource_keys": json.loads(row["required_resource_keys_json"]), "estimated_scratch_bytes": row["estimated_scratch_bytes"], "estimated_output_bytes": row["estimated_output_bytes"], "unavailable_reason": reason}

    @_verified_mutation
    def register_capability(self, body):
        value = self.store.register_capability(body.get("capability_id", ""), body.get("definition_digest", ""), required_resource_keys=body.get("required_resource_keys", []), status=body.get("status", "ready"), unavailable_reason=body.get("unavailable_reason"), estimated_scratch_bytes=body.get("estimated_scratch_bytes", 0), estimated_output_bytes=body.get("estimated_output_bytes", 0))
        # Registration acknowledges the executor's declared state. Discovery
        # computes liveness-aware availability via ``_capability_resource``.
        return {"capability_id": value["id"], "definition_digest": value["definition_digest"], "status": value["status"], "required_resource_keys": value["required_resource_keys"], "estimated_scratch_bytes": value["estimated_scratch_bytes"], "estimated_output_bytes": value["estimated_output_bytes"], "unavailable_reason": value.get("unavailable_reason")}

    @_durable_mutation
    def register_executor(self, body, *, idempotency_key=None, identity=None):
        body = _wire_object(
            body,
            allowed=(
                "executor_id", "max_concurrency", "resource_keys", "capabilities",
                "protocol", "readiness", "readiness_reason", "runtime_epoch",
                "source_digest", "dependency_digest", "source_epoch", "schema_digest",
                "verified_facts",
            ),
        )
        executor_id = _wire_string(body, "executor_id")
        self._assert_executor_identity(identity, executor_id)
        self._assert_local_claim_admission(executor_id, identity=identity, registration=True)
        max_concurrency = body.get("max_concurrency", 1)
        if isinstance(max_concurrency, bool) or not isinstance(max_concurrency, int) or max_concurrency < 1:
            raise ValidationError("max_concurrency must be positive")
        capabilities = body.get("capabilities", [])
        if not isinstance(capabilities, list):
            raise ValidationError("capabilities must be a list")
        resource_keys = body.get("resource_keys", [])
        if not isinstance(resource_keys, list):
            raise ValidationError("resource_keys must be a list")
        protocol = body.get("protocol", "workspace.v1")
        if not isinstance(protocol, str) or protocol != "workspace.v1":
            raise ValidationError("protocol must be workspace.v1")
        readiness = body.get("readiness", "ready")
        if readiness not in {"ready", "not_ready"}:
            raise ValidationError("readiness must be ready or not_ready")
        if body.get("runtime_epoch") is not None:
            _wire_integer(body, "runtime_epoch", positive=True)
        for field in ("source_digest", "dependency_digest", "source_epoch"):
            if body.get(field) is not None:
                _wire_string(body, field)
        if body.get("schema_digest") is not None:
            if not isinstance(body["schema_digest"], str) or body["schema_digest"] != SCHEMA_DIGEST:
                raise ValidationError("schema_digest does not match the runtime contract")
        verified_facts = normalize_execution_facts(body["verified_facts"], field="verified_facts") if "verified_facts" in body else None
        request_hash = hashlib.sha256(canonical_json(body).encode()).hexdigest()
        # Executor registration is an endpoint-scoped command.  The request
        # hash includes executor identity and all registration fields, so a
        # reused key can only replay the exact durable result.
        aggregate_id = "executors"
        existing = self.store.conn.execute("SELECT runtime_epoch FROM executors WHERE id=?", (body["executor_id"],)).fetchone()
        current_epoch = self.store._current_runtime_epoch()
        if body.get("runtime_epoch") is not None:
            self.store._validate_runtime_epoch(
                body.get("runtime_epoch"), identity="executor",
                identity_id=body.get("executor_id"), required=True,
            )
        prior = None
        if idempotency_key is not None:
            validate_idempotency_key(idempotency_key)
            prior = self.store.conn.execute(
                "SELECT request_hash, result_json, created_at FROM session_command_replay "
                "WHERE command_kind='executor.register' AND aggregate_id=? AND idempotency_key=?",
                (aggregate_id, idempotency_key),
            ).fetchone()
        if prior:
            if prior["request_hash"] != request_hash:
                raise ConflictError("idempotency key was already used with different input")
            replay = command_result(prior["result_json"], kind="executor.register", connection=self.store.conn, created_at=prior["created_at"], window_seconds=SESSION_IDEMPOTENCY_WINDOW_SECONDS)
            # A replay is safe only in the same runtime session.  In
            # particular, do not let a pre-restart registration refresh a
            # dead executor lease merely because its key is known.
            if int(replay.get("runtime_epoch") or 0) != current_epoch:
                self.store._validate_runtime_epoch(
                    body.get("runtime_epoch"), identity="executor",
                    identity_id=body.get("executor_id"), required=True,
                )
            return replay
        # Re-registration is the canonical reconnect path after a runtime
        # restart or a deliberate capability/readiness refresh.  The bearer
        # fence above binds the caller to this executor (or an administrator),
        # while an existing identity must present the current runtime epoch.
        epoch = self.store._validate_runtime_epoch(
            body.get("runtime_epoch"), identity="executor",
            identity_id=body.get("executor_id"), required=existing is not None,
        )
        registered = self.store.upsert_executor(body["executor_id"], capabilities, max_concurrency, body.get("resource_keys", []), protocol=body.get("protocol", "workspace.v1"), readiness=body.get("readiness", "ready"), readiness_reason=body.get("readiness_reason"), runtime_epoch=epoch, source_digest=body.get("source_digest"), dependency_digest=body.get("dependency_digest"), source_epoch=body.get("source_epoch"), verified_facts=verified_facts)
        result = {"executor_id": body["executor_id"], "max_concurrency": max_concurrency, "resource_keys": body.get("resource_keys", []), "capabilities": registered["capabilities"], "protocol": body.get("protocol", "workspace.v1"), "readiness": body.get("readiness", "ready"), "runtime_epoch": epoch, "source_digest": body.get("source_digest"), "dependency_digest": body.get("dependency_digest"), "source_epoch": body.get("source_epoch")}
        if verified_facts is not None:
            result["verified_facts"] = verified_facts
        return self._command_record("executor.register", aggregate_id, idempotency_key, request_hash, result, project_id="unscoped", with_receipt=False)

    def executor_observation(self, executor_id, *, identity):
        """Return one exact registered executor for owner-side observation."""
        if self._require_placement_recovery_owner(identity) != "owner":
            raise AuthorizationError("executor observation requires the Runtime owner")
        if not isinstance(executor_id, str) or not executor_id:
            raise ValidationError("executor_id is required")
        with self.store._mutex:
            row = self.store.conn.execute("SELECT * FROM executors WHERE id=?", (executor_id,)).fetchone()
            if row is None:
                raise NotFoundError("executor not found")
            value = self.store._executor_result(row)
            value["executor_id"] = value.pop("id")
            value["runtime_session_id"] = self.runtime_session_id
            return {key: value[key] for key in (
                "executor_id", "max_concurrency", "resource_keys", "capabilities",
                "protocol", "runtime_epoch", "readiness", "readiness_reason",
                "last_seen_at", "source_digest", "dependency_digest", "source_epoch",
                "runtime_session_id",
            ) if key in value} | ({"verified_facts": value["verified_facts"]} if "verified_facts" in value else {})

    @_durable_mutation
    def claim_next(self, body, *, idempotency_key=None, identity=None):
        """Atomically select, claim, fence, and record a canonical claim.

        A claim has no task path, so its command aggregate is the endpoint's
        claim namespace.  The request hash binds executor, capabilities, and
        runtime epoch; a replay can never consume a second queued task.
        """
        _require_runtime_epoch_for_lease(body)
        body = _wire_object(
            body,
            required=("executor_id", "capability_ids", "runtime_epoch"),
            allowed=("executor_id", "capability_ids", "runtime_epoch", "target"),
        )
        executor_id = _wire_string(body, "executor_id")
        capability_ids = body.get("capability_ids")
        runtime_epoch = body.get("runtime_epoch")
        self._assert_executor_identity(identity, executor_id)
        self._assert_local_claim_admission(executor_id, identity=identity)
        if not isinstance(capability_ids, list) or any(not isinstance(value, str) or not value for value in capability_ids) or len(set(capability_ids)) != len(capability_ids):
            raise ValidationError("capability_ids must be a list of unique non-empty strings")
        _wire_integer(body, "runtime_epoch", positive=True)
        requested_target = None
        if body.get("target") is not None:
            requested_target = _normalize_execution_target(body["target"])
        trusted_placement = self._trusted_execution_placement(identity)
        request_hash = hashlib.sha256(canonical_json({
            "executor_id": executor_id, "capability_ids": capability_ids,
            "runtime_epoch": runtime_epoch, "target": requested_target,
            "trusted_execution_placement": trusted_placement,
        }).encode()).hexdigest()
        # Epoch validation intentionally precedes the idempotency lookup: a
        # stale worker must never turn an old claim receipt into a live lease.
        epoch = self.store._validate_runtime_epoch(runtime_epoch, identity="executor", identity_id=executor_id, required=True)
        replayed, replay = self._command_replay_state(
            "task.claim", "claim", idempotency_key, request_hash, with_receipt=False,
        )
        if replayed:
            if isinstance(replay, dict) and replay.get("task_id"):
                replay_capability = self.store.conn.execute(
                    "SELECT capability FROM tasks WHERE id=?", (replay["task_id"],)
                ).fetchone()
                qualified_identity = (
                    isinstance(identity, dict)
                    and isinstance(identity.get("qualified_activation"), dict)
                )
                if (replay_capability is not None and (
                        self._task_requires_remote_activation(replay["task_id"])
                        or qualified_identity
                    )
                        and not self._remote_activation_matches(
                            replay["task_id"], identity, trusted_placement,
                            require_fresh=not bool(replay.get("attempt_id")),
                        )):
                    raise AuthorizationError("remote activation is missing, revoked, or stale")
            return replay
        # Reap before selecting work. Otherwise an expired running task is
        # invisible to the queued-task query and reclaim waits for another
        # claim attempt.
        self.store._reap_expired_leases()
        caps = set(capability_ids)
        rows = self.store.conn.execute(
            "SELECT id, capability, execution_request_json, spec_digest, waiting_reason "
            "FROM tasks WHERE status='queued' ORDER BY rowid"
        ).fetchall()
        row = None
        selected_binding = None
        for item in rows:
            if caps and item["capability"] not in caps:
                continue
            binding = self.store.execution_binding(item["id"])
            targeted_request = self.store._execution_request_from_row(item)
            targeted = targeted_request is not None
            if targeted:
                if binding is None or requested_target is None:
                    continue
                if canonical_json(binding["resolved_target"]) != canonical_json(requested_target):
                    continue
                selected_binding = binding
            row = item
            break
        if row is None:
            # Persist the empty outcome too.  Otherwise a retry after another
            # task is admitted would silently claim new work.
            return self._command_record("task.claim", "claim", idempotency_key, request_hash, None, project_id="unscoped", with_receipt=False)
        if row["waiting_reason"] == "provider_state_unknown":
            value = self.store.get_task(row["id"])
            result = {
                "task": self._task_resource(value),
                "waiting_reason": "provider_state_unknown",
            }
            return self._command_record(
                "task.claim", "claim", idempotency_key, request_hash, result,
                project_id="unscoped", with_receipt=False,
            )
        qualified_identity = (
            isinstance(identity, dict)
            and isinstance(identity.get("qualified_activation"), dict)
        )
        if selected_binding is not None or qualified_identity:
            if trusted_placement is None:
                reason = "execution_binding_missing"
            elif selected_binding is None:
                reason = "execution_binding_missing"
            elif not execution_placement_matches(
                selected_binding["resolved_target"], trusted_placement
            ):
                reason = "execution_binding_mismatch"
            elif not self._placement_recovery_qualification_matches(
                row["id"], trusted_placement
            ):
                reason = "execution_qualification_mismatch"
            elif (
                self._task_requires_remote_activation(row["id"])
                or qualified_identity
            ) and not self._remote_activation_matches(
                row["id"], identity, trusted_placement, require_fresh=True
            ):
                reason = "remote_activation_missing"
            else:
                reason = None
            if reason is not None:
                self.store._set_waiting_reason(row["id"], reason)
                value = self.store.get_task(row["id"])
                result = {"task": self._task_resource(value), "waiting_reason": reason}
                return self._command_record(
                    "task.claim", "claim", idempotency_key, request_hash, result,
                    project_id="unscoped", with_receipt=False,
                )
        attempt_id, lease_id = new_id(), new_id()
        value = self.store._claim_task(row["id"], executor_id, lease_id, runtime_epoch=epoch, _transactional=False)
        if value["task"]["status"] != "running":
            result = {"task": self._task_resource(value), "waiting_reason": value["task"].get("waiting_reason") or "waiting_for_worker"}
        else:
            task = value["task"]
            fence = int(task.get("lease_fence") or task.get("attempt") or 1)
            expires = task.get("lease_expires_at") or now()
            self.store.conn.execute("INSERT INTO attempts(id, task_id, lease_id, fence, executor_id, lease_expires_at, settled, runtime_epoch) VALUES (?, ?, ?, ?, ?, ?, 0, ?)", (attempt_id, row["id"], lease_id, fence, executor_id, expires, epoch))
            self.store.conn.execute("UPDATE tasks SET attempt_id=? WHERE id=?", (attempt_id, row["id"]))
            binding = self.store.bind_execution_attempt(
                row["id"], attempt_id=attempt_id, lease_id=lease_id,
                fence=fence, executor_id=executor_id, runtime_epoch=epoch,
                placement=trusted_placement,
            )
            if binding is not None:
                self.store._append_event(
                    value["run"]["id"], row["id"], "task.execution_bound",
                    {
                        "attempt_id": attempt_id,
                        "lease_id": lease_id,
                        "fence": fence,
                        "runtime_epoch": epoch,
                        "execution_binding": binding,
                    },
                )
            # Return the immutable admitted spec alongside the lease. Workers
            # must execute exactly what was claimed, without a racy second read.
            admitted_spec, generation_intent = public_task_spec(task.get("spec") or {})
            from .capture_validation import claim_capture_view
            admitted_spec = claim_capture_view(self, admitted_spec)
            if task.get("generation_intent") is not None:
                generation_intent = task["generation_intent"]
            result = {"attempt_id": attempt_id, "task_id": row["id"], "run_id": value["run"]["id"], "project_id": value["run"].get("project_id"), "lease_id": lease_id, "fence": fence, "lease_expires_at": expires, "runtime_epoch": epoch, "input_object_ids": list(admitted_spec.get("input_object_ids") or []), "spec": admitted_spec}
            if task.get("execution_request") is not None:
                result["execution_request"] = dict(task["execution_request"])
            if binding is not None:
                result["execution_binding"] = binding
            if generation_intent is not None:
                result["generation_intent"] = generation_intent
            if task.get("expected_effect") is not None:
                result["expected_effect"] = dict(task["expected_effect"])
            if "required_facts" in admitted_spec:
                result["required_facts"] = dict(admitted_spec["required_facts"])
            if "storage_estimate" in admitted_spec:
                result["storage_estimate"] = dict(admitted_spec["storage_estimate"])
        return self._command_record("task.claim", "claim", idempotency_key, request_hash, result, project_id="unscoped", with_receipt=False)

    @_durable_mutation
    def settle_attempt(self, attempt_id, body, *, idempotency_key=None, identity=None, _verified_objects=None):
        idempotency_key = require_idempotency_key(idempotency_key)
        body = dict(_wire_object(
            body,
            allowed=("attempt_id", "lease_id", "fence", "runtime_epoch", "outputs", "effect", "result"),
        ))
        supplied_attempt_id = body.get("attempt_id")
        if supplied_attempt_id is not None and str(supplied_attempt_id) != str(attempt_id):
            raise ConflictError("attempt_id does not match the attempt path")
        body["attempt_id"] = str(attempt_id)
        _wire_string(body, "lease_id")
        _require_runtime_epoch_for_lease(body)
        # Keep a numerically typed stale fence on the lease path. A worker
        # presenting fence 0 (or another old fence) is a fenced lease error,
        # not a request-shape error; this preserves one guard taxonomy.
        _wire_integer(body, "fence")
        _wire_integer(body, "runtime_epoch", positive=True)
        if "outputs" in body and not isinstance(body["outputs"], list):
            raise ValidationError("outputs must be a list")
        if "result" in body and not isinstance(body["result"], dict):
            raise ValidationError("result must be an object")
        if isinstance(body.get("result"), dict) and "outputs" in body["result"]:
            raise ValidationError("result.outputs is reserved; send outputs at the settlement top level")
        with self.store._mutex:
            row = self.store.conn.execute("SELECT * FROM attempts WHERE id=?", (attempt_id,)).fetchone()
            self._assert_attempt_identity(row, identity)
            if not row:
                raise LeaseError("attempt lease is stale or already settled")
            current_epoch = self.store._current_runtime_epoch()
            self.store._validate_runtime_epoch(body["runtime_epoch"], identity="executor", identity_id=row["executor_id"], required=True)
            task = self.store.conn.execute("SELECT * FROM tasks WHERE id=?", (row["task_id"],)).fetchone()
            project_id = self.store.conn.execute("SELECT project_id FROM runs WHERE id=?", (task["run_id"],)).fetchone()[0] if task else "unscoped"
            request_hash = hashlib.sha256(canonical_json({"attempt_id": attempt_id, "body": body}).encode()).hexdigest()
            replay = self._command_replay("attempt.settle", attempt_id, idempotency_key, request_hash, project_id=project_id or "unscoped")
            if replay is not None:
                return replay
            self._validate_attempt_lease(row, body, current_epoch)
            if not task or (task["runtime_epoch"] is not None and int(task["runtime_epoch"]) != current_epoch):
                raise LeaseError("attempt belongs to a stale runtime epoch")
            if task["status"] != "running" or task["attempt_id"] != attempt_id or task["lease_token"] != row["lease_id"] or int(task["lease_fence"] or 0) != int(row["fence"]):
                raise LeaseError("attempt lease is stale or already settled")
            declared = json.loads(task["expected_effect_json"]) if task["expected_effect_json"] else None
            effect = body.get("effect")
            if effect is not None and declared != effect:
                raise ValidationError("settlement effect was not predeclared", details={"declared": declared})
            if declared is not None and effect is None:
                raise ValidationError("declared settlement effect is required")
            if effect is not None:
                self.store._validate_settlement_effect(effect)
            admitted_spec = self.store._spec(task)
            if admitted_spec.get("delegation_closed_attempt_id") == attempt_id:
                raise AuthorizationError("parent attempt child authority has ended")
            lineage = admitted_spec.get("delegated_parent")
            if lineage is not None:
                self._live_delegating_parent(lineage["parent_attempt_id"], {
                    "lease_id": lineage["parent_lease_id"], "fence": lineage["parent_fence"],
                    "runtime_epoch": lineage["runtime_epoch"],
                }, identity=None)
            self.store.assert_delegated_children_completed(task["id"], attempt_id)
            for child in self.store.delegated_children(task["id"], attempt_id):
                for association in self.store.list_managed_outputs(child["id"]):
                    if association["role"] == "recoverable_snapshot":
                        continue
                    digest = association["object_id"].removeprefix("sha256:")
                    obj = self.store.conn.execute("SELECT size, media_type FROM objects WHERE digest=?", (digest,)).fetchone()
                    if (obj is None or int(obj["size"]) != association["size"] or obj["media_type"] != association["media_type"]
                            or association["project_id"] != project_id
                            or (project_id is not None and not self.store.conn.execute("SELECT 1 FROM project_objects WHERE project_id=? AND digest=?", (project_id, digest)).fetchone())):
                        raise ConflictError("accepted child managed output metadata changed")
                    self._verify_child_object_bytes(digest, association["size"], label="accepted child output CAS object")
            verified_source = admitted_spec.get("verified_publication_source")
            if verified_source is not None:
                lineage = admitted_spec["delegated_parent"]
                self._live_delegating_parent(lineage["parent_attempt_id"], {
                    "lease_id": lineage["parent_lease_id"], "fence": lineage["parent_fence"],
                    "runtime_epoch": lineage["runtime_epoch"],
                }, identity=None)
                association = self.store.get_managed_output(verified_source["association_id"])
                producer = self.store.conn.execute("SELECT status, attempt_id FROM tasks WHERE id=?", (verified_source["producer_task_id"],)).fetchone()
                if (association["task_id"] != verified_source["producer_task_id"]
                        or association["attempt_id"] != verified_source["producer_attempt_id"]
                        or association["project_id"] != project_id
                        or association["object_id"] != verified_source["object_id"]
                        or association["output_port"] != verified_source["output_port"]
                        or association["durability"] != "durable"
                        or association["lifecycle"]["state"] not in {"available", "promoted"}
                        or producer is None or producer["status"] != "completed"
                        or producer["attempt_id"] != verified_source["producer_attempt_id"]):
                    raise ConflictError("verified publication source is no longer available")
                outputs = body.get("outputs")
                if (not isinstance(outputs, list) or len(outputs) != 1 or not isinstance(outputs[0], dict)
                        or outputs[0].get("digest") != verified_source["object_id"]
                        or outputs[0].get("output_port") != verified_source["output_port"]
                        or outputs[0].get("kind", "object") != "object"
                        or outputs[0].get("durability", "durable") != "durable"):
                    raise AuthorizationError("final publication must use the declared verified output")
            if _verified_objects is not None and (row["executor_id"] != MEDIA_IMPORT_EXECUTOR or task["capability"] != MEDIA_IMPORT_CAPABILITY):
                raise AuthorizationError("verified import proof requires the host import executor")
            staged = self._stage_outputs(
                attempt_id,
                body.get("outputs", []),
                project_id=project_id,
                attempt_row=row,
                task_row=task,
                lease_body=body,
                verified_objects=_verified_objects,
            )
            try:
                # Persist one flat result object. Outputs are the only
                # reserved field and are added atomically with user fields.
                result = dict(body.get("result") or {})
                result["outputs"] = staged["outputs"]
                recorded = None
                def record(value, *, event_ids=(), primary_stream_id=None, resulting_stream_seq=None, created_at=None):
                    nonlocal recorded
                    recorded = self._command_record(
                        "attempt.settle", attempt_id, idempotency_key, request_hash,
                        self._task_resource(value), project_id=project_id or "unscoped",
                        event_ids=event_ids, primary_stream_id=primary_stream_id,
                        resulting_stream_seq=resulting_stream_seq,
                        created_at=created_at,
                    )
                self.store._settle_attempt(
                    row["task_id"], row["lease_id"], result,
                    effect=effect, fence=body["fence"], attempt_id=attempt_id,
                    duration_seconds_presence=staged["duration_seconds_presence"],
                    publish=lambda: self._publish_staged_outputs(staged, project_id=project_id),
                    record=record,
                )
                staged["committed"] = True
                return recorded
            finally:
                self._discard_staged_outputs(staged)

    def publish_timeline_render(self, attempt_id, body, *, idempotency_key=None, identity=None):
        self._require_timeline_command()

    def _is_authorized_generic_output(
        self, digest, size, media_type, *, name, output_port, filename,
        recorded_filename, attempt_row, task_row, project_id, lease_body,
    ):
        """Recognize the worker's unscoped output upload receipt.

        Generic producers cannot create a project association during their
        upload. Settlement may adopt that exact object only when the
        unscoped upload's request hash carries the current task/run/project,
        attempt, executor, lease/fence, filename, and deterministic output
        key, and its durable result matches the descriptor.
        """
        if attempt_row is None or task_row is None or lease_body is None:
            return False
        try:
            canonical_recorded_filename = _canonical_managed_output_filename(recorded_filename)
        except ValidationError:
            return False
        if canonical_recorded_filename != filename:
            return False
        binding = {
            "project_id": project_id,
            "run_id": task_row["run_id"],
            "task_id": task_row["id"],
            "attempt_id": attempt_row["id"],
            "executor_id": attempt_row["executor_id"],
            "lease_id": lease_body["lease_id"],
            "fence": int(lease_body["fence"]),
            "runtime_epoch": int(lease_body["runtime_epoch"]),
            "output_key": name,
            "output_port": output_port,
            # Upload receipts are keyed by the producer's original name;
            # settlement stores its canonical flat managed name.
            "filename": recorded_filename,
            "digest": "sha256:" + digest,
            "size": int(size),
            "media_type": media_type,
        }
        idempotency_key = self._generic_output_idempotency_key(binding)
        row = self.store.conn.execute(
            "SELECT request_hash, result_json FROM command_idempotency "
            "WHERE command_kind='object.ingest' AND aggregate_id='objects' "
            "AND idempotency_key=?",
            (idempotency_key,),
        ).fetchone()
        if not row:
            return False
        try:
            result = json.loads(row["result_json"])
        except (TypeError, ValueError):
            return False
        if not isinstance(result, dict):
            return False
        expected_hash = self._generic_output_request_hash(
            digest, media_type, recorded_filename, None, binding,
        )
        if row["request_hash"] != expected_hash:
            return False
        try:
            recorded_size = int(result.get("size", -1))
        except (TypeError, ValueError):
            return False
        return (
            result.get("object_id") == "sha256:" + digest
            and result.get("digest") == "sha256:" + digest
            and recorded_size == int(size)
            and result.get("media_type") == media_type
        )

    def _stage_outputs(self, attempt_id, outputs, *, project_id=None, attempt_row=None, task_row=None, lease_body=None, verified_objects=None):
        """Validate and stage every output without making it globally reachable."""
        if not isinstance(outputs, list):
            raise ValidationError("outputs must be a list")
        stage_dir = self.store.attempt_staging_dir(attempt_id)
        stage_dir.mkdir(parents=True, exist_ok=True)
        if stage_dir.is_symlink() or not stage_dir.is_dir():
            raise ValidationError("attempt staging directory is invalid")
        platform.owner_only(stage_dir)
        staged = []
        duration_seconds_presence = {}
        seen = set()
        content_metadata = {}
        non_object_digests = set()
        try:
            for index, output in enumerate(outputs):
                if not isinstance(output, dict):
                    raise ValidationError("each output must be an object")
                allowed = {
                    "name", "filename", "output_port", "selector", "group_key", "variant_key", "generation_id",
                    "kind", "digest", "media_type", "size", "data_base64", "ordinal", "role",
                    "is_primary", "duration_seconds", "durability", "producer", "provenance",
                    "regeneration", "coverage",
                }
                unknown = sorted(set(output) - allowed)
                if unknown:
                    raise ValidationError("output contains unsupported fields", details={"fields": unknown})
                if output.get("role") == "recoverable_snapshot":
                    raise ValidationError("recoverable_snapshot is a Runtime-reserved output role")
                digest_value = output.get("digest")
                if not isinstance(digest_value, str) or not digest_value.startswith("sha256:"):
                    raise ValidationError("each output requires a sha256 digest")
                digest = digest_value.removeprefix("sha256:")
                if len(digest) != 64 or any(char not in "0123456789abcdef" for char in digest):
                    raise ValidationError("each output requires a valid SHA-256 digest")
                kind = output.get("kind", "object")
                if not isinstance(kind, str) or kind not in {"object", "document", "value"}:
                    raise ValidationError("output kind is invalid")
                if digest in non_object_digests or (kind != "object" and digest in content_metadata):
                    raise ValidationError("outputs must not contain duplicate digests")
                if kind != "object":
                    non_object_digests.add(digest)
                name = output.get("name", "output")
                if not isinstance(name, str) or not name or len(name) > 512:
                    raise ValidationError("output name must be a non-empty string")
                filename = _canonical_managed_output_filename(output.get("filename", name))
                media_type = output.get("media_type", "application/octet-stream")
                if not isinstance(media_type, str) or not media_type or len(media_type) > 255 or any(ord(char) < 32 for char in media_type):
                    raise ValidationError("output media_type is invalid")
                declared_size = output.get("size")
                if declared_size is not None and (isinstance(declared_size, bool) or not isinstance(declared_size, int) or declared_size < 0 or declared_size > OBJECT_MAX_BYTES):
                    raise ValidationError("output size must be an integer between 0 and 5 GiB")
                data_field = output.get("data_base64")
                stage_path = None
                if data_field is not None:
                    if not isinstance(data_field, str):
                        raise ValidationError("output data_base64 is invalid")
                    try:
                        data = base64.b64decode(data_field, validate=True)
                    except (ValueError, TypeError) as exc:
                        raise ValidationError("output data_base64 is invalid") from exc
                    if len(data) > OBJECT_MAX_BYTES:
                        raise ValidationError("output exceeds 5 GiB object limit")
                    actual_digest = sha256_bytes(data)
                    if actual_digest != digest:
                        raise ConflictError("output content hash does not match declared digest", details={"expected": digest_value, "actual": "sha256:" + actual_digest})
                    if declared_size is not None and declared_size != len(data):
                        raise ValidationError("output size does not match staged bytes")
                    stage_path = stage_dir / f"{index:08d}.stage"
                    with open(stage_path, "xb") as stream:
                        stream.write(data)
                        stream.flush()
                        os.fsync(stream.fileno())
                    size = len(data)
                else:
                    root_fd = prefix_fd = file_fd = -1
                    try:
                        try:
                            root_fd, prefix_fd = self._cas_prefix_fds(digest, create=False)
                        except (FileNotFoundError, OSError) as exc:
                            raise ConflictError(
                                "output must be staged or published to runtime CAS before settlement",
                                details={"digest": digest_value},
                            ) from exc
                        try:
                            file_fd = os.open(
                                digest[2:],
                                os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0),
                                dir_fd=prefix_fd,
                            )
                        except OSError as exc:
                            raise ConflictError(
                                "output must be staged or published to runtime CAS before settlement",
                                details={"digest": digest_value},
                            ) from exc
                        size = int(os.fstat(file_fd).st_size)
                        if size > OBJECT_MAX_BYTES:
                            raise ValidationError("output exceeds 5 GiB object limit")
                        if verified_objects is not None and digest in verified_objects:
                            if file_identity(os.fstat(file_fd)) != verified_objects[digest]:
                                raise ConflictError("verified imported CAS object changed")
                        else:
                            self._verify_open_file(file_fd, digest, size, label="CAS object")
                    finally:
                        if file_fd >= 0:
                            os.close(file_fd)
                        if prefix_fd >= 0:
                            os.close(prefix_fd)
                        if root_fd >= 0:
                            os.close(root_fd)
                    if declared_size is not None and declared_size != size:
                        raise ValidationError("output size does not match CAS bytes")
                metadata = (size, media_type)
                if digest in content_metadata and content_metadata[digest] != metadata:
                    raise ConflictError("output metadata does not match existing object", details={"digest": digest_value})
                content_metadata[digest] = metadata
                ordinal = output.get("ordinal")
                if ordinal is not None and (isinstance(ordinal, bool) or not isinstance(ordinal, int) or ordinal < 0):
                    raise ValidationError("output ordinal must be a non-negative integer")
                role = output.get("role")
                if role is not None and (not isinstance(role, str) or not role or len(role) > 255 or any(ord(char) < 32 for char in role)):
                    raise ValidationError("output role is invalid")
                is_primary = output.get("is_primary")
                if is_primary is not None and not isinstance(is_primary, bool):
                    raise ValidationError("output is_primary must be a boolean")
                duration_seconds = output.get("duration_seconds")
                if duration_seconds is not None and (
                    isinstance(duration_seconds, bool)
                    or not isinstance(duration_seconds, (int, float))
                    or not math.isfinite(float(duration_seconds))
                    or float(duration_seconds) <= 0
                ):
                    raise ValidationError("output duration_seconds must be a positive finite number")
                output_port = output.get("output_port", name)
                if not isinstance(output_port, str) or not output_port or len(output_port) > 255 or any(ord(char) < 32 for char in output_port):
                    raise ValidationError("output_port is invalid")
                selector = output.get("selector")
                if selector is not None:
                    if not isinstance(selector, dict) or set(selector) != {"group_key", "variant_key"}:
                        raise ValidationError("output selector requires exactly group_key and variant_key")
                    if "group_key" not in output:
                        output["group_key"] = selector["group_key"]
                    if "variant_key" not in output:
                        output["variant_key"] = selector["variant_key"]
                group_key = output.get("group_key", "default")
                if not isinstance(group_key, str) or not group_key or len(group_key) > 255 or any(ord(char) < 32 for char in group_key):
                    raise ValidationError("output group_key is invalid")
                variant_key = output.get("variant_key", str(ordinal if ordinal is not None else 0))
                if not isinstance(variant_key, str) or len(variant_key) > 255 or any(ord(char) < 32 for char in variant_key):
                    raise ValidationError("output variant_key is invalid")
                # Content identity is shared by CAS objects; association
                # identity follows the existing port/group/variant/ordinal key.
                association_key = (output_port, group_key, variant_key, ordinal if ordinal is not None else 0)
                if kind == "object":
                    if association_key in seen:
                        raise ValidationError("outputs must not contain duplicate associations")
                    seen.add(association_key)
                generation_id = output.get("generation_id")
                if generation_id is not None and (not isinstance(generation_id, str) or not generation_id or len(generation_id) > 255):
                    raise ValidationError("output generation_id is invalid")
                durability = output.get("durability", "durable")
                if durability not in MANAGED_DURABILITIES:
                    raise ValidationError("output durability is invalid")
                if durability == "temporary" and is_primary is True:
                    raise ValidationError("primary outputs must be durable")
                producer = output.get("producer", {})
                provenance = output.get("provenance", {})
                if not isinstance(producer, dict) or not isinstance(provenance, dict):
                    raise ValidationError("output producer and provenance must be objects")
                regeneration = output.get("regeneration")
                if regeneration is not None:
                    regeneration = _validate_regeneration(regeneration)
                coverage = output.get("coverage")
                if coverage is not None:
                    coverage = _validate_coverage(coverage)
                existing = self.store.conn.execute("SELECT size, media_type, original_name FROM objects WHERE digest=?", (digest,)).fetchone()
                if existing:
                    if int(existing["size"]) != size or existing["media_type"] != media_type:
                        raise ConflictError("output metadata does not match existing object", details={"digest": digest_value})
                    if project_id and not self.store.conn.execute("SELECT 1 FROM project_objects WHERE project_id=? AND digest=?", (project_id, digest)).fetchone():
                        has_project_owner = self.store.conn.execute(
                            "SELECT 1 FROM project_objects WHERE digest=? LIMIT 1", (digest,)
                        ).fetchone()
                        # The CAS row retains the first ingest's filename.
                        # Each association still needs its own exact receipt;
                        # retain the recorded filename for legacy normalization.
                        if has_project_owner or not any(self._is_authorized_generic_output(
                            digest,
                            size,
                            media_type,
                            name=name,
                            output_port=output_port,
                            filename=filename,
                            recorded_filename=recorded_filename,
                            attempt_row=attempt_row,
                            task_row=task_row,
                            project_id=project_id,
                            lease_body=lease_body,
                        ) for recorded_filename in (output.get("filename", name), existing["original_name"])):
                            raise ConflictError("output object is outside the task project", details={"project_id": project_id, "digest": digest_value})
                elif project_id and stage_path is None and not self.store.conn.execute("SELECT 1 FROM project_objects WHERE project_id=? AND digest=?", (project_id, digest)).fetchone():
                    raise ConflictError("output object is outside the task project", details={"project_id": project_id, "digest": digest_value})
                normalized = {
                    "name": name, "kind": kind, "digest": digest_value,
                    "media_type": media_type, "size": size,
                }
                # Keep the established settlement result wire stable.  The
                # association table/readback carries the defaulted filename,
                # port, group, and variant identity; echo an extended field
                # only when the producer explicitly supplied it.
                if "filename" in output:
                    normalized["filename"] = filename
                if "output_port" in output:
                    normalized["output_port"] = output_port
                if selector is not None:
                    normalized["selector"] = {"group_key": group_key, "variant_key": variant_key}
                if "group_key" in output:
                    normalized["group_key"] = group_key
                if "variant_key" in output:
                    normalized["variant_key"] = variant_key
                if generation_id is not None:
                    normalized["generation_id"] = generation_id
                if ordinal is not None:
                    normalized["ordinal"] = ordinal
                if role is not None:
                    normalized["role"] = role
                if is_primary is not None:
                    normalized["is_primary"] = is_primary
                if duration_seconds is not None:
                    normalized["duration_seconds"] = duration_seconds
                if "duration_seconds" in output:
                    duration_seconds_presence[(
                        output_port,
                        group_key,
                        variant_key,
                        int(ordinal if ordinal is not None else 0),
                    )] = duration_seconds
                if durability != "durable":
                    normalized["durability"] = durability
                if producer:
                    normalized["producer"] = producer
                if provenance:
                    normalized["provenance"] = provenance
                if regeneration is not None:
                    normalized["regeneration"] = regeneration
                if coverage is not None:
                    normalized["coverage"] = coverage
                staged.append({
                    "digest": digest, "path": stage_path, "size": size, "media_type": media_type,
                    "verified_identity": (verified_objects or {}).get(digest),
                    "name": name, "filename": filename, "output": normalized,
                    "output_port": output_port, "group_key": group_key, "variant_key": variant_key,
                    "generation_id": generation_id, "durability": durability, "producer": producer,
                    "provenance": provenance, "regeneration": regeneration, "coverage": coverage,
                })
            return {
                "stage_dir": stage_dir,
                "attempt_id": attempt_id,
                "items": staged,
                "outputs": [item["output"] for item in staged],
                # Keep explicit null presence transiently for missing-only
                # settlement enrichment; it is not part of the wire result.
                "duration_seconds_presence": duration_seconds_presence,
            }
        except Exception:
            self._discard_staged_outputs({"stage_dir": stage_dir, "items": staged})
            raise


    @staticmethod
    def _verify_open_file(file_fd, digest, expected_size, *, label):
        """Hash one already-open file without reopening its pathname."""
        try:
            initial = os.fstat(file_fd)
            if not stat.S_ISREG(initial.st_mode):
                raise ConflictError(f"{label} must be a regular file")
            if initial.st_size != expected_size:
                raise ConflictError(f"{label} size does not match staged metadata")
            os.lseek(file_fd, 0, os.SEEK_SET)
            hasher = hashlib.sha256()
            while True:
                chunk = os.read(file_fd, 1024 * 1024)
                if not chunk:
                    break
                hasher.update(chunk)
            final = os.fstat(file_fd)
        except OSError as exc:
            raise ConflictError(f"{label} is unavailable") from exc
        if (
            final.st_dev != initial.st_dev
            or final.st_ino != initial.st_ino
            or final.st_size != expected_size
            or final.st_mtime_ns != initial.st_mtime_ns
            or final.st_ctime_ns != initial.st_ctime_ns
            or hasher.hexdigest() != digest
        ):
            raise ConflictError(f"{label} hash or size does not match staged metadata")
        return initial

    def _cas_prefix_fds(self, digest, *, create):
        """Open a CAS digest prefix below descriptors, never through a path."""
        root_fd = _open_directory_chain(self.cas.root)
        try:
            prefix = digest[:2]
            if create:
                prefix_fd = _mkdir_chain_at(root_fd, prefix)
            else:
                prefix_fd = os.open(
                    prefix,
                    os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0),
                    dir_fd=root_fd,
                )
            try:
                if not stat.S_ISDIR(os.fstat(prefix_fd).st_mode):
                    raise ConflictError("CAS destination directory is invalid")
            except Exception:
                os.close(prefix_fd)
                raise
            return root_fd, prefix_fd
        except Exception:
            os.close(root_fd)
            raise

    @staticmethod
    def _copy_open_file_at(source_fd, destination_fd, destination_name, digest, expected_size, *, label):
        """Copy verified bytes to a private file, then atomically link it."""
        temporary_name = f".{destination_name}.{os.getpid()}-{uuid.uuid4().hex}.tmp"
        temporary_fd = -1
        linked = False
        try:
            initial = RuntimeService._verify_open_file(source_fd, digest, expected_size, label=label)
            temporary_fd = os.open(
                temporary_name,
                os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0),
                0o600,
                dir_fd=destination_fd,
            )
            os.lseek(source_fd, 0, os.SEEK_SET)
            hasher = hashlib.sha256()
            copied = 0
            while True:
                chunk = os.read(source_fd, 1024 * 1024)
                if not chunk:
                    break
                hasher.update(chunk)
                copied += len(chunk)
                view = memoryview(chunk)
                while view:
                    written = os.write(temporary_fd, view)
                    view = view[written:]
            final = os.fstat(source_fd)
            if (
                final.st_dev != initial.st_dev
                or final.st_ino != initial.st_ino
                or copied != expected_size
                or hasher.hexdigest() != digest
            ):
                raise ConflictError(f"{label} hash or size does not match staged metadata")
            os.fsync(temporary_fd)
            os.close(temporary_fd)
            temporary_fd = -1
            RuntimeService._verify_file_at(
                destination_fd, temporary_name, digest, expected_size, label="temporary CAS object",
            )
            try:
                os.stat(destination_name, dir_fd=destination_fd, follow_symlinks=False)
            except FileNotFoundError:
                pass
            else:
                raise ConflictError("CAS destination appeared during publication")
            os.link(
                temporary_name,
                destination_name,
                src_dir_fd=destination_fd,
                dst_dir_fd=destination_fd,
                follow_symlinks=False,
            )
            linked = True
            os.unlink(temporary_name, dir_fd=destination_fd)
        except OSError as exc:
            raise ConflictError(f"{label} is unavailable") from exc
        finally:
            if temporary_fd >= 0:
                os.close(temporary_fd)
            try:
                os.unlink(temporary_name, dir_fd=destination_fd)
            except OSError:
                pass
        RuntimeService._verify_file_at(destination_fd, destination_name, digest, expected_size, label="CAS object")
        return initial

    @staticmethod
    def _verify_file_at(directory_fd, name, digest, expected_size, *, label):
        try:
            file_fd = os.open(name, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0), dir_fd=directory_fd)
        except OSError as exc:
            raise ConflictError(f"{label} is unavailable") from exc
        try:
            RuntimeService._verify_open_file(file_fd, digest, expected_size, label=label)
        finally:
            os.close(file_fd)

    @staticmethod
    def _unlink_stage_entry(stage_fd, name, expected_stat=None):
        try:
            current = os.stat(name, dir_fd=stage_fd, follow_symlinks=False)
            if expected_stat is not None and (
                current.st_dev != expected_stat.st_dev or current.st_ino != expected_stat.st_ino
            ):
                return
            os.unlink(name, dir_fd=stage_fd)
        except FileNotFoundError:
            pass

    def _unlink_cas_destination(self, digest, *, create_prefix=False):
        """Unlink a CAS object relative to a descriptor-pinned prefix."""
        root_fd = prefix_fd = -1
        try:
            try:
                root_fd, prefix_fd = self._cas_prefix_fds(digest, create=create_prefix)
            except FileNotFoundError:
                return False
            try:
                os.unlink(digest[2:], dir_fd=prefix_fd)
            except FileNotFoundError:
                return False
            os.fsync(prefix_fd)
            return True
        finally:
            if prefix_fd >= 0:
                os.close(prefix_fd)
            if root_fd >= 0:
                os.close(root_fd)
    def _publish_staged_outputs(self, staged, *, project_id=None):
        """Publish already validated bytes as part of the settlement transaction."""
        staged.setdefault("published", [])
        candidate_entries = []
        task_id = None
        attempt_id = staged.get("attempt_id")
        if attempt_id:
            row = self.store.conn.execute("SELECT task_id FROM attempts WHERE id=?", (attempt_id,)).fetchone()
            task_id = row["task_id"] if row else None

        stage_identity = None
        stage_fd = -1
        cas_handles = {}
        try:
            if any(item["path"] is not None for item in staged["items"]):
                stage_identity, stage_fd, _ = _pin_directory(staged["stage_dir"])

            for item in staged["items"]:
                digest = item["digest"]
                if digest in cas_handles:
                    continue
                root_fd, prefix_fd = self._cas_prefix_fds(digest, create=True)
                cas_handles[digest] = (root_fd, prefix_fd)
                destination_name = digest[2:]
                try:
                    os.stat(destination_name, dir_fd=prefix_fd, follow_symlinks=False)
                    destination_exists = True
                except FileNotFoundError:
                    destination_exists = False
                except OSError as exc:
                    raise ConflictError("CAS destination is unavailable") from exc
                if item["path"] is not None and not destination_exists:
                    candidate_entries.append({"digest": digest})

            if candidate_entries:
                staged["journal_path"] = self._begin_cas_publication_journal(
                    "settlement", candidate_entries, project_id=project_id or "unscoped", task_id=task_id,
                )

            for item in staged["items"]:
                digest = item["digest"]
                _root_fd, prefix_fd = cas_handles[digest]
                destination_name = digest[2:]
                if item["path"] is not None:
                    source_name = item["path"].name
                    try:
                        source_fd = os.open(
                            source_name,
                            os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0),
                            dir_fd=stage_fd,
                        )
                    except OSError as exc:
                        raise ConflictError("staged output is unavailable") from exc
                    try:
                        source_stat = self._verify_open_file(
                            source_fd, digest, item["size"], label="staged output",
                        )
                        try:
                            destination_exists = os.stat(
                                destination_name, dir_fd=prefix_fd, follow_symlinks=False,
                            )
                        except FileNotFoundError:
                            destination_exists = None
                        except OSError as exc:
                            raise ConflictError("CAS destination is unavailable") from exc
                        if destination_exists is not None:
                            self._verify_file_at(
                                prefix_fd, destination_name, digest, item["size"], label="CAS object",
                            )
                        else:
                            self._copy_open_file_at(
                                source_fd, prefix_fd, destination_name, digest, item["size"],
                                label="staged output",
                            )
                            staged["published"].append(digest)
                            os.fsync(prefix_fd)
                        self._unlink_stage_entry(stage_fd, source_name, source_stat)
                    finally:
                        os.close(source_fd)
                else:
                    if item.get("verified_identity") is not None:
                        value = os.stat(destination_name, dir_fd=prefix_fd, follow_symlinks=False)
                        if not stat.S_ISREG(value.st_mode) or file_identity(value) != item["verified_identity"]:
                            raise ConflictError("verified imported CAS object changed")
                    else:
                        self._verify_file_at(
                            prefix_fd, destination_name, digest, item["size"], label="CAS object",
                        )
                self.store.conn.execute(
                    "INSERT OR IGNORE INTO objects(digest, size, media_type, original_name, created_at) VALUES (?, ?, ?, ?, ?)",
                    (digest, item["size"], item["media_type"], item["name"], now()),
                )
                if project_id:
                    self.store.conn.execute(
                        "INSERT OR IGNORE INTO project_objects(project_id, digest, relation, created_at) VALUES (?, ?, 'managed', ?)",
                        (project_id, digest, now()),
                    )
        finally:
            if stage_fd >= 0:
                os.close(stage_fd)
            if stage_identity is not None:
                _close_pinned(stage_identity)
            for root_fd, prefix_fd in cas_handles.values():
                os.close(prefix_fd)
                os.close(root_fd)


    def _discard_staged_outputs(self, staged):
        stage_dir = staged.get("stage_dir") if isinstance(staged, dict) else None
        committed = bool(staged.get("committed")) if isinstance(staged, dict) else False

        if stage_dir is not None:
            stage_identity = None
            stage_fd = -1
            try:
                stage_identity, stage_fd, stage_stat = _pin_directory(stage_dir)
            except (OSError, ConflictError):
                # Never fall back to pathname unlinking when the staging
                # directory cannot be descriptor-pinned.
                pass
            else:
                try:
                    try:
                        for entry in os.scandir(stage_fd):
                            entry_stat = entry.stat(follow_symlinks=False)
                            if stat.S_ISREG(entry_stat.st_mode) or stat.S_ISLNK(entry_stat.st_mode):
                                os.unlink(entry.name, dir_fd=stage_fd)
                        os.fsync(stage_fd)
                    except OSError:
                        pass
                    parent_fd = stage_identity.get("_parent_fd")
                    if parent_fd is not None:
                        try:
                            current = os.stat(
                                stage_dir.name, dir_fd=int(parent_fd), follow_symlinks=False,
                            )
                            if (
                                stat.S_ISDIR(current.st_mode)
                                and current.st_dev == stage_stat.st_dev
                                and current.st_ino == stage_stat.st_ino
                            ):
                                os.rmdir(stage_dir.name, dir_fd=int(parent_fd))
                                os.fsync(int(parent_fd))
                        except OSError:
                            pass
                finally:
                    os.close(stage_fd)
                    _close_pinned(stage_identity)

        if not committed:
            for digest in (staged.get("published", []) if isinstance(staged, dict) else []):
                try:
                    if len(digest) == 64 and all(char in "0123456789abcdef" for char in digest):
                        self._unlink_cas_destination(digest)
                except (FileNotFoundError, OSError, ConflictError):
                    continue

    def _checkpoint_row(self, checkpoint_id=None, attempt_id=None):
        if checkpoint_id:
            row = self.store.conn.execute("SELECT * FROM recovery_checkpoints WHERE id=?", (checkpoint_id,)).fetchone()
            if row and attempt_id is not None and row["attempt_id"] != attempt_id:
                raise LeaseError("checkpoint is bound to a different attempt")
        else:
            row = self.store.conn.execute("SELECT * FROM recovery_checkpoints WHERE attempt_id=? ORDER BY created_at DESC LIMIT 1", (attempt_id,)).fetchone()
        if not row:
            raise NotFoundError("recovery checkpoint not found")
        attempt = self.store.conn.execute("SELECT task_id, executor_id, lease_id, fence FROM attempts WHERE id=?", (row["attempt_id"],)).fetchone()
        if not attempt or attempt["task_id"] != row["task_id"] or attempt["executor_id"] != row["executor_id"] or attempt["lease_id"] != row["lease_id"] or int(attempt["fence"]) != int(row["fence"]):
            raise ConflictError("recovery checkpoint identity is inconsistent")
        return row

    def _reboot_authorized(self, body, attempt_id, expected_nonce=None, *, allow_consumed=False):
        """Validate durable, attempt-bound recovery authorization.

        A nonce supplied by a caller is not sufficient by itself.  It must be
        the nonce persisted by ``prepare_reboot`` for this exact attempt and
        must still be within its short validity window.
        """
        attempt = self.store.conn.execute("SELECT recovery_nonce, recovery_nonce_expires_at, recovery_nonce_used FROM attempts WHERE id=?", (attempt_id,)).fetchone()
        nonce = attempt["recovery_nonce"] if attempt else None
        if "authorization_nonce" in body:
            raise ValidationError("authorization_nonce is not supported; use authorization")
        authorization = body.get("authorization")
        supplied = body.get("nonce")
        if not nonce:
            raise ValidationError("prepare_reboot is required before recovery")
        if attempt["recovery_nonce_used"] and not allow_consumed:
            raise ConflictError("recovery authorization has already been consumed")
        if attempt["recovery_nonce_expires_at"] and attempt["recovery_nonce_expires_at"] <= now():
            raise ValidationError("recovery authorization has expired")
        if not supplied or not authorization or str(supplied) != str(nonce) or str(authorization) != str(nonce) or (expected_nonce is not None and str(expected_nonce) != str(nonce)):
            raise ValidationError("recovery nonce authorization is required")
        return nonce

    def _validate_attempt_lease(self, row, body, current, *, require_epoch=True, allow_expired=False):
        """Validate the complete attempt fence before a mutating side effect."""
        if require_epoch:
            self.store._validate_runtime_epoch(
                body.get("runtime_epoch"),
                identity="executor",
                identity_id=row["executor_id"] if row else None,
                required=True,
            )
        if not row or row["settled"] or int(row["runtime_epoch"]) != current:
            raise LeaseError("attempt lease is stale or already settled")
        try:
            supplied_fence = int(body.get("fence", 0))
        except (TypeError, ValueError) as exc:
            raise LeaseError("attempt fence is invalid") from exc
        if row["lease_id"] != body.get("lease_id") or int(row["fence"]) != supplied_fence:
            raise LeaseError("attempt lease is stale or already settled")
        if not allow_expired and row["lease_expires_at"]:
            try:
                if datetime.fromisoformat(row["lease_expires_at"]) <= datetime.now(timezone.utc):
                    raise LeaseError("attempt lease has expired")
            except ValueError as exc:
                raise LeaseError("attempt lease deadline is invalid") from exc
    @_verified_mutation
    def prepare_reboot(self, body=None, *, identity=None):
        """Issue a one-shot nonce for an attempt's recovery handshake."""
        raw_body = {} if body is None else body
        _require_runtime_epoch_for_lease(raw_body)
        body = _wire_object(
            raw_body,
            required=("attempt_id", "lease_id", "fence", "runtime_epoch"),
            allowed=("attempt_id", "lease_id", "fence", "runtime_epoch"),
        )
        attempt_id = _wire_string(body, "attempt_id")
        _wire_string(body, "lease_id")
        _wire_integer(body, "fence")
        _wire_integer(body, "runtime_epoch", positive=True)
        with self.store._mutex:
            row = self.store.conn.execute("SELECT * FROM attempts WHERE id=?", (attempt_id,)).fetchone()
            self._assert_attempt_identity(row, identity)
            if not row or row["settled"]:
                raise LeaseError("attempt lease is stale or already settled")
            current = self.store._current_runtime_epoch()
            self._validate_attempt_lease(row, body, current)
            with self.store._transaction():
                current_row = self.store.conn.execute("SELECT recovery_nonce, recovery_nonce_expires_at, recovery_nonce_used FROM attempts WHERE id=?", (attempt_id,)).fetchone()
                if current_row["recovery_nonce"] and not current_row["recovery_nonce_used"] and (not current_row["recovery_nonce_expires_at"] or current_row["recovery_nonce_expires_at"] > now()):
                    nonce = current_row["recovery_nonce"]
                    expires_at = current_row["recovery_nonce_expires_at"]
                else:
                    nonce = new_id() + new_id()
                    expires_at = (datetime.now(timezone.utc) + timedelta(seconds=300)).isoformat(timespec="milliseconds")
                    self.store.conn.execute("UPDATE attempts SET recovery_nonce=?, recovery_nonce_expires_at=?, recovery_nonce_used=0 WHERE id=? AND settled=0", (nonce, expires_at, attempt_id))
        expires_in = max(0, int((datetime.fromisoformat(expires_at) - datetime.now(timezone.utc)).total_seconds()))
        return {"attempt_id": attempt_id, "task_id": row["task_id"], "executor_id": row["executor_id"], "runtime_epoch": current, "nonce": nonce, "expires_in_seconds": expires_in}

    @_verified_mutation
    def checkpoint_attempt(self, attempt_id, body, *, identity=None):
        """Persist a bounded, fsync'd R1 checkpoint before a reboot request."""
        body = _wire_object(
            body,
            required=("lease_id", "fence", "nonce", "authorization", "runtime_epoch"),
            allowed=("lease_id", "fence", "nonce", "authorization", "runtime_epoch", "checkpoint", "state"),
        )
        if not isinstance(attempt_id, str) or not attempt_id:
            raise ValidationError("attempt_id is required")
        _wire_string(body, "lease_id")
        _wire_integer(body, "fence")
        _wire_string(body, "nonce")
        _wire_string(body, "authorization")
        _wire_integer(body, "runtime_epoch", positive=True)
        with self.store._mutex:
            row = self.store.conn.execute("SELECT * FROM attempts WHERE id=?", (attempt_id,)).fetchone()
            self._assert_attempt_identity(row, identity)
            current = self.store._current_runtime_epoch()
            self._validate_attempt_lease(row, body, current)
            nonce = self._reboot_authorized(body, attempt_id)
            payload = body.get("checkpoint", body.get("state", {}))
            if not isinstance(payload, (dict, list)):
                raise ValidationError("checkpoint must be an object or array")
            durable_bytes = durable_json_bytes(payload)
            if len(durable_bytes) > CHECKPOINT_MAX_BYTES:
                raise ValidationError("recovery checkpoint exceeds 1 MiB bound")
            # A repeated request with the same durable authorization and bytes
            # is idempotent.  A different payload is a conflict, never a new
            # checkpoint that could be resumed accidentally.
            existing = self.store.conn.execute("SELECT * FROM recovery_checkpoints WHERE attempt_id=? AND nonce=? ORDER BY created_at DESC LIMIT 1", (attempt_id, nonce)).fetchone()
            if existing:
                existing_bytes = Path(existing["checkpoint_path"]).read_bytes()
                if sha256_bytes(existing_bytes) != existing["checkpoint_digest"] or json.loads(existing_bytes.decode("utf-8")) != payload:
                    raise ConflictError("recovery checkpoint authorization already binds different bytes")
                return {"checkpoint_id": existing["id"], "attempt_id": existing["attempt_id"], "task_id": existing["task_id"], "runtime_epoch": existing["runtime_epoch"], "nonce": nonce, "digest": "sha256:" + existing["checkpoint_digest"], "size": existing["checkpoint_size"], "state": existing["state"], "path": existing["checkpoint_path"]}
            checkpoint_id = new_id()
            path = self.store.root / "checkpoints" / f"{checkpoint_id}.json"
            root_identity, root_fd, _ = _pin_directory(self.store.root)
            checkpoints_fd = -1
            try:
                checkpoints_fd = _mkdir_chain_at(root_fd, "checkpoints")
                _write_bytes_at(checkpoints_fd, f"{checkpoint_id}.json", durable_bytes)
                os.fsync(checkpoints_fd)
            finally:
                if checkpoints_fd >= 0:
                    os.close(checkpoints_fd)
                os.close(root_fd)
                _close_pinned(root_identity)
            if durable_bytes != durable_json_bytes(payload):
                raise ConflictError("checkpoint serializer changed while writing")
            digest = sha256_bytes(durable_bytes)
            # atomic_json_write fsyncs the file; fsync the containing directory
            # as well so the rename survives a sudden power loss.
            timestamp = now()
            with self.store._transaction():
                self.store.conn.execute("INSERT INTO recovery_checkpoints(id, attempt_id, task_id, executor_id, runtime_epoch, lease_id, fence, nonce, checkpoint_path, checkpoint_digest, checkpoint_size, state, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'durable', ?, ?)", (checkpoint_id, attempt_id, row["task_id"], row["executor_id"], current, row["lease_id"], row["fence"], nonce, str(path), digest, len(durable_bytes), timestamp, timestamp))
            return {"checkpoint_id": checkpoint_id, "attempt_id": attempt_id, "task_id": row["task_id"], "runtime_epoch": current, "nonce": nonce, "digest": "sha256:" + digest, "size": len(durable_bytes), "state": "durable", "path": str(path)}

    create_checkpoint = checkpoint_attempt

    def request_reboot(self, body, *, identity=None):
        """Execute only an allowlisted reboot command after durable checkpointing."""
        body = _wire_object(
            body,
            required=("nonce", "authorization", "runtime_epoch"),
            allowed=("checkpoint_id", "attempt_id", "nonce", "authorization", "runtime_epoch", "command"),
        )
        _wire_string(body, "nonce")
        _wire_string(body, "authorization")
        _wire_integer(body, "runtime_epoch", positive=True)
        for field in ("checkpoint_id", "attempt_id"):
            if field in body and body[field] is not None:
                _wire_string(body, field)
        if "command" in body and body["command"] is not None:
            _wire_string(body, "command")
        # Claim and consume the one-shot authorization in the same SQLite
        # transaction as the durable-state transition.  The executor is
        # intentionally called after commit (it may block or terminate the
        # process), but no competing request can pass the claim meanwhile.
        with self.store._mutex:
            self._assert_mutation_admitted()
            current = self.store._validate_runtime_epoch(body.get("runtime_epoch"), identity="executor", required=True)
            row = self._checkpoint_row(body.get("checkpoint_id"), body.get("attempt_id"))
            self._assert_attempt_identity(row, identity)
            if row["state"] in {"executed", "resumed"} and row["recovery_receipt_json"]:
                # A completed request is safely replayable, but still require
                # the exact original nonce and authorization.
                self._reboot_authorized(body, row["attempt_id"], row["nonce"], allow_consumed=True)
                return json.loads(row["recovery_receipt_json"])
            self._reboot_authorized(body, row["attempt_id"], row["nonce"])
            command = str(body.get("command") or "reboot")
            if command not in self.reboot_allowlist:
                raise ValidationError("reboot command is not allowlisted", details={"command": command, "allowlist": sorted(self.reboot_allowlist)})
            if int(row["runtime_epoch"]) != self.store._current_runtime_epoch():
                raise LeaseError("reboot checkpoint belongs to a stale runtime epoch")
            attempt = self.store.conn.execute("SELECT * FROM attempts WHERE id=?", (row["attempt_id"],)).fetchone()
            self._validate_attempt_lease(attempt, {**body, "lease_id": row["lease_id"], "fence": row["fence"]}, current)
            checkpoint_bytes = Path(row["checkpoint_path"]).read_bytes()
            if sha256_bytes(checkpoint_bytes) != row["checkpoint_digest"]:
                raise ConflictError("recovery checkpoint digest mismatch")
            checkpoint = json.loads(checkpoint_bytes.decode("utf-8"))
            if row["state"] != "durable":
                raise ConflictError("reboot has already been requested", details={"state": row["state"]})
            if self.reboot_executor is None:
                raise ConflictError("reboot executor is unavailable; tests must inject a safe executor")
            timestamp = now()
            with self.store._transaction():
                consumed = self.store.conn.execute("UPDATE attempts SET recovery_nonce_used=1 WHERE id=? AND recovery_nonce_used=0", (row["attempt_id"],))
                if consumed.rowcount != 1:
                    raise ConflictError("recovery authorization has already been consumed")
                claimed = self.store.conn.execute("UPDATE recovery_checkpoints SET state='reboot_requested', updated_at=? WHERE id=? AND state='durable'", (timestamp, row["id"]))
                if claimed.rowcount != 1:
                    raise ConflictError("reboot has already been requested", details={"state": row["state"]})
        executor = self.reboot_executor
        import inspect
        try:
            signature = inspect.signature(executor)
        except (TypeError, ValueError):
            # Some extension/callable objects do not expose a signature.  A
            # single positional invocation is the only safe fallback; never
            # retry after a TypeError raised by the executor itself.
            call = lambda: executor(command, checkpoint)
        else:
            try:
                signature.bind(command=command, checkpoint=checkpoint)
            except TypeError:
                signature.bind(command, checkpoint)
                call = lambda: executor(command, checkpoint)
            else:
                call = lambda: executor(command=command, checkpoint=checkpoint)
        try:
            outcome = call()
        except Exception as exc:
            failure = {"type": "runtime.recovery.receipt", "version": 1, "checkpoint_id": row["id"], "attempt_id": row["attempt_id"], "task_id": row["task_id"], "runtime_epoch": current, "command": command, "status": "failed", "error": {"type": type(exc).__name__, "message": str(exc)}}
            with self.store._mutex:
                with self.store._transaction():
                    self.store.conn.execute("UPDATE recovery_checkpoints SET state='executor_failed', recovery_receipt_json=?, updated_at=? WHERE id=? AND state='reboot_requested'", (canonical_json(failure), now(), row["id"]))
            raise
        receipt = {"type": "runtime.recovery.receipt", "version": 1, "checkpoint_id": row["id"], "attempt_id": row["attempt_id"], "task_id": row["task_id"], "runtime_epoch": self.store._current_runtime_epoch(), "command": command, "status": "executed", "executor_result": outcome}
        with self.store._mutex:
            with self.store._transaction():
                self.store.conn.execute("UPDATE recovery_checkpoints SET state='executed', recovery_receipt_json=?, updated_at=? WHERE id=? AND state='reboot_requested'", (canonical_json(receipt), now(), row["id"]))
        return receipt

    @_verified_mutation
    def resume_attempt(self, body, *, identity=None):
        if isinstance(identity, dict):
            self._assert_local_claim_admission(identity.get("actor"), identity=identity)
        body = _wire_object(
            body,
            required=("nonce", "authorization", "runtime_epoch"),
            allowed=("checkpoint_id", "attempt_id", "nonce", "authorization", "runtime_epoch"),
        )
        _wire_string(body, "nonce")
        _wire_string(body, "authorization")
        _wire_integer(body, "runtime_epoch", positive=True)
        for field in ("checkpoint_id", "attempt_id"):
            if field in body and body[field] is not None:
                _wire_string(body, field)
        def attempt_resource(attempt):
            task_value = self.store.get_task(attempt["task_id"])
            admitted_spec, generation_intent = public_task_spec(task_value["task"].get("spec") or {})
            if task_value["task"].get("generation_intent") is not None:
                generation_intent = task_value["task"]["generation_intent"]
            resource = {
                "attempt_id": attempt["id"],
                "task_id": attempt["task_id"],
                "run_id": task_value["run"]["id"],
                "project_id": task_value["run"].get("project_id"),
                "lease_id": attempt["lease_id"],
                "fence": attempt["fence"],
                "lease_expires_at": attempt["lease_expires_at"],
                "runtime_epoch": attempt["runtime_epoch"],
                "input_object_ids": list(admitted_spec.get("input_object_ids") or []),
                "spec": admitted_spec,
            }
            if generation_intent is not None:
                resource["generation_intent"] = generation_intent
            binding = self.store.execution_binding(attempt["task_id"])
            if binding is not None:
                resource["execution_binding"] = binding
            return resource

        with self.store._mutex:
            current = self.store._validate_runtime_epoch(body.get("runtime_epoch"), identity="executor", required=True)
            row = self._checkpoint_row(body.get("checkpoint_id"), body.get("attempt_id"))
            self._assert_attempt_identity(row, identity)
            attempt_owner = self.store.conn.execute("SELECT executor_id FROM attempts WHERE id=?", (row["attempt_id"],)).fetchone()
            if attempt_owner is None:
                raise ConflictError("resume executor is unresolved")
            self._assert_local_claim_admission(attempt_owner["executor_id"], identity=identity)
            # Fence validation precedes even a consumed checkpoint replay.
            # request_reboot consumes the one-shot authorization. The exact
            # consumed token remains the authorization for this checkpoint's
            # one successful resume; it is not a newly reusable nonce.
            self._reboot_authorized(body, row["attempt_id"], row["nonce"], allow_consumed=True)
            if row["state"] == "resumed" and row["recovery_receipt_json"]:
                receipt = json.loads(row["recovery_receipt_json"])
                attempt = self.store.conn.execute("SELECT * FROM attempts WHERE id=?", (receipt["attempt_id"],)).fetchone()
                if attempt:
                    return {"receipt": receipt, "attempt": attempt_resource(attempt)}
            activation = identity.get("qualified_activation") if isinstance(identity, dict) else None
            owner_id = activation.get("task_id") if isinstance(activation, dict) else row["task_id"]
            if self._task_drain(owner_id) is not None:
                raise ConflictError("remote drain blocks fresh checkpoint resume")
            if row["state"] not in {"recovered", "reboot_requested", "executed"}:
                raise ConflictError("checkpoint is not ready for resume", details={"state": row["state"]})
            checkpoint_bytes = Path(row["checkpoint_path"]).read_bytes()
            if sha256_bytes(checkpoint_bytes) != row["checkpoint_digest"]:
                raise ConflictError("recovery checkpoint digest mismatch")
            checkpoint = json.loads(checkpoint_bytes.decode("utf-8"))
            binding = self.store.execution_binding(row["task_id"])
            placement = self._trusted_execution_placement(identity)
            if binding is not None:
                if placement is None:
                    raise AuthorizationError("worker credential has no execution placement")
                if not execution_placement_matches(binding["resolved_target"], placement):
                    raise AuthorizationError("worker credential placement cannot resume this task")
                if not self._placement_recovery_qualification_matches(row["task_id"], placement):
                    raise AuthorizationError("worker credential qualification cannot resume this task")
                self.store.reset_execution_attempt(row["task_id"], runtime_epoch=current)
            # Claim this exact task.  Never use claim_next here: a mismatch
            # must not consume an unrelated queued task.
            lease_id = new_id()
            claim = self.store._claim_task(
                row["task_id"], row["executor_id"], lease_id,
                runtime_epoch=current, allow_provider_recovery=True,
            )
            task = claim["task"]
            if task.get("status") != "running" or task.get("id") != row["task_id"]:
                raise ConflictError("checkpoint task is not queued for resume")
            attempt_id = new_id()
            with self.store._transaction():
                self.store.conn.execute("INSERT INTO attempts(id, task_id, lease_id, fence, executor_id, lease_expires_at, settled, runtime_epoch) VALUES (?, ?, ?, ?, ?, ?, 0, ?)", (attempt_id, row["task_id"], lease_id, task["lease_fence"], row["executor_id"], task["lease_expires_at"], current))
                self.store.conn.execute("UPDATE tasks SET attempt_id=? WHERE id=? AND status='running'", (attempt_id, row["task_id"]))
                resumed_binding = self.store.bind_execution_attempt(
                    row["task_id"], attempt_id=attempt_id, lease_id=lease_id,
                    fence=task["lease_fence"], executor_id=row["executor_id"],
                    runtime_epoch=current, placement=placement,
                ) if binding is not None else None
                if resumed_binding is not None:
                    self.store._append_event(
                        task["run_id"], row["task_id"], "task.execution_bound",
                        {
                            "attempt_id": attempt_id,
                            "lease_id": lease_id,
                            "fence": task["lease_fence"],
                            "runtime_epoch": current,
                            "execution_binding": resumed_binding,
                            "recovery": "checkpoint_authorized_resume",
                        },
                    )
            resumed_attempt = self.store.conn.execute("SELECT * FROM attempts WHERE id=?", (attempt_id,)).fetchone()
            receipt = {"type": "runtime.recovery.receipt", "version": 1, "checkpoint_id": row["id"], "attempt_id": resumed_attempt["id"], "task_id": row["task_id"], "runtime_epoch": current, "command": "resume", "status": "resumed", "checkpoint_digest": "sha256:" + row["checkpoint_digest"], "checkpoint": checkpoint}
            with self.store._transaction():
                self.store.conn.execute("UPDATE recovery_checkpoints SET state='resumed', recovery_receipt_json=?, updated_at=? WHERE id=? AND state IN ('recovered', 'reboot_requested', 'executed')", (canonical_json(receipt), now(), row["id"]))
            return {"receipt": receipt, "attempt": attempt_resource(resumed_attempt)}

    resume = resume_attempt

    @_verified_mutation
    def heartbeat_attempt(self, attempt_id, body, *, idempotency_key=None, identity=None):
        idempotency_key = require_idempotency_key(idempotency_key)
        _require_runtime_epoch_for_lease(body)
        body = _wire_object(
            body,
            required=("lease_id", "fence", "runtime_epoch"),
            allowed=("lease_id", "fence", "runtime_epoch", "lease_seconds", "progress"),
        )
        _wire_string(body, "lease_id")
        # Fence zero is deliberately accepted as a typed stale fence. The
        # lease validator must classify it as LeaseError, not ValidationError.
        _wire_integer(body, "fence")
        _wire_integer(body, "runtime_epoch", positive=True)
        if "lease_seconds" in body and (
            isinstance(body["lease_seconds"], bool)
            or not isinstance(body["lease_seconds"], int)
            or body["lease_seconds"] <= 0
        ):
            raise ValidationError("lease_seconds must be a positive integer")
        progress = body.get("progress")
        if progress is not None:
            if not isinstance(progress, Mapping):
                raise ValidationError("progress must be an object")
            unexpected = set(progress) - {"phase", "percent", "current", "total"}
            if unexpected:
                raise ValidationError("progress contains unsupported fields", details={"fields": sorted(unexpected)})
            normalized_progress = {}
            if "phase" in progress:
                phase = progress["phase"]
                if not isinstance(phase, str) or not phase.strip() or len(phase) > 128:
                    raise ValidationError("progress.phase must be a non-empty string of at most 128 characters")
                normalized_progress["phase"] = phase.strip()
            for key in ("percent", "current", "total"):
                if key not in progress:
                    continue
                value = progress[key]
                if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(float(value)):
                    raise ValidationError(f"progress.{key} must be a finite number")
                if key == "percent" and not 0 <= float(value) <= 100:
                    raise ValidationError("progress.percent must be between 0 and 100")
                if key == "total" and float(value) < 1:
                    raise ValidationError("progress.total must be at least 1")
                if key == "current" and float(value) < 0:
                    raise ValidationError("progress.current must be non-negative")
                normalized_progress[key] = value
            if not normalized_progress:
                raise ValidationError("progress must contain phase, percent, current, or total")
            body["progress"] = normalized_progress
        with self.store._mutex:
            row = self.store.conn.execute("SELECT * FROM attempts WHERE id=?", (attempt_id,)).fetchone()
            self._assert_attempt_identity(row, identity)
            current = self.store._current_runtime_epoch()
            self.store._validate_runtime_epoch(body.get("runtime_epoch"), identity="executor", identity_id=row["executor_id"] if row else None, required=True)
            task = self.store.conn.execute("SELECT * FROM tasks WHERE id=?", (row["task_id"],)).fetchone() if row else None
            project_id = self.store.conn.execute("SELECT project_id FROM runs WHERE id=?", (task["run_id"],)).fetchone()[0] if task else "unscoped"
            request_hash = hashlib.sha256(canonical_json({"attempt_id": attempt_id, "body": body}).encode()).hexdigest()
            replay = self._command_replay("attempt.heartbeat", attempt_id, idempotency_key, request_hash, project_id=project_id or "unscoped")
            if replay is not None:
                return replay
            self._validate_attempt_lease(row, body, current)
            recorded = None
            def record(value):
                nonlocal recorded
                expires = value["task"].get("lease_expires_at")
                self.store.conn.execute("UPDATE attempts SET lease_expires_at=? WHERE id=?", (expires, attempt_id))
                if progress is not None:
                    self.store._append_event(task["run_id"], row["task_id"], "task.progress", progress)
                result = {"attempt_id": attempt_id, "task_id": row["task_id"], "lease_id": row["lease_id"], "fence": row["fence"], "lease_expires_at": expires, "runtime_epoch": self.store._current_runtime_epoch()}
                recorded = self._command_record("attempt.heartbeat", attempt_id, idempotency_key, request_hash, result, project_id=project_id or "unscoped")
            self.store.heartbeat_task(row["task_id"], row["lease_id"], fence=row["fence"], lease_seconds=body.get("lease_seconds", 30), record=record)
            return recorded

    @_verified_mutation
    def fail_attempt(self, attempt_id, body, *, idempotency_key=None, identity=None):
        idempotency_key = require_idempotency_key(idempotency_key)
        _require_runtime_epoch_for_lease(body)
        body = _wire_object(
            body,
            required=("lease_id", "fence", "runtime_epoch"),
            allowed=("lease_id", "fence", "runtime_epoch", "error", "reason"),
        )
        _wire_string(body, "lease_id")
        # A typed fence of zero is stale lease state, not malformed wire.
        _wire_integer(body, "fence")
        _wire_integer(body, "runtime_epoch", positive=True)
        with self.store._mutex:
            row = self.store.conn.execute("SELECT * FROM attempts WHERE id=?", (attempt_id,)).fetchone()
            self._assert_attempt_identity(row, identity)
            if not row:
                raise LeaseError("attempt lease is stale or already settled")
            current = self.store._current_runtime_epoch()
            self.store._validate_runtime_epoch(body["runtime_epoch"], identity="executor", identity_id=row["executor_id"], required=True)
            task = self.store.conn.execute("SELECT * FROM tasks WHERE id=?", (row["task_id"],)).fetchone() if row else None
            project_id = self.store.conn.execute("SELECT project_id FROM runs WHERE id=?", (task["run_id"],)).fetchone()[0] if task else "unscoped"
            request_hash = hashlib.sha256(canonical_json({"attempt_id": attempt_id, "body": body}).encode()).hexdigest()
            replay = self._command_replay("attempt.fail", attempt_id, idempotency_key, request_hash, project_id=project_id or "unscoped")
            if replay is not None:
                return replay
            self._validate_attempt_lease(row, body, current)
            if "reason" in body:
                raise ValidationError("reason is not supported; use error")
            failure = body.get("error") or {"code": "executor_failed"}
            recorded = None
            def record(value, *, event_ids=(), primary_stream_id=None, resulting_stream_seq=None):
                nonlocal recorded
                recorded = self._command_record("attempt.fail", attempt_id, idempotency_key, request_hash, self._task_resource(value), project_id=project_id or "unscoped", event_ids=event_ids, primary_stream_id=primary_stream_id, resulting_stream_seq=resulting_stream_seq)
            self.store.fail_task(row["task_id"], row["lease_id"], failure, fence=row["fence"], attempt_id=attempt_id, record=record)
            return recorded

    def events_page(self, aggregate_id=None, *, cursor=None, limit=50, from_=None):
        scope = f"events:{aggregate_id or '*'}"
        limit, decoded = _page_args(cursor, limit)
        if decoded is not None and decoded.get("s") != scope:
            raise InvalidRequestError("cursor does not belong to this collection")
        if from_ not in (None, "latest") or (from_ == "latest" and decoded is not None):
            raise InvalidRequestError("from must be latest and cannot be combined with cursor")
        where = " WHERE task_id = ? OR run_id = ?" if aggregate_id else ""
        filter_args = (aggregate_id, aggregate_id) if aggregate_id else ()
        if from_ == "latest":
            row = self.store.conn.execute(
                "SELECT id FROM events" + where + " ORDER BY id DESC LIMIT 1", filter_args
            ).fetchone()
            return {"items": [], "next_cursor": _page_cursor(scope, (str(row["id"] if row else 0),), numeric=True)}
        after = 0
        if decoded is not None:
            key = decoded["k"]
            if len(key) != 1 or not isinstance(key[0], str) or not key[0].isdecimal():
                raise InvalidRequestError("cursor is invalid")
            try:
                after = int(key[0])
            except ValueError as exc:
                raise InvalidRequestError("cursor is invalid") from exc
            if after > 2**63 - 1:
                raise InvalidRequestError("cursor is invalid")
        polling = decoded is not None and decoded.get("numeric") is True
        where = " WHERE id > ?" + (" AND (task_id = ? OR run_id = ?)" if aggregate_id else "")
        args = (after, *filter_args)
        if decoded is not None and not polling:
            # Old cursors used string keys; preserve their historical page bytes.
            where += " AND CAST(id AS TEXT) > ?"
            args += (key[0],)
        rows = self.store.conn.execute(
            "SELECT * FROM events" + where + " ORDER BY id LIMIT ?",
            (*args, limit + 1),
        ).fetchall()
        has_more = len(rows) > limit
        selected = rows[:limit]
        return {
            "items": [{"event_id": str(row["id"]), "sequence": int(row["id"]), "cursor": str(row["id"]), "event_type": row["kind"], "aggregate_type": "task" if row["task_id"] else "run", "aggregate_id": row["task_id"] or row["run_id"], "payload": json.loads(row["payload_json"]), "occurred_at": row["created_at"]} for row in selected],
            "next_cursor": _page_cursor(scope, (str(selected[-1]["id"]),), numeric=polling) if (has_more or (polling and selected)) else (cursor if polling else None),
        }

"""Authenticate provider annotations against sealed requests and recorded boundaries.

This module consumes provider observations; it never executes submitted edits.
Command execution, conflict detection and inverse construction belong to Agent.
"""
from __future__ import annotations

import copy
import hashlib
import re
from typing import cast

from .timeline_commit_producer import value_equal
from .timeline_commit_validation import digest, validate_commit_value
from .util import canonical_json


def require(condition, message):
    if not condition:
        from .timeline_commit_store import reject
        reject("invalid_records", message, status=422)


def images(document):
    return {"parent": document["parent_revision"], **{
        "shot-revision:" + row["revision_id"]: row for row in document["shot_revisions"]}, **{
        "internal-revision:" + row["revision_id"]: row for row in document["internal_timeline_revisions"]}}


def normalized_path(ref, path):
    if ref == "parent" and path[:1] in (["clips"], ["registry"]):
        return ["config", *path]
    return list(path)


_TEXT_BINDING_REF = re.compile(
    r"occurrence:([^/]+)/text-binding:(prompt|voiceover_script|transcript)"
    r"(?::([a-z][a-z0-9-]{0,63}))?\Z"
)


def _text_binding_key(kind, slot):
    return kind + (":" + slot if slot is not None else "")


def _text_binding_members(owner, rows):
    require(isinstance(rows, list), "provider text-binding collection is absent or malformed")
    members = []
    for row in rows:
        require(isinstance(row, dict) and isinstance(row.get("kind"), str)
                and (row.get("slot") is None or isinstance(row.get("slot"), str)),
                "provider text-binding collection has an invalid identity")
        member = owner + "/text-binding:" + _text_binding_key(row["kind"], row.get("slot"))
        require(member not in members, "provider text-binding collection has an ambiguous identity")
        members.append(member)
    return members


def _text_binding_site(boundary, ref):
    collection = ref.endswith("/collection:text-binding")
    if collection:
        owner = ref.removesuffix("/collection:text-binding")
        owner_match = re.fullmatch(r"occurrence:([^/]+)", owner)
        require(owner_match is not None, "provider text-binding collection is outside its authenticated boundary")
        if owner_match is None:
            raise AssertionError("unreachable text-binding collection alias")
        occurrence, kind, slot = owner_match.group(1), None, None
    else:
        match = _TEXT_BINDING_REF.fullmatch(ref)
        require(match is not None, "provider text-binding alias is outside its authenticated boundary")
        if match is None:
            raise AssertionError("unreachable text-binding alias")
        occurrence, kind, slot = match.groups()
        require(kind == "prompt" or slot is None,
                "provider text-binding alias has an invalid slot")
    owner = "occurrence:" + occurrence
    rows = boundary.get("parent", {}).get("payload", {}).get("occurrences", [])
    matches = [row for row in rows if isinstance(row, dict) and row.get("occurrence_id") == occurrence]
    require(len(matches) == 1, "provider text-binding occurrence is outside or ambiguous in its boundary")
    shot_ref = "shot-revision:" + str(matches[0].get("shot_revision_id"))
    require(shot_ref in boundary, "provider text-binding occurrence has no authenticated shot")

    bindings = boundary[shot_ref]["payload"].get("text_bindings", [])
    require(isinstance(bindings, list),
            "provider text-binding collection is malformed")
    for row in bindings:
        require(isinstance(row, dict) and row.get("kind") in {"prompt", "voiceover_script", "transcript"}
                and (row.get("slot") is None or isinstance(row.get("slot"), str)),
                "provider text-binding collection has an invalid identity")
    if collection:
        _text_binding_members(owner, bindings)
        return shot_ref, ["text_bindings"]
    identity = _text_binding_key(kind, slot)
    matching = [row for row in bindings
                if _text_binding_key(row["kind"], row.get("slot")) == identity]
    require(len(matching) <= 1, "provider text-binding alias is ambiguous in its boundary")
    return shot_ref, ["text_bindings", "kind:" + identity]


def site(boundary, ref, path, continuations=None):
    """Resolve root and native aliases in one authenticated closure image."""
    path = list(path)
    if ref == "timeline":
        return ref, []
    if ref in boundary:
        return ref, normalized_path(ref, path)
    if ref.startswith(("shot-revision:", "internal-revision:")) and continuations:
        seen = set()
        while ref not in boundary and ref in continuations and ref not in seen:
            seen.add(ref)
            successors = continuations[ref]
            require(len(successors) == 1, "provider source has ambiguous authenticated successors")
            ref = next(iter(successors))
        if ref in boundary:
            return ref, path
    if "/text-binding:" in ref:
        binding_ref, binding_path = _text_binding_site(boundary, ref)
        return binding_ref, [*binding_path, *path]
    if "/collection:" in ref:
        owner, family = ref.rsplit("/collection:", 1)
        if family == "text-binding":
            return _text_binding_site(boundary, owner + "/collection:text-binding")
        if family == "asset":
            require(owner == "parent",
                    "provider collection alias is outside its authenticated boundary")
            # The native asset collection is a shape guard over the complete
            # parent image.  Its recorder state includes both authored registry
            # mirrors, so it must retain the parent root as its physical site.
            return "parent", []
        if family in {"clip", "track", "occurrence"}:
            prefix = ["config", family + "s"] if owner == "parent" and family != "occurrence" else [family + "s"]
            return site(boundary, owner if owner == "parent" else owner + "/source", prefix)
        require(False, "provider collection alias is outside its authenticated boundary")
    kind, _, identity = ref.partition(":")
    field = {"shot": "shot_id", "internal": "timeline_id"}.get(kind)
    if field and "/" not in identity:
        matches = [key for key, image in boundary.items() if image.get(field) == identity]
        require(len(matches) == 1, "provider alias is outside or ambiguous in its boundary")
        return matches[0], path[1:] if path[:1] == ["payload"] else path
    owner, _, entity = ref.partition("/")
    if owner == "parent":
        if entity == "source":
            return "parent", ["config", *path]
        if entity == "registry":
            return "parent", ["config", "registry", *path]
        if entity.startswith(("clip:", "track:")):
            family, identity = entity.split(":", 1)
            return "parent", ["config", family + "s", "id:" + identity, *path]
        if entity.startswith("asset:"):
            return "parent", ["config", "registry", "assets", entity[6:], *path]
    if owner.startswith("occurrence:"):
        identity = owner[len("occurrence:"):]
        if not entity:
            return "parent", ["occurrences", "occurrence_id:" + identity, *path]
        rows = boundary["parent"]["payload"]["occurrences"]
        matches = [row for row in rows if row["occurrence_id"] == identity]
        require(len(matches) == 1, "provider occurrence alias is outside its boundary")
        shot_ref = "shot-revision:" + matches[0]["shot_revision_id"]
        require(shot_ref in boundary, "provider occurrence has no authenticated shot")
        if entity == "shot":
            return shot_ref, path[1:] if path[:1] == ["payload"] else path
        internal = "internal-revision:" + boundary[shot_ref]["internal_timeline_revision_id"]
        require(internal in boundary, "provider occurrence has no authenticated internal timeline")
        if entity == "source":
            return internal, path
        if entity == "registry":
            return internal, ["registry", *path]
        if entity.startswith(("clip:", "track:")):
            family, identity = entity.split(":", 1)
            return internal, [family + "s", "id:" + identity, *path]
        if entity.startswith("asset:"):
            return internal, ["registry", "assets", entity[6:], *path]
    require(False, "provider alias is outside its authenticated boundary")


def location(payload, path, *, absent_items=False):
    node = payload
    for index, token in enumerate(path):
        if isinstance(node, list):
            if index and path[index - 1] == "text_bindings" and token.startswith("kind:"):
                identity = token.removeprefix("kind:")
                matches = [row for row in node if isinstance(row, dict)
                           and _text_binding_key(row.get("kind"), row.get("slot")) == identity]
                require(len(matches) <= 1, "provider observation has an ambiguous text-binding path")
                if not matches:
                    return {"state": "absent"}
                node = matches[0]
                continue
            key, separator, identity = token.partition(":")
            matches = [row for row in node if isinstance(row, dict) and row.get(key) == identity]
            if absent_items and separator and not matches:
                return {"state": "absent"}
            require(separator and len(matches) == 1, "provider observation has an ambiguous item path")
            node = matches[0]
        elif isinstance(node, dict) and token in node:
            node = node[token]
        else:
            return {"state": "absent"}
    return {"state": "present", "value": node}


def stored_path(payload, ref, path):
    if (ref == "parent" and path[:2] in (["config", "clips"], ["config", "registry"])
            and path[1] not in payload.get("config", {}) and path[1] in payload):
        return path[1:]
    return path


def normalized(boundary, value, continuations=None):
    ref, path = site(boundary, value["ref"], value["path"], continuations)
    return {**value, "ref": ref, "path": path}


def native_site(boundary, ref, path):
    if ref.startswith("occurrence:") and ref.endswith("/shot") and path[:1] != ["payload"]:
        return site(boundary, ref.removesuffix("/shot"), path)
    if ref.startswith("shot:") and "/" not in ref and path[:1] != ["payload"]:
        return "timeline", []
    return site(boundary, ref, path)


def covers(dependencies, read):
    for dependency in dependencies:
        if value_equal(dependency, read):
            return True
        if dependency["kind"] == "scope" and (
                dependency["ref"] == "timeline" or dependency["ref"] == read["ref"]
                and read["path"][:len(dependency["path"])] == dependency["path"]):
            return True
    return False


def validate_read(boundary, read, continuations=None):
    read = normalized(boundary, read, continuations)
    if read["kind"] == "scope":
        return read
    payload = boundary[read["ref"]]["payload"]
    observed = location(payload, stored_path(payload, read["ref"], read["path"]))
    if read["kind"] == "field":
        require(value_equal(observed, read["state"]), "declared field read differs from its input boundary")
    else:
        rows = observed.get("value")
        if not isinstance(rows, list):
            require(False, "declared collection is absent at its input boundary")
            return read
        key = "occurrence_id" if read["path"][-1:] == ["occurrences"] else "id"
        members = [row[key] for row in rows if isinstance(row, dict) and isinstance(row.get(key), str)]
        require(len(members) == len(rows)
                and sorted(members) == read["members"]
                and (read["order"] is None or members == read["order"]),
                "declared collection read differs from its input boundary")
    return read


def _omitted_inverse_created_is_authenticated(submitted, record, records):
    """Allow the inverse provider to report restored allocation facts.

    ``created`` is optional on the wire.  A raw inverse request therefore has
    no caller allocation claim, while the provider must still return the
    authenticated restoration facts in its record.  This helper only admits
    that request/recorder shape; the physical bindings, materialization,
    destination, history, and undo guards below and in the store remain the
    authority for the restored identities.
    """
    if "created" in submitted or submitted.get("op") != "timeline.inverse":
        return False
    args = submitted.get("args")
    command = record["command"]
    created = command.get("created")
    if not isinstance(args, dict) or not isinstance(created, list) or not created:
        return False
    if records.get("undo_of") != args.get("publications"):
        return False
    requested_steps = args.get("steps")
    if records.get("undo_steps") != requested_steps:
        return False
    facts = record["created"]
    if not isinstance(facts, list) or [item["ref"] for item in facts] != created:
        return False
    restoration_writes = {
        write["ref"]
        for write in [*record["writes"], *record["derived_writes"]]
        if write["path"] == []
        and write["before"] == {"state": "absent"}
        and write["after"]["state"] == "present"
    }
    return set(created) <= restoration_writes


def validate_claims(request, records):
    commands = records["commands"]
    require(len(commands) == len(request["commands"]), "provider command count differs from request")
    for submitted, record in zip(request["commands"], commands):
        core_matches = all(value_equal(submitted.get(key), record["command"].get(key))
                           for key in ("schema_version", "op", "version", "select", "args"))
        created_matches = value_equal(submitted.get("created", []), record["command"].get("created", []))
        inverse_restoration = _omitted_inverse_created_is_authenticated(submitted, record, records)
        require(core_matches and (created_matches or inverse_restoration),
                "provider executed a different command")


def _authoring_identity(kind, *parts):
    encoded = "\0".join([kind, *(canonical_json(part) for part in parts)]).encode("utf-8")
    return f"{kind}-" + hashlib.sha256(encoded).hexdigest()


def _sequential_assertion(claim, ordinals, sequential, key):
    matches = []
    for (ordinal, _), pair in sequential["binding_pairs"].items():
        if ordinal not in ordinals or key not in pair["original"]:
            continue
        original_input = images(sequential["original"][ordinal]["input"])
        original = pair["original"][key]
        if claim["ref"] not in {pair["original"]["ref"], original["ref"]}:
            continue
        if value_equal(normalized(original_input, claim), normalized(original_input, original)):
            matches.append((ordinal, pair["landing"][key]))
    require(len(matches) == 1, "submitted assertion has no unique authenticated sequential binding")
    return matches[0]


def validate_step(request, records, step, boundary, batch_reads, continuations, command_inputs=None, sequential=None):
    submitted = next((item for item in request.get("steps", []) if item["id"] == step["id"]), None)
    dependencies = step["dependencies"]
    step_reads = []
    for read in (submitted or {}).get("reads", []):
        if sequential is not None and "binding_pairs" in sequential:
            _, read = _sequential_assertion(read, step["command_ordinals"][:1], sequential, "dependency")
        step_reads.append(validate_read(boundary, read, continuations))
    for read in [*batch_reads, *step_reads]:
        require(covers(dependencies, read), "provider dependency union omits a declared read")
    for ordinal in step["command_ordinals"]:
        record = records["commands"][ordinal]
        command_boundary = (command_inputs or {}).get(ordinal, boundary)
        created = {item["ref"] for item in record["created"]}
        for read in record["reads"]:
            if read["ref"] in created and read["state"] == {"state": "absent"}:
                continue
            ref, path = native_site(command_boundary, read["ref"], read["path"])
            if ref == "timeline" or not path or "/collection:" in read["ref"]:
                capture = {"kind": "scope", "ref": ref, "path": []}
                if "/collection:" in read["ref"] and ref != "timeline":
                    observed = location(command_boundary[ref]["payload"], path).get("value")
                    if isinstance(observed, list):
                        if read["ref"].endswith("/collection:text-binding"):
                            owner = read["ref"].rsplit("/collection:", 1)[0]
                            members = _text_binding_members(owner, observed)
                        else:
                            key = "occurrence_id" if path[-1:] == ["occurrences"] else "id"
                            members = [row[key] for row in observed]
                        capture = {"kind": "collection", "ref": ref, "path": path,
                                   "members": sorted(members), "order": members}
            else:
                capture = {"kind": "field", "ref": ref, "path": path, "state": read["state"]}
            require(covers(dependencies, capture), "provider dependency union omits a captured read")
        for binding in record["bindings"]:
            if "dependency" in binding:
                require(covers(dependencies, binding["dependency"]), "provider dependency union omits a bound read")
    assertions = (submitted or {}).get("patch", [])
    calls = [request["commands"][ordinal] for ordinal in step["command_ordinals"]]
    patches = [change for call in calls if call["op"] == "doc.patch" for change in call["args"]["changes"]]
    if submitted is not None and all(call["op"] == "doc.patch" for call in calls):
        require(value_equal(assertions, patches), "submitted step patch differs from its commands")
    for claim in assertions:
        matches = []
        claim_boundary = boundary
        if (sequential is not None and "binding_pairs" in sequential
                and any(value_equal(claim, patch) for patch in patches)):
            ordinal, claim = _sequential_assertion(claim, step["command_ordinals"], sequential, "change")
            claim_boundary = (command_inputs or {}).get(ordinal, boundary)
        for ordinal in step["command_ordinals"]:
            command_boundary = (command_inputs or {}).get(ordinal, boundary)
            for binding in records["commands"][ordinal]["bindings"]:
                if "change" in binding:
                    matches.append(normalized(command_boundary, {**binding["change"], "path": binding["path"]},
                                               continuations))
                    if (binding["change"].get("ref") == claim.get("ref")
                            and binding["change"].get("path") == claim.get("path")):
                        # A submitted claim belongs to the command that owns
                        # its input.  In a sequential step that input can be
                        # an intermediate materialized image, not the step's
                        # first (outer) boundary.
                        claim_boundary = command_boundary
        for effect in step["patch"]:
            if not any(effect.get("ref") == claim.get("ref")
                       and effect.get("path") == claim.get("path")
                       for claim in assertions):
                continue
            effect_boundary = boundary
            for ordinal in step["command_ordinals"]:
                command_boundary = (command_inputs or {}).get(ordinal, boundary)
                if any(binding.get("change", {}).get("ref") == effect.get("ref")
                       and binding.get("change", {}).get("path") == effect.get("path")
                       for binding in records["commands"][ordinal]["bindings"] if "change" in binding):
                    effect_boundary = command_boundary
            matches.append(normalized(effect_boundary,
                                      {**effect, "path": normalized_path(effect["ref"], effect["path"])},
                                      continuations))
        require(any(value_equal(normalized(claim_boundary, claim, continuations), match) for match in matches),
                "provider effects omit a submitted assertion")


def validate_bindings(request, records, expected, boundary, output, step, ordinal, continuations, original,
                      step_input, effect_boundaries=None, input_parent_revision=None, sequential=None):
    record = records["commands"][ordinal]
    for binding_index, binding in enumerate(record["bindings"]):
        if "physical_ref" not in binding:
            continue  # Original ABI-1 captures do not claim physical provenance.
        captured = binding.get("boundary", {})
        phase = captured.get("phase")
        require(phase in {"input", "batch-read", "effect"} and (phase != "batch-read" or ordinal == 0)
                and captured.get("base_revision_id") == request["base_revision_id"]
                and captured.get("base_publication_id") == request["base_publication_id"]
                and value_equal(captured.get("evaluated_head"), expected)
                and captured.get("step_id") == step["id"]
                and captured.get("command_ordinal") == ordinal,
                "provider binding boundary differs from the authenticated invocation")
        bound = boundary
        if phase == "effect":
            side, index = captured.get("side"), binding.get("effect_ordinal")
            require(binding["key"] == "commit.effect" and side in {"before", "after"}
                    and ordinal == step["command_ordinals"][-1]
                    and type(index) is int and 0 <= index < len(step["patch"]),
                    "provider effect binding is misattributed")
            require(step["patch"][index]["ref"] == binding["physical_ref"]
                    and step["patch"][index]["path"] == binding.get("path"),
                    "provider effect binding differs from the recorded effect")
            if effect_boundaries is not None:
                require(index in effect_boundaries,
                        "provider effect binding is outside an authenticated inverse stage")
                bound = effect_boundaries[index][0 if side == "before" else 1]
            else:
                bound = step_input if side == "before" else output
        elif binding["key"] == "commit.materialization":
            bound = step_input
        for key in ("command_ordinal", "step_id", "phase", "change_ordinal"):
            if key in binding:
                require(binding[key] == captured.get(key), "provider binding attribution is inconsistent")
        physical = binding["physical_ref"]
        resolve = site if binding["key"].startswith(("doc.patch:", "commit.")) else native_site
        pair = (sequential or {}).get("binding_pairs", {}).get((ordinal, binding_index))
        if pair is not None:
            require(pair["landing"]["physical_ref"] == physical
                    and pair["original"]["physical_ref"] == pair["source_physical_ref"],
                    "provider sequential source-to-landing binding is inconsistent")
            ref = physical
        else:
            ref, _ = (site(bound, binding["ref"], [], continuations) if resolve is site
                      else resolve(bound, binding["ref"], []))
        require(ref == physical or ref == "timeline" and binding["key"] in {"commit.read", "commit.atomic"},
                "provider alias names a different physical image")
        # Materialization observes the authenticated landing input, whose
        # physical sources can already be successors of the requested base.
        # Its owner/edge correspondence is verified below. Submitted aliases
        # still have to retain their original physical source.
        if (pair is None and ordinal == 0 and phase != "effect" and resolve is site and binding["ref"] != "timeline"
                and binding["key"] != "commit.materialization"):
            original_ref, _ = site(original, binding["ref"], [], continuations)
            continued_ref, _ = site(bound, original_ref, [], continuations)
            require(continued_ref == physical, "provider alias changed without an authenticated successor")
        image = bound.get(physical)
        revision_matches = image is not None and binding.get("revision_id") == image["revision_id"]
        if (not revision_matches and image is not None and physical == "parent"
                and phase == "effect" and captured.get("side") == "before"
                and effect_boundaries is None and input_parent_revision is not None):
            # Agent hydrates captured documents before deriving effect images.
            # Equal payloads alone cannot authorize a different parent pin.
            revision_matches = binding.get("revision_id") == input_parent_revision
        require(image is not None and binding.get("content_digest") == image["content_digest"]
                and revision_matches,
                "provider binding differs from its authenticated input image")
        if "owners" in binding:
            owners = []
            for row in bound["parent"]["payload"]["occurrences"]:
                shot_ref = "shot-revision:" + row["shot_revision_id"]
                shot = bound.get(shot_ref)
                if physical == shot_ref or shot is not None and physical == "internal-revision:" + shot["internal_timeline_revision_id"]:
                    owners.append("occurrence:" + row["occurrence_id"] + "/shot")
            require(set(owners) == set(binding["owners"]), "provider binding owners differ from its physical edges")
        if "change" in binding:
            change = binding["change"]
            require(change["ref"] == physical and normalized_path(physical, change["path"]) == binding.get("path"),
                    "provider binding path differs from its change")
            start, end = binding.get("write_range", [-1, -1])
            require(0 <= start <= end <= len(record["writes"]), "provider binding has an invalid write range")
            if record["command"]["op"] == "doc.patch":
                index = captured.get("change_ordinal")
                changes = request["commands"][ordinal]["args"]["changes"]
                submitted_boundary, submitted_change = boundary, change
                if pair is not None and sequential is not None:
                    submitted_boundary = images(sequential["original"][ordinal]["input"])
                    submitted_change = pair["original"]["change"]
                require(type(index) is int and 0 <= index < len(changes)
                        and value_equal(normalized(submitted_boundary, changes[index], continuations),
                                        normalized(submitted_boundary, submitted_change, continuations)),
                        "provider binding differs from the submitted change")
        if "dependency" in binding:
            dependency = binding["dependency"]
            require(dependency["ref"] == physical and dependency["path"] == binding.get("path"),
                    "provider read binding differs from its dependency")
        if "successor" in binding:
            from .timeline_materialization import edges
            before_rows, after_rows = edges({"parent_revision": boundary["parent"]}), edges({"parent_revision": output["parent"]})
            owner = binding.get("owner", "").removeprefix("occurrence:").removesuffix("/shot")
            successor = binding["successor"]
            require(binding["key"] == "commit.materialization" and owner in before_rows and owner in after_rows
                    and successor in output, "provider successor lacks an authenticated owner edge")
            before_shot = "shot-revision:" + before_rows[owner][1]
            after_shot = "shot-revision:" + after_rows[owner][1]
            require(before_shot in boundary and after_shot in output, "provider successor has an absent owner image")
            before_internal = "internal-revision:" + boundary[before_shot]["internal_timeline_revision_id"]
            after_internal = "internal-revision:" + output[after_shot]["internal_timeline_revision_id"]
            require((physical, successor, binding.get("edge_before"), binding.get("edge_after")) in {
                (before_shot, after_shot, before_internal, after_internal),
                (before_internal, after_internal, before_shot, after_shot)},
                "provider successor differs from its authenticated physical edges")


def project_observation(payload, path, state):
    """Project a recorder's full observed value, without interpreting edit operands."""
    if not path:
        require(state["state"] == "present", "provider removed an existing payload")
        return copy.deepcopy(state["value"])
    result = copy.deepcopy(payload)
    node = result
    for token in path[:-1]:
        if isinstance(node, list):
            key, _, identity = token.partition(":")
            matches = [row for row in node if row.get(key) == identity]
            require(len(matches) == 1, "provider observation has no unique ancestor")
            node = matches[0]
        else:
            require(isinstance(node, dict) and token in node, "provider observation has no ancestor")
            node = node[token]
    token = path[-1]
    if isinstance(node, list):
        key, _, identity = token.partition(":")
        indices = [index for index, row in enumerate(node) if row.get(key) == identity]
        require(len(indices) <= 1, "provider observation has an ambiguous item")
        if state["state"] == "absent":
            require(bool(indices), "provider removed an absent item")
            node.pop(indices[0])
        elif indices:
            node[indices[0]] = copy.deepcopy(state["value"])
        else:
            node.append(copy.deepcopy(state["value"]))
    else:
        require(isinstance(node, dict), "provider observation has a scalar ancestor")
        if state["state"] == "absent":
            node.pop(token, None)
        else:
            node[token] = copy.deepcopy(state["value"])
    return result


def _physical_owner(document, ref):
    """Return the occurrence owning an authenticated shot/internal image."""
    parent = document.get("parent", {}).get("payload", {})
    for row in parent.get("occurrences", []):
        occurrence = row.get("occurrence_id")
        shot_ref = "shot-revision:" + str(row.get("shot_revision_id"))
        if ref == shot_ref:
            return occurrence, row.get("shot_id")
        shot = document.get(shot_ref, {})
        if ref == "internal-revision:" + str(shot.get("internal_timeline_revision_id")):
            return occurrence, row.get("shot_id")
    return None


def _coherent_materialization(boundary, effect, effects):
    """Accept a physical turnover only when its sibling effect names its owner."""
    if not effects:
        return False
    parent = boundary.get("parent", {}).get("payload", {})
    occurrences = {row.get("occurrence_id"): row for row in parent.get("occurrences", [])}
    roots = [candidate for candidate in effects
             if not normalized_path(candidate["ref"], candidate["path"])
             and candidate["ref"].startswith("shot-revision:")]

    def payload(effect):
        if effect["op"] == "remove":
            value = effect.get("before")
            return value.get("value") if value.get("state") == "present" else None
        return effect.get("value")

    def shot_ids(image):
        return {binding.get("shot_id") for binding in (image or {}).get("text_bindings", [])
                if binding.get("shot_id") is not None}

    if effect["ref"] == "parent" and effect["path"][-1:] == ["shot_revision_id"]:
        occurrence = next((part.split(":", 1)[1] for part in effect["path"]
                           if part.startswith("occurrence_id:")), None)
        row = occurrences.get(occurrence)
        if row is None:
            return False
        return any(effect.get("value") == root["ref"].partition(":")[2]
                   and row.get("shot_id") in shot_ids(payload(root)) for root in roots)

    if effect["ref"].startswith(("shot-revision:", "internal-revision:")) and not effect["path"]:
        internal_id = effect["ref"].partition(":")[2]
        if effect["ref"].startswith("shot-revision:"):
            image = payload(effect) or {}
            internal_id = image.get("internal_timeline_revision_id")
        if internal_id is None:
            return False
        return any(root_payload.get("internal_timeline_revision_id") == internal_id
                   and any(row.get("shot_id") in shot_ids(root_payload) for row in occurrences.values())
                   for root in roots for root_payload in [payload(root) or {}])
    return False


def _materialization_input(boundary, original, effect, observed_path, effects=None):
    """Accept a rebased physical edge only across one authenticated owner."""
    if original is None:
        return False
    ref, path = effect["ref"], normalized_path(effect["ref"], effect["path"])
    if ref == "parent" and path[-1:] == ["shot_revision_id"]:
        owner_path = path[:-1]
        original_value = location(original[ref]["payload"], path)
        if original_value.get("state") != "present":
            return False
        owner = owner_path[-1].partition(":")[2] if owner_path[-1].startswith("occurrence_id:") else None
        current_value = location(boundary[ref]["payload"], path)
        if owner is None or current_value.get("state") != "present":
            return False
        old_ref = "shot-revision:" + str(original_value["value"])
        current_ref = "shot-revision:" + str(current_value["value"])
        old_owner = _physical_owner(original, old_ref)
        current_owner = _physical_owner(boundary, current_ref)
        return ((old_owner is not None and current_owner is not None
                 and old_owner == current_owner == (owner, old_owner[1]))
                or _coherent_materialization(boundary, effect, effects))
    if not path and ref.startswith(("shot-revision:", "internal-revision:")):
        old_owner = _physical_owner(original, ref)
        current_owner = _physical_owner(boundary, ref)
        return old_owner is not None or current_owner is not None or _coherent_materialization(boundary, effect, effects)
    return _coherent_materialization(boundary, effect, effects)


def _align_materialized_images(result, accepted):
    """Map provider-generated physical ids to the accepted authenticated images."""
    for ref, image in list(result.items()):
        if ref == "parent" or not ref.startswith(("shot-revision:", "internal-revision:")):
            continue
        candidates = [candidate for candidate, known in accepted.items()
                      if candidate.startswith(ref.split(":", 1)[0] + ":")
                      and value_equal(known["payload"], image["payload"])
                      and _physical_owner(result, ref) == _physical_owner(accepted, candidate)]
        if len(candidates) != 1:
            continue
        candidate = candidates[0]
        result[candidate] = copy.deepcopy(accepted[candidate])
        if candidate != ref:
            if ref.startswith("shot-revision:"):
                old_id, new_id = ref.partition(":")[2], candidate.partition(":")[2]
                for row in result["parent"]["payload"].get("occurrences", []):
                    if row.get("shot_revision_id") == old_id:
                        row["shot_revision_id"] = new_id
            else:
                old_id, new_id = ref.partition(":")[2], candidate.partition(":")[2]
                for shot_ref, shot in result.items():
                    if shot_ref.startswith("shot-revision:") and shot["payload"].get("internal_timeline_revision_id") == old_id:
                        shot["payload"]["internal_timeline_revision_id"] = new_id
            result.pop(ref)


def _parent_materialization_reconciles(result, accepted):
    """Recognize a landing parent whose only delta is authenticated shot turnover."""
    before = copy.deepcopy(result["parent"]["payload"])
    after = copy.deepcopy(accepted["parent"]["payload"])
    before_rows = {row.get("occurrence_id"): row for row in before.get("occurrences", [])}
    after_rows = {row.get("occurrence_id"): row for row in after.get("occurrences", [])}
    if set(before_rows) != set(after_rows):
        return False
    changed = False
    for occurrence, row in before_rows.items():
        other = after_rows[occurrence]
        old_ref, new_ref = row.get("shot_revision_id"), other.get("shot_revision_id")
        row.pop("shot_revision_id", None)
        other.pop("shot_revision_id", None)
        if old_ref != new_ref:
            changed = True
            if (_physical_owner(result, "shot-revision:" + str(old_ref)) is None
                    or _physical_owner(accepted, "shot-revision:" + str(new_ref)) is None):
                return False
    return changed and value_equal(before, after)


def _reconcile_materialized_owner_images(result, accepted):
    def owner_token(document, ref):
        image = document.get(ref, {})
        if ref.startswith("shot-revision:"):
            return "shot:" + str(image.get("payload", {}).get("internal_timeline_revision_id"))
        if ref.startswith("internal-revision:"):
            return ref
        return None

    owners = {owner_token(accepted, ref) for ref in accepted
              if ref.startswith(("shot-revision:", "internal-revision:"))}
    for owner in owners - {None}:
        result_refs = {ref for ref in result if owner_token(result, ref) == owner}
        accepted_refs = {ref for ref in accepted if owner_token(accepted, ref) == owner}
        for ref in result_refs - accepted_refs:
                result.pop(ref, None)
        for ref in accepted_refs:
            result[ref] = copy.deepcopy(accepted[ref])


def step_output(boundary, step, records, accepted, original=None):
    """Project complete authoritative effects solely to authenticate their boundaries."""
    result = copy.deepcopy(boundary)
    for effect in step["patch"]:
        ref, path = effect["ref"], normalized_path(effect["ref"], effect["path"])
        if ref != "parent" and not path:
            before = {"state": "present", "value": result[ref]["payload"]} if ref in result else {"state": "absent"}
            require(value_equal(before, effect["before"])
                    or _materialization_input(boundary, original, effect, path, step["patch"]),
                    "provider root effect has a different input")
            if effect["op"] == "remove":
                result.pop(ref, None)
            else:
                require(effect["op"] == "set", "provider root effect is not an observed value")
                result[ref] = {**copy.deepcopy(accepted.get(ref, {})), "revision_id": ref.partition(":")[2],
                               "content_digest": digest(effect["value"]), "payload": copy.deepcopy(effect["value"])}
                if ref.startswith("shot-revision:"):
                    result[ref]["internal_timeline_revision_id"] = effect["value"]["internal_timeline_revision_id"]
            continue
        require(ref in result, "provider effect addresses an absent root")
        payload = result[ref]["payload"]
        observed_path = stored_path(payload, ref, path)
        if effect["op"].startswith("list."):
            # List operations are Agent semantics. The recorder supplies the
            # complete resulting collection; Runtime only projects that value.
            observations = [write for ordinal in step["command_ordinals"]
                            for write in records["commands"][ordinal]["writes"]
                            if site(boundary, write["ref"], write["path"]) == (ref, path)]
            require(bool(observations), "provider list effect lacks a full collection observation")
            state = observations[-1]["after"]
        else:
            require(value_equal(location(payload, observed_path), effect["before"])
                    or _materialization_input(boundary, original, effect, observed_path, step["patch"]),
                    "provider effect has a different input value")
            state = {"state": "present", "value": effect["value"]} if effect["op"] == "set" else {"state": "absent"}
        result[ref]["payload"] = project_observation(payload, observed_path, state)
        if ref == "parent" and path[:2] in (["config", "clips"], ["config", "registry"]):
            mirror = path[1]
            if mirror in payload and mirror in result[ref]["payload"].get("config", {}):
                result[ref]["payload"][mirror] = copy.deepcopy(result[ref]["payload"]["config"].get(mirror))
        result[ref]["content_digest"] = digest(result[ref]["payload"])
    _align_materialized_images(result, accepted)
    # Bindings of complete effect images carry the provider's generated revision
    # names. Their payload digest must agree with the projected observations.
    for row in result["parent"]["payload"]["occurrences"]:
        ref = "shot-revision:" + row["shot_revision_id"]
        require(ref in result, "provider occurrence effect has no physical shot image")
        require(result[ref].get("shot_id", row["shot_id"]) == row["shot_id"],
                "provider occurrence effect changes physical shot ownership")
        result[ref]["shot_id"] = row["shot_id"]
    for ref, image in list(result.items()):
        known = accepted.get(ref)
        if ref == "parent":
            pins = [binding for ordinal in step["command_ordinals"]
                    for binding in records["commands"][ordinal]["bindings"]
                    if binding.get("key") == "commit.effect" and binding.get("physical_ref") == ref
                    and binding.get("boundary", {}).get("side") == "after"
                    and binding.get("content_digest") == image["content_digest"]]
            if pins:
                require(len({pin["revision_id"] for pin in pins}) == 1, "provider intermediate parent pins disagree")
                image["revision_id"] = pins[0]["revision_id"]
            else:
                reconciled = known is not None and _parent_materialization_reconciles(result, accepted)
                require(known is not None and (value_equal(known["payload"], image["payload"])
                                                or reconciled),
                        "provider intermediate parent lacks an effect image")
                result[ref] = copy.deepcopy(known)
                if reconciled:
                    _reconcile_materialized_owner_images(result, accepted)
        elif known is not None and value_equal(known["payload"], image["payload"]):
            result[ref] = copy.deepcopy(known)
    return result


def _inverse_stage_write_site(boundary, write):
    """Resolve a staged inverse write, including a root entering the closure."""
    ref, path = write["ref"], write["path"]
    # Native root captures name physical fields. The two parent mirrors can
    # differ between their separately recorded writes within a stage.
    if ref in boundary:
        return ref, path
    if (not path and ref.startswith(("shot-revision:", "internal-revision:"))
            and ref not in boundary):
        return ref, path
    return native_site(boundary, ref, path)


def _inverse_stage_state(boundary, ref, path):
    if ref not in boundary:
        return {"state": "absent"}
    return location(boundary[ref]["payload"], stored_path(boundary[ref]["payload"], ref, path),
                    absent_items=True)


def _inverse_stage_root(boundary, ref):
    """Observe authored aggregate roots through authenticated physical images."""
    kind, _, identity = ref.partition(":")
    if kind == "occurrence":
        state = location(boundary["parent"]["payload"], ["occurrences", "occurrence_id:" + identity],
                         absent_items=True)
        state = copy.deepcopy(state)
        if state["state"] == "present":
            assert isinstance(state["value"], dict)
            state["value"].pop("shot_revision_id", None)
            state["value"].pop("revision_id", None)
        return state, []
    matches = [(key, image) for key, image in boundary.items()
               if key.startswith("shot-revision:") and image.get("shot_id") == identity]
    require(len(matches) <= 1, "inverse stage shot root is ambiguous")
    if not matches:
        return {"state": "absent"}, []
    physical, shot = matches[0]
    internal = "internal-revision:" + shot["internal_timeline_revision_id"]
    require(internal in boundary and shot["payload"].get("internal_timeline_revision_id")
            == shot["internal_timeline_revision_id"], "inverse stage shot root has no authenticated internal image")
    return {"state": "present", "value": {"payload": copy.deepcopy(shot["payload"]),
            "internal_timeline": copy.deepcopy(boundary[internal]["payload"])}}, [physical, internal]


def _inverse_stage_root_equal(observed, claimed, ref):
    if value_equal(observed, claimed):
        return True
    if ref.startswith("shot:") and observed["state"] == "present":
        authored = copy.deepcopy(observed)
        authored["value"]["payload"].pop("internal_timeline_revision_id", None)
        return value_equal(authored, claimed)
    return False


def _inverse_stage_history(records, history):
    """Return the authenticated source stages named by an inverse record."""
    publications = records.get("undo_of")
    require(isinstance(publications, list) and publications and
            all(isinstance(publication, str) and publication for publication in publications)
            and len(set(publications)) == len(publications),
            "inverse stage history targets are malformed")
    require(isinstance(history, dict), "inverse stage history is unavailable")
    require(set(history) == set(publications), "inverse stage history includes non-source publications")
    selected = records.get("undo_steps")
    if selected is not None:
        require(isinstance(selected, dict) and set(selected) == set(publications),
                "inverse stage selection does not cover its history targets")

    expected = []
    for publication in reversed(publications):
        entry = history.get(publication)
        require(isinstance(entry, dict) and entry.get("publication_id") == publication
                and entry.get("intent") == "recorded"
                and isinstance(entry.get("receipt"), dict)
                and entry["receipt"].get("receipt_id") == publication,
                "inverse stage source publication is not authenticated")
        source_records = entry.get("records")
        require(isinstance(source_records, dict)
                and isinstance(source_records.get("commands"), list)
                and isinstance(source_records.get("steps"), list)
                and source_records["commands"],
                "inverse stage source command history is unavailable")
        assert isinstance(source_records, dict)
        commands = source_records["commands"]
        require([record.get("ordinal") for record in commands] == list(range(len(commands))),
                "inverse stage source command ordinals are unavailable")
        source_steps = source_records["steps"]
        assert isinstance(commands, list) and isinstance(source_steps, list)
        step_by_id = {source_step.get("id"): source_step for source_step in source_steps}
        require(len(step_by_id) == len(source_steps) and all(isinstance(identity, str) and identity
                                                            for identity in step_by_id),
                "inverse stage source steps are malformed")
        requested = (list(step_by_id) if selected is None else selected.get(publication))
        require(isinstance(requested, list) and requested and
                all(isinstance(identity, str) and identity in step_by_id for identity in requested)
                and len(set(requested)) == len(requested),
                "inverse stage selected source steps are unavailable")
        for source_step in reversed(source_steps):
            if source_step["id"] not in requested:
                continue
            ordinals = source_step.get("command_ordinals")
            require(isinstance(ordinals, list) and ordinals
                    and ordinals == list(range(ordinals[0], ordinals[0] + len(ordinals)))
                    and all(type(ordinal) is int and 0 <= ordinal < len(commands) for ordinal in ordinals),
                    "inverse stage source step command boundary is malformed")
            source_commands = [commands[ordinal] for ordinal in ordinals]
            native_sites = [(write["ref"], write["path"]) for command in reversed(source_commands)
                            for write in reversed([*command.get("writes", []),
                                *(write for write in command.get("derived_writes", [])
                                  if write.get("ref", "").startswith("parent/clip:")
                                  and write.get("path") in (["at"], ["hold"]))])]
            expected.append({"publication_id": publication, "step_id": source_step["id"],
                             "command_ordinals": ordinals, "native_sites": native_sites})
    return expected


def _inverse_stage_ranges(step, records, history=None):
    """Validate the recorder's stage partition without trusting its images."""
    stages = []
    stage_records = []
    for ordinal in step["command_ordinals"]:
        record = records["commands"][ordinal]
        for binding in record["bindings"]:
            if binding.get("key") == "inverse.stage":
                stages.append(binding)
                stage_records.append(record)
    if not stages:
        return None

    expected = _inverse_stage_history(records, history)
    require(len(stages) == len(expected),
            "inverse stage provenance does not match authenticated history")

    require(all(records["commands"][ordinal]["command"]["op"] == "timeline.inverse"
                for ordinal in step["command_ordinals"]),
            "inverse stage provenance is attached to a non-inverse command")
    final_ordinal = step["command_ordinals"][-1]
    require(all(record["ordinal"] == final_ordinal for record in stage_records),
            "inverse stage provenance is attached to the wrong command")
    record = records["commands"][final_ordinal]
    previous_native_end = 0
    previous_effect_end = 0
    result = []
    for binding, source_stage in zip(stages, expected):
        boundary = binding.get("boundary")
        require(isinstance(boundary, dict), "inverse stage boundary is absent or malformed")
        step_id = boundary.get("step_id")
        command_ordinals = boundary.get("command_ordinals")
        require(binding.get("ref") == "parent" and binding.get("policy") == "fixed"
                and binding.get("dependencies") == []
                and boundary.get("publication_id") == source_stage["publication_id"]
                and step_id == source_stage["step_id"]
                and command_ordinals == source_stage["command_ordinals"],
                "inverse stage provenance differs from authenticated source history")
        require(isinstance(step_id, str) and step_id
                and isinstance(command_ordinals, list) and command_ordinals
                and all(type(item) is int and item >= 0 for item in command_ordinals)
                and len(set(command_ordinals)) == len(command_ordinals)
                and command_ordinals == sorted(command_ordinals),
                "inverse stage command provenance is malformed")
        native_range = boundary.get("native_write_range")
        effect_range = boundary.get("effect_range")
        require(isinstance(native_range, list) and len(native_range) == 2
                and all(type(item) is int for item in native_range),
                "inverse stage native range is malformed")
        require(isinstance(effect_range, list) and len(effect_range) == 2
                and all(type(item) is int for item in effect_range),
                "inverse stage effect range is malformed")
        native_start, native_end = native_range
        effect_start, effect_end = effect_range
        require(native_end - native_start == len(source_stage["native_sites"])
                and native_start == previous_native_end and native_start < native_end <= len(record["writes"]),
                "inverse stage native ranges are missing, reordered, or overlapping")
        require(effect_start == previous_effect_end and effect_start < effect_end <= len(step["patch"]),
                "inverse stage effect ranges are missing, reordered, or overlapping")
        native_sites = [(write["ref"], write["path"]) for write in record["writes"][native_start:native_end]]
        effect_sites = [(effect["ref"], effect["path"]) for effect in step["patch"][effect_start:effect_end]]
        # A recorder may observe the exact canonical stage effects directly or
        # retain the source's finer native captures in reverse execution order.
        # Neither representation permits extra sites or mere ancestor overlap.
        require(native_sites == source_stage["native_sites"] or native_sites == effect_sites,
                "inverse stage native write membership differs from its authenticated stage")
        previous_native_end, previous_effect_end = native_end, effect_end
        result.append({"binding": binding, "record": record, "native_range": native_range,
                       "effect_range": effect_range})
    require(previous_native_end == len(record["writes"])
            and previous_effect_end == len(step["patch"]),
            "inverse stage ranges do not cover the authenticated inverse")
    return result


def _inverse_stage_boundaries(boundary, output, step, records, accepted, original, history=None):
    stages = _inverse_stage_ranges(step, records, history)
    if stages is None:
        return None
    current = boundary
    effect_boundaries = {}
    authenticated_turnovers = []
    effect_bindings = [binding for ordinal in step["command_ordinals"]
                       for binding in records["commands"][ordinal]["bindings"]
                       if binding.get("key") == "commit.effect"]
    for stage in stages:
        effect_start, effect_end = stage["effect_range"]
        stage_before = current
        stage_step = {**step, "patch": step["patch"][effect_start:effect_end]}
        stage_after = step_output(stage_before, stage_step, records, accepted, original=stage_before)
        native_start, native_end = stage["native_range"]
        writes = stage["record"]["writes"][native_start:native_end]
        source_boundary = stage["binding"].get("boundary", {})
        source_entry = (history or {}).get(source_boundary.get("publication_id"), {})
        source_records = source_entry.get("records", {})
        source_commands = source_records.get("commands", [])
        source_steps = source_records.get("steps", [])
        source_step = next((item for item in source_steps
                            if item.get("id") == source_boundary.get("step_id")), None)
        source_bindings = []
        if source_step is not None:
            source_bindings = [binding for ordinal in source_step.get("command_ordinals", [])
                               if isinstance(ordinal, int) and ordinal < len(source_commands)
                               for binding in source_commands[ordinal].get("bindings", [])
                               if binding.get("key") == "commit.materialization"]
        native_image = copy.deepcopy(stage_before)
        root_checks = []
        # Native captures observe each preceding write (including empty ancestor
        # removals); canonical effects describe the complete stage transition.
        for write in writes:
            if not write["path"] and re.fullmatch(r"(?:shot|occurrence):[^/]+", write["ref"]):
                root = write["ref"]
                observed, physical = _inverse_stage_root(native_image, root)
                after, successors = _inverse_stage_root(stage_after, root)
                root_checks.append((observed, write["before"], root, physical,
                                    after, write["after"], successors))
                if root.startswith("occurrence:"):
                    path = ["occurrences", "occurrence_id:" + root.partition(":")[2]]
                    state = location(stage_after["parent"]["payload"], path, absent_items=True)
                    native_image["parent"]["payload"] = project_observation(
                        native_image["parent"]["payload"], path, state)
                else:
                    for ref in physical:
                        if ref.startswith("internal-revision:") and any(
                                image.get("internal_timeline_revision_id") == ref.partition(":")[2]
                                for key, image in native_image.items()
                                if key.startswith("shot-revision:") and key not in physical):
                            continue
                        native_image.pop(ref)
                    for ref in successors:
                        native_image[ref] = copy.deepcopy(stage_after[ref])
                continue
            ref, path = _inverse_stage_write_site(native_image, write)
            require(value_equal(_inverse_stage_state(native_image, ref, path), write["before"]),
                    "inverse stage write differs from its sequential input")
            if not path and ref not in native_image:
                require(ref in stage_after and value_equal(
                    {"state": "present", "value": stage_after[ref]["payload"]}, write["after"]),
                    "inverse stage root differs from its authenticated effect image")
                native_image[ref] = copy.deepcopy(stage_after[ref])
            elif not path and write["after"]["state"] == "absent":
                native_image.pop(ref)
            else:
                payload = native_image[ref]["payload"]
                observed_path = stored_path(payload, ref, path)
                native_image[ref]["payload"] = project_observation(payload, observed_path, write["after"])
                if (write["ref"].startswith("occurrence:") and "/" not in write["ref"]
                        and write["path"] == ["shot_id"] and source_step is not None):
                    fork_commands = [source_commands[ordinal]
                                     for ordinal in source_step["command_ordinals"]
                                     if source_commands[ordinal]["command"]["op"] == "occurrence.fork"]
                    captures = [capture for command in fork_commands for capture in command["writes"]
                                if capture["ref"] == write["ref"] and capture["path"] == write["path"]]
                    if captures:
                        require(len(captures) == 1 and value_equal(captures[0]["after"], write["before"])
                                and value_equal(captures[0]["before"], write["after"]),
                                "inverse fork differs from its authenticated native capture")
                        occurrence_path = ["occurrences", "occurrence_id:" + write["ref"].partition(":")[2]]
                        # The native fork's source alias can predate the physical
                        # source pin. Restore that exact accepted source pair.
                        for field in ("shot_id", "shot_revision_id"):
                            effects = [effect for effect in source_step["patch"]
                                       if effect["ref"] == "parent" and effect["path"] == [*occurrence_path, field]]
                            require(len(effects) == 1 and effects[0]["op"] == "set"
                                    and value_equal(location(stage_before["parent"]["payload"],
                                                             [*occurrence_path, field]),
                                                    {"state": "present", "value": effects[0]["value"]}),
                                    "inverse fork differs from its authenticated source edge")
                            native_image["parent"]["payload"] = project_observation(
                                native_image["parent"]["payload"], [*occurrence_path, field], effects[0]["before"])
                if ref == "parent" and write["ref"].startswith(("parent/clip:", "parent/asset:")):
                    projected = native_image[ref]["payload"]
                    for mirror in (("clips",) if write["ref"].startswith("parent/clip:") else ("registry",)):
                        if mirror in projected and mirror in projected.get("config", {}):
                            projected[mirror] = copy.deepcopy(projected["config"][mirror])
        # A leaf native write can restore authored bytes while the accepted
        # source records an authenticated physical turnover.  In that case,
        # reverse the source materialization edges; never infer a new root or
        # copy an arbitrary stage image.
        transitions = []
        for binding in source_bindings:
            assert source_step is not None
            source_new = binding.get("physical_ref")
            source_old = binding.get("successor")
            owner = binding.get("owner")
            attribution = binding.get("boundary", {})
            require(binding.get("ref") == source_new
                    and binding.get("step_id") == source_step["id"]
                    and attribution.get("step_id") == source_step["id"]
                    and attribution.get("command_ordinal") in source_step["command_ordinals"]
                    and attribution.get("phase") == "input"
                    and attribution.get("base_revision_id") == source_entry["receipt"]["result"]["base_revision_id"]
                    and attribution.get("base_publication_id") == source_entry["receipt"]["result"]["base_publication_id"]
                    and value_equal(attribution.get("evaluated_head"), source_entry["previous"]),
                    "inverse stage source materialization attribution differs from history")
            require(binding.get("policy") == "fixed"
                    and binding.get("dependencies") == []
                    and isinstance(source_new, str) and isinstance(source_old, str)
                    and source_new.startswith(("shot-revision:", "internal-revision:"))
                    and source_old.startswith(("shot-revision:", "internal-revision:")),
                    "inverse stage source materialization is malformed")
            old, new = source_old, source_new
            require(old != new and old in stage_before and new in stage_after
                    and old not in stage_after and new not in stage_before,
                    "inverse stage source materialization is outside its physical turnover")
            require(isinstance(owner, str) and owner.startswith("occurrence:")
                    and owner.endswith("/shot") and binding.get("owners") == [owner],
                    "inverse stage source materialization owner is malformed")
            occurrence = owner.removeprefix("occurrence:").removesuffix("/shot")
            before_rows = [row for row in stage_before["parent"]["payload"].get("occurrences", [])
                           if row.get("occurrence_id") == occurrence]
            after_rows = [row for row in stage_after["parent"]["payload"].get("occurrences", [])
                          if row.get("occurrence_id") == occurrence]
            require(len(before_rows) == len(after_rows) == 1,
                    "inverse stage materialization owner is absent or ambiguous")
            before_row, after_row = before_rows[0], after_rows[0]
            require(before_row["shot_id"] == after_row["shot_id"]
                    and _physical_owner(stage_before, old) == (occurrence, before_row["shot_id"])
                    and _physical_owner(stage_after, new) == (occurrence, after_row["shot_id"]),
                    "inverse stage materialization changes physical ownership")
            before_shot = "shot-revision:" + str(before_row["shot_revision_id"])
            after_shot = "shot-revision:" + str(after_row["shot_revision_id"])
            before_internal = "internal-revision:" + str(stage_before[before_shot]["internal_timeline_revision_id"])
            after_internal = "internal-revision:" + str(stage_after[after_shot]["internal_timeline_revision_id"])
            if old == before_shot and new == after_shot:
                expected_edges = (before_internal, after_internal)
            elif old == before_internal and new == after_internal:
                expected_edges = (before_shot, after_shot)
            else:
                require(False, "inverse stage materialization differs from its owner edges")
                expected_edges = (None, None)
            require(binding.get("edge_before") == expected_edges[1]
                    and binding.get("edge_after") == expected_edges[0]
                    and binding.get("revision_id") == stage_after[new]["revision_id"]
                    and binding.get("content_digest") == stage_after[new]["content_digest"],
                    "inverse stage source materialization differs from its successor image")
            source_images = [pin for ordinal in source_step["command_ordinals"]
                             for pin in source_commands[ordinal]["bindings"]
                             if pin.get("key") == "commit.effect" and pin.get("physical_ref") == new
                             and pin.get("boundary", {}).get("side") == "before"]
            require(source_images and all(pin.get("revision_id") == binding["revision_id"]
                                          and pin.get("content_digest") == binding["content_digest"]
                                          for pin in source_images),
                    "inverse stage materialization differs from its recorded source image")
            sibling = [item for item in source_bindings
                       if item.get("physical_ref") == binding.get("edge_before")
                       and item.get("successor") == binding.get("edge_after")]
            require(len(sibling) == 1 and sibling[0].get("owner") == owner
                    and sibling[0].get("owners") == [owner]
                    and sibling[0].get("edge_before") == source_new
                    and sibling[0].get("edge_after") == source_old,
                    "inverse stage source materialization has no authenticated sibling edge")
            require((old, new) not in [(item[0], item[1]) for item in transitions],
                    "inverse stage materialization has an ambiguous successor")
            transitions.append((old, new, before_internal, after_internal,
                                before_shot, after_shot))

        shot_turnovers = {(old, new): (before_internal, after_internal)
                          for old, new, before_internal, after_internal, _, _ in transitions
                          if old.startswith("shot-revision:")}
        for old, new, before_internal, after_internal, before_shot, after_shot in transitions:
            image = native_image.pop(old)
            expected = stage_after[new]
            if old.startswith("internal-revision:"):
                require(value_equal(image["payload"], expected["payload"]),
                        "inverse stage materialization changes internal payload")
            else:
                payload = copy.deepcopy(image["payload"])
                require(payload.get("internal_timeline_revision_id") == before_internal.partition(":")[2],
                        "inverse stage materialization has a wrong shot pin")
                payload["internal_timeline_revision_id"] = after_internal.partition(":")[2]
                require(value_equal(payload, expected["payload"]),
                        "inverse stage materialization changes shot payload")
                image["payload"] = payload
                image["internal_timeline_revision_id"] = after_internal.partition(":")[2]
            require(image.get("shot_id") == expected.get("shot_id"),
                    "inverse stage materialization changes physical ownership")
            image["revision_id"] = expected["revision_id"]
            image["content_digest"] = expected["content_digest"]
            require(image["content_digest"] == digest(image["payload"]),
                    "inverse stage materialization has an unauthenticated payload digest")
            native_image[new] = image
        for row in native_image["parent"]["payload"].get("occurrences", []):
            for old, new in shot_turnovers:
                if row.get("shot_revision_id") == old.partition(":")[2]:
                    row["shot_revision_id"] = new.partition(":")[2]
        for observed, before_claim, root, physical, after, after_claim, successors in root_checks:
            before_claim = copy.deepcopy(before_claim)
            after_claim = copy.deepcopy(after_claim)
            # A later aggregate capture retains the pin from the native source
            # execution. Translate only the exact edge already proved in an
            # earlier inverse stage, preserving every other aggregate byte.
            for claim, refs in ((before_claim, physical), (after_claim, successors)):
                if root.startswith("shot:") and claim["state"] == "present":
                    payload = claim["value"]["payload"]
                    for old, new, old_internal, new_internal, _, _ in authenticated_turnovers:
                        if (new in refs and old.startswith("shot-revision:")
                                and payload.get("internal_timeline_revision_id") == old_internal.partition(":")[2]):
                            payload["internal_timeline_revision_id"] = new_internal.partition(":")[2]
            require(_inverse_stage_root_equal(observed, before_claim, root),
                    "inverse stage root differs from its sequential input")
            require(_inverse_stage_root_equal(after, after_claim, root),
                    "inverse stage root differs from its authenticated effect image")
        authenticated_turnovers.extend(transitions)

        require(value_equal({ref: image["payload"] for ref, image in native_image.items()},
                            {ref: image["payload"] for ref, image in stage_after.items()}),
                "inverse stage native writes do not cover its authenticated effect image")
        for write in writes:
            if not write["path"] and re.fullmatch(r"(?:shot|occurrence):[^/]+", write["ref"]):
                require(value_equal(_inverse_stage_root(native_image, write["ref"])[0],
                                    _inverse_stage_root(stage_after, write["ref"])[0]),
                        "inverse stage roots differ from its authenticated effect image")
                continue
            before_ref, before_path = _inverse_stage_write_site(native_image, write)
            after_ref, after_path = _inverse_stage_write_site(stage_after, write)
            require(before_ref == after_ref and before_path == after_path
                    and value_equal(_inverse_stage_state(native_image, before_ref, before_path),
                                    _inverse_stage_state(stage_after, after_ref, after_path)),
                    "inverse stage writes differ from its authenticated effect image")
        for index in range(effect_start, effect_end):
            effect = step["patch"][index]
            for side, image in (("before", stage_before), ("after", stage_after)):
                if (effect["ref"] in image or (not effect["path"]
                        and effect["ref"].startswith(("shot-revision:", "internal-revision:")))):
                    physical = effect["ref"]
                else:
                    physical, _ = site(image, effect["ref"], effect["path"])
                expected = [binding for binding in effect_bindings
                            if binding.get("effect_ordinal") == index
                            and binding.get("boundary", {}).get("side") == side
                            and binding.get("physical_ref") == physical]
                if physical in image:
                    require(len(expected) == 1,
                            "provider inverse effect bindings do not cover its stage image")
            effect_boundaries[index] = (stage_before, stage_after)
        current = stage_after
    require(value_equal(current, output), "inverse stage images do not reach the authenticated output")
    return effect_boundaries


def _authoring_parent_identity(boundary, identity_scope, manifest):
    """Derive the parent pin from sequential images and retained input pins."""
    project_id, timeline_id = identity_scope
    manifest = copy.deepcopy(manifest or {"media": [], "documents": []})
    for family, prefix, keys, order in (
            ("shots", "shot-revision:", ("shot_id", "revision_id", "internal_timeline_revision_id", "content_digest"),
             ("shot_id", "revision_id")),
            ("internal_timelines", "internal-revision:", ("timeline_id", "revision_id", "content_digest"),
             ("timeline_id", "revision_id"))):
        manifest[family] = sorted(({key: image[key] for key in keys} for ref, image in boundary.items()
                                   if ref.startswith(prefix)), key=lambda row: tuple(row[key] for key in order))
    return "authoring-parent-revision-" + digest({
        "project_id": project_id, "timeline_id": timeline_id,
        "parent": boundary["parent"]["payload"], "manifest": manifest,
    }).removeprefix("sha256:")


def _project_created_child(boundary, record, following, accepted, identity_scope=None):
    """Carry an authenticated occurrence birth into the next command input.

    Native occurrence creation records authored aggregate roots, while the
    Runtime closure stores their physical shot/internal images.  A later
    command in the same step must see the birth, but must not inherit the
    later command's final payload. Build the intermediate view and scoped
    allocation identities from creation writes; check the accepted owner
    edges without borrowing their later payloads.
    """
    created = {item.get("ref"): item for item in record.get("created", [])}
    projected_roots = set()
    future_refs = [read.get("ref") for read in following.get("reads", [])]
    future_refs.extend(binding.get("ref") for binding in following.get("bindings", []))
    future_refs.extend(write.get("ref") for write in following.get("writes", []))

    for occurrence_ref, allocation in created.items():
        if not (isinstance(occurrence_ref, str) and occurrence_ref.startswith("occurrence:")
                and "/" not in occurrence_ref
                and any(ref == occurrence_ref or isinstance(ref, str) and ref.startswith(occurrence_ref + "/")
                        for ref in future_refs)):
            continue
        occurrence_write = next((write for write in record.get("writes", [])
                                 if write.get("ref") == occurrence_ref and not write.get("path")), None)
        occurrence_value = ((occurrence_write or {}).get("after", {}).get("value"))
        shot_id = occurrence_value.get("shot_id") if isinstance(occurrence_value, dict) else None
        if (allocation.get("kind") != "occurrence" or allocation.get("owner") != "parent"
                or not isinstance(shot_id, str)):
            require(False, "provider created occurrence root is not an authenticated parent birth")
            continue
        require(occurrence_write is not None
                and occurrence_write.get("before") == {"state": "absent"}
                and occurrence_write.get("after", {}).get("state") == "present",
                "provider created occurrence lacks its absent-to-present root write")

        accepted_shot_refs = [ref for ref, image in accepted.items()
                              if ref.startswith("shot-revision:") and image.get("shot_id") == shot_id]
        require(len(accepted_shot_refs) == 1,
                "provider created occurrence has an ambiguous accepted physical shot")
        if len(accepted_shot_refs) != 1:
            require(False, "provider created occurrence has no accepted physical shot")
            continue
        accepted_shot_ref = accepted_shot_refs[0]
        accepted_shot = accepted[accepted_shot_ref]
        accepted_internal_id = accepted_shot.get("internal_timeline_revision_id")
        if not isinstance(accepted_internal_id, str):
            require(False, "provider created occurrence has no accepted physical internal timeline")
            continue
        accepted_internal_ref = "internal-revision:" + str(accepted_internal_id)
        if accepted_internal_ref not in accepted:
            require(False, "provider created occurrence has no accepted physical internal timeline")
            continue
        accepted_internal = accepted[accepted_internal_ref]

        shot_write = next((write for write in record.get("writes", [])
                           if write.get("ref") == "shot:" + shot_id and not write.get("path")), None)
        if not isinstance(shot_write, dict):
            require(False, "provider created occurrence lacks its authored shot birth")
            continue
        require(shot_write.get("before") == {"state": "absent"}
                and shot_write.get("after", {}).get("state") == "present",
                "provider created occurrence lacks its authored shot birth")
        shot_value = shot_write["after"]["value"]
        require(isinstance(shot_value, dict)
                and isinstance(shot_value.get("payload"), dict)
                and isinstance(shot_value.get("internal_timeline"), dict),
                "provider created shot birth is malformed")
        if (not isinstance(shot_value, dict)
                or not isinstance(shot_value.get("payload"), dict)
                or not isinstance(shot_value.get("internal_timeline"), dict)):
            continue
        initial_shot = copy.deepcopy(shot_value["payload"])
        authored_shot = copy.deepcopy(initial_shot)
        initial_internal = copy.deepcopy(shot_value["internal_timeline"])
        if identity_scope is None:
            shot_ref = accepted_shot_ref
            internal_ref = accepted_internal_ref
            internal_id = accepted_internal_id
            shot_revision_id = shot_ref.partition(":")[2]
        else:
            project_id, timeline_id = identity_scope
            require(accepted_internal.get("timeline_id") == timeline_id,
                    "provider created occurrence internal timeline has a foreign owner")
            internal_id = _authoring_identity("authoring-timeline-revision", project_id, timeline_id,
                                              shot_id, initial_internal)
            initial_shot["internal_timeline_revision_id"] = internal_id
            shot_revision_id = _authoring_identity("authoring-shot-revision", project_id, shot_id,
                                                   initial_shot)
            shot_ref = "shot-revision:" + shot_revision_id
            internal_ref = "internal-revision:" + internal_id
        internal_image = copy.deepcopy(accepted_internal)

        # Every physical alias claimed by the next command must still belong
        # to this exact created occurrence. A source pin cannot retarget the
        # child to a foreign or future physical image.
        for binding in following.get("bindings", []):
            ref = binding.get("ref")
            if not (isinstance(ref, str) and (ref == occurrence_ref or ref.startswith(occurrence_ref + "/"))):
                continue
            physical = binding.get("physical_ref")
            if physical is None:
                continue
            require(physical in {"parent", shot_ref, internal_ref},
                    "provider created occurrence source pin is foreign")
            if ref == occurrence_ref + "/source":
                require(physical == internal_ref,
                        "provider created occurrence source pin differs from its child")

        accepted_occurrences = accepted["parent"]["payload"].get("occurrences", [])
        accepted_occurrence = [row for row in accepted_occurrences
                               if row.get("occurrence_id") == occurrence_ref.partition(":")[2]]
        require(len(accepted_occurrence) == 1
                and accepted_occurrence[0].get("shot_id") == shot_id
                and accepted_occurrence[0].get("shot_revision_id") == accepted_shot_ref.partition(":")[2],
                "provider created occurrence has an ambiguous accepted owner")
        # Keep authored creation fields from the earlier native write; only the
        # managed shot revision edge comes from the accepted physical closure.
        intermediate_occurrence = copy.deepcopy(occurrence_value)
        intermediate_occurrence["shot_revision_id"] = shot_revision_id
        if identity_scope is not None:
            accepted_payload = accepted_shot.get("payload")
            require(isinstance(accepted_payload, dict)
                    and {key: value for key, value in accepted_payload.items()
                         if key != "internal_timeline_revision_id"} == authored_shot,
                    "provider created occurrence accepted shot is not its authored allocation")
            projected_parent = copy.deepcopy(boundary["parent"]["payload"])
            projected_parent.setdefault("occurrences", []).append(intermediate_occurrence)
            parent_pins = [binding for binding in following.get("bindings", [])
                           if binding.get("physical_ref") == "parent"
                           and binding.get("boundary", {}).get("phase") == "input"
                           and binding.get("content_digest") == digest(projected_parent)]
            require(parent_pins,
                    "provider created occurrence lacks an authenticated authoring allocation mapping")
        require(all(accepted_occurrence[0].get(key) == value
                    for key, value in occurrence_value.items()),
                "provider created occurrence differs from its accepted owner")

        result_parent = boundary["parent"]
        payload = copy.deepcopy(result_parent["payload"])
        occurrences = payload.setdefault("occurrences", [])
        require(not any(row.get("occurrence_id") == intermediate_occurrence["occurrence_id"]
                        for row in occurrences),
                "provider created occurrence is already present at its input boundary")
        occurrences.append(intermediate_occurrence)
        result_parent["payload"] = payload
        result_parent["content_digest"] = digest(payload)

        require(shot_ref not in boundary and internal_ref not in boundary,
                "provider created occurrence physical roots overlap its input boundary")
        result_shot = copy.deepcopy(accepted_shot)
        result_shot["revision_id"] = shot_revision_id
        result_shot["internal_timeline_revision_id"] = internal_id
        result_shot["payload"] = initial_shot
        result_shot["content_digest"] = digest(initial_shot)
        result_internal = copy.deepcopy(internal_image)
        result_internal["revision_id"] = internal_id
        result_internal["payload"] = initial_internal
        result_internal["content_digest"] = digest(initial_internal)
        for binding in following.get("bindings", []):
            if binding.get("ref") == occurrence_ref + "/source":
                require(binding.get("content_digest") == result_internal["content_digest"],
                        "provider created occurrence source digest differs from its birth")
        boundary[shot_ref] = result_shot
        boundary[internal_ref] = result_internal
        projected_roots.update({"shot:" + shot_id, occurrence_ref})
    return projected_roots


def _following_read_observes(boundary, following, physical_ref):
    for read in following.get("reads", []):
        ref, path = native_site(boundary, read["ref"], read["path"])
        if ref != physical_ref:
            continue
        if not path and "/collection:" in read["ref"]:
            return True
        if not path:
            continue
        observed = location(boundary[ref]["payload"], stored_path(boundary[ref]["payload"], ref, path))
        if value_equal(observed, read.get("state")):
            return True
    return False


def command_output(boundary, record, following, *, accepted=None, identity_scope=None, manifest=None):
    """Project full recorder observations needed by a subsequent input binding."""
    result = copy.deepcopy(boundary)
    projected_roots = (_project_created_child(result, record, following, accepted, identity_scope)
                       if accepted is not None else set())
    created_roots = {item.get("ref") for item in record.get("created", [])
                     if re.fullmatch(r"(?:shot|occurrence):[^/]+", item.get("ref", ""))}
    for capture in [*record["writes"], *record["derived_writes"]]:
        if capture.get("ref") in created_roots & projected_roots and not capture.get("path"):
            # The authored aggregate root was installed above through its
            # physical closure images; it has no direct Runtime image site.
            continue
        ref, path = native_site(result, capture["ref"], capture["path"])
        require(ref in result, "provider intermediate command lacks an authenticated physical observation")
        payload = result[ref]["payload"]
        path = stored_path(payload, ref, path)
        before_payload = boundary.get(ref, result[ref])["payload"] if "cause" in capture else payload
        require(value_equal(location(before_payload, path, absent_items=True), capture["before"]),
                "provider intermediate command has a different input observation")
        result[ref]["payload"] = project_observation(payload, path, capture["after"])
        if ref == "parent":
            for mirror in ("clips", "registry"):
                projected = result[ref]["payload"]
                if mirror in projected and mirror in projected.get("config", {}):
                    projected[mirror] = copy.deepcopy(projected["config"][mirror])
        result[ref]["content_digest"] = digest(result[ref]["payload"])
    for ref, image in list(result.items()):
        if ref not in boundary:
            continue
        if image["content_digest"] == boundary[ref]["content_digest"]:
            continue
        pins = [binding for binding in following["bindings"] if binding.get("physical_ref") == ref
                and binding.get("boundary", {}).get("phase") == "input"
                and binding.get("content_digest") == image["content_digest"]]
        if pins:
            require(len({pin["revision_id"] for pin in pins}) == 1,
                    "provider intermediate image differs from recorded command observations")
            require(ref == "parent",
                    "provider intermediate changed payload retains its immutable physical identity")
            image["revision_id"] = pins[0]["revision_id"]
        else:
            aliases = [binding for binding in following["bindings"]
                       if isinstance(binding.get("physical_ref"), str)
                       and binding["physical_ref"].startswith(("shot-revision:", "internal-revision:"))
                       and binding.get("physical_ref") != ref
                       and binding.get("boundary", {}).get("phase") == "input"
                       and binding.get("content_digest") == image["content_digest"]]
            if aliases:
                require(len({binding["physical_ref"] for binding in aliases}) == 1,
                        "provider intermediate image has ambiguous authenticated promotion")
                alias = aliases[0]
                target = alias["physical_ref"]
                require(target.split(":", 1)[0] == ref.split(":", 1)[0]
                        and alias["revision_id"] == target.partition(":")[2],
                        "provider intermediate promotion changes its physical kind or identity")
                require(target not in result,
                        "provider intermediate image promotion overlaps an authenticated root")
                if identity_scope is None:
                    require(False, "provider intermediate promotion lacks an authenticated allocation")
                    continue
                project_id, timeline_id = identity_scope
                target_id = target.partition(":")[2]
                source_id = ref.partition(":")[2]
                if ref.startswith("internal-revision:"):
                    owners = [(owner_ref, owner) for owner_ref, owner in result.items()
                              if owner_ref.startswith("shot-revision:")
                              and owner.get("internal_timeline_revision_id") == source_id]
                    require(len(owners) == 1,
                            "provider intermediate image has an ambiguous physical owner")
                    old_shot_ref, owner = owners[0]
                    shot_id = owner["shot_id"]
                    require(target_id == _authoring_identity(
                        "authoring-timeline-revision", project_id, timeline_id, owner["shot_id"], image["payload"]),
                        "provider intermediate promotion differs from its sequential allocation")
                    payload = owner["payload"]
                    require(payload.get("internal_timeline_revision_id") == source_id,
                            "provider intermediate image owner has a different physical edge")
                    owner["internal_timeline_revision_id"] = target_id
                    payload["internal_timeline_revision_id"] = target_id
                    owner["content_digest"] = digest(payload)
                    successor_shot_id = _authoring_identity(
                        "authoring-shot-revision", project_id, owner["shot_id"], payload)
                    successor_shot_ref = "shot-revision:" + successor_shot_id
                    require(successor_shot_ref not in result,
                            "provider intermediate shot promotion overlaps an authenticated root")
                    owner["revision_id"] = successor_shot_id
                    result[successor_shot_ref] = result.pop(old_shot_ref)
                else:
                    shot_id = image["shot_id"]
                    require(target_id == _authoring_identity(
                        "authoring-shot-revision", project_id, image["shot_id"], image["payload"]),
                        "provider intermediate shot promotion differs from its sequential allocation")
                    old_shot_ref, successor_shot_id = ref, target_id
                parent = result["parent"]["payload"]
                owners = [row for row in parent.get("occurrences", [])
                          if row.get("shot_revision_id") == old_shot_ref.partition(":")[2]]
                require(owners and all(row.get("shot_id") == shot_id for row in owners),
                        "provider intermediate promotion lacks its authenticated parent owner")
                for row in owners:
                    row["shot_revision_id"] = successor_shot_id
                result["parent"]["content_digest"] = digest(parent)
                image["revision_id"] = target_id
                result[target] = result.pop(ref)
                expected_parent = _authoring_parent_identity(result, identity_scope, manifest)
                parent_pins = [binding for binding in following["bindings"]
                               if binding.get("physical_ref") == "parent"
                               and binding.get("boundary", {}).get("phase") == "input"]
                require(parent_pins and all(pin.get("revision_id") == expected_parent
                                           and pin.get("content_digest") == result["parent"]["content_digest"]
                                           for pin in parent_pins),
                        "provider intermediate parent promotion differs from its sequential allocation")
                result["parent"]["revision_id"] = expected_parent
            else:
                require(not ref.startswith(("shot-revision:", "internal-revision:")),
                        "provider intermediate image lacks an authenticated physical promotion")
                require(_following_read_observes(result, following, ref),
                        "provider intermediate image lacks a next-command authenticated read")
    if projected_roots and identity_scope is not None:
        expected_parent = _authoring_parent_identity(result, identity_scope, manifest)
        parent_pins = [binding for binding in following["bindings"]
                       if binding.get("physical_ref") == "parent"
                       and binding.get("boundary", {}).get("phase") == "input"]
        require(parent_pins and all(pin.get("revision_id") == expected_parent
                                   and pin.get("content_digest") == result["parent"]["content_digest"]
                                   for pin in parent_pins),
                "provider created parent differs from its sequential allocation")
        result["parent"]["revision_id"] = expected_parent
    return result


def _capture_document_images(document):
    validate_commit_value(document, "CanonicalDocument")
    require(isinstance(document, dict)
            and isinstance(document.get("parent_revision"), dict)
            and isinstance(document.get("shot_revisions"), list)
            and isinstance(document.get("internal_timeline_revisions"), list),
            "sequential command boundary document is malformed")
    rows = [document["parent_revision"], *document["shot_revisions"],
            *document["internal_timeline_revisions"]]
    require(all(isinstance(row, dict) and isinstance(row.get("revision_id"), str)
                and isinstance(row.get("payload"), dict)
                and isinstance(row.get("content_digest"), str) for row in rows),
            "sequential command boundary image is malformed")
    try:
        result = images(document)
    except (KeyError, TypeError, ValueError, IndexError) as exc:
        require(False, "sequential command boundary document is malformed")
        raise AssertionError("unreachable") from exc
    require(len(result) == len(rows), "sequential command boundary has duplicate physical images")
    for image in result.values():
        require(isinstance(image, dict) and isinstance(image.get("payload"), dict),
                "sequential command boundary image is malformed")
        require(image.get("content_digest") == digest(image["payload"]),
                "sequential command boundary image digest differs from its payload")
    return result


def _capture_projection_equal(left, right):
    """Compare the immutable image projection used by Runtime authentication.

    ``timeline_id`` is a closure transport annotation on internal images; the
    authenticated payload, revision and content digest are the authoritative
    projection used by the existing step projector.
    """
    left = copy.deepcopy(left)
    right = copy.deepcopy(right)
    for imageset in (left, right):
        for ref, image in imageset.items():
            if ref.startswith("internal-revision:"):
                image.pop("timeline_id", None)
    return value_equal(left, right)


def _capture_binding_identity(binding):
    boundary = binding.get("boundary", {})
    identity = {key: copy.deepcopy(value) for key, value in binding.items()
                if key not in {"physical_ref", "revision_id", "content_digest", "successor",
                               "edge_before", "edge_after", "boundary", "ref"}}
    for key in ("change", "dependency"):
        if isinstance(identity.get(key), dict):
            identity[key].pop("ref", None)
    physical_ref = binding.get("physical_ref")
    if isinstance(physical_ref, str):
        identity["physical_kind"] = physical_ref.partition(":")[0]
    return canonical_json(identity | {
                                              "boundary": {key: boundary.get(key) for key in (
                                                  "base_revision_id", "base_publication_id", "step_id",
                                                  "command_ordinal", "change_ordinal", "phase", "side")
                                                  if key in boundary},
                                          })


def _capture_source_chain(source):
    """Parse a replay lineage without granting it authority.

    Authority is established by ``validate_sequential_capture`` against the
    actual materialization binding for every node.  This helper only enforces
    the closed JSON shape and returns the complete chain for that check.
    """
    nodes = []
    seen = set()
    while isinstance(source, dict):
        require(set(source) == {"step_id", "source", "owner", "owners"},
                "sequential replay source is malformed")
        require(isinstance(source["step_id"], str) and bool(source["step_id"])
                and isinstance(source["owner"], str) and bool(source["owner"])
                and isinstance(source["owners"], list)
                and all(isinstance(owner, str) and bool(owner) for owner in source["owners"])
                and source["owner"] in source["owners"]
                and len(set(source["owners"])) == len(source["owners"]),
                "sequential replay source owner attribution is malformed")
        token = canonical_json(source)
        require(token not in seen, "sequential replay source is cyclic")
        seen.add(token)
        nodes.append(source)
        source = source["source"]
    require(isinstance(source, str) and bool(source)
            and source.startswith(("shot-revision:", "internal-revision:")),
            "sequential replay source terminal is malformed")
    require(source not in seen, "sequential replay source is cyclic")
    return {"nodes": nodes, "terminal": source}


def sequential_proof_required(prepared, source, continuations=None):
    """Identify the moved-head staged-alias case that cannot use the old ABI."""
    boundary = images(source)
    continuations = continuations or {}
    for record in prepared.get("records", {}).get("commands", []):
        if record.get("ordinal") != 0:
            continue
        for binding in record.get("bindings", []):
            if (binding.get("boundary", {}).get("phase") != "input"
                    or not isinstance(binding.get("physical_ref"), str)
                    or not binding["physical_ref"].startswith(("shot-revision:", "internal-revision:"))):
                continue
            ref = binding.get("ref")
            physical = binding["physical_ref"]
            if physical in boundary or not isinstance(ref, str):
                continue
            seen = set()
            while ref not in boundary and ref in continuations and ref not in seen:
                seen.add(ref)
                successors = continuations[ref]
                if len(successors) != 1:
                    break
                ref = next(iter(successors))
            if ref not in boundary and binding.get("ref", "").startswith(("shot-revision:", "internal-revision:")):
                return True
    return False


def _capture_head(head):
    require(isinstance(head, dict) and set(head) == {"revision_id", "publication_id"}
            and isinstance(head["revision_id"], str) and isinstance(head["publication_id"], str),
            "sequential execution head is malformed")


def _capture_records(records, expected, request):
    """Bind provider records to the prepared candidate without flattening bindings."""
    validate_commit_value(records, "Recorder")
    require(isinstance(records, dict) and isinstance(expected, dict)
            and set(records) == set(expected), "sequential execution records are malformed")
    require(isinstance(records.get("commands"), list) and isinstance(records.get("steps"), list),
            "sequential execution records are incomplete")
    require(len(records["commands"]) == len(request["commands"])
            and len(records["commands"]) == len(expected.get("commands", [])),
            "sequential execution command records are incomplete")
    for ordinal, (record, prepared_record, command) in enumerate(
            zip(records["commands"], expected["commands"], request["commands"])):
        require(isinstance(record, dict) and isinstance(prepared_record, dict)
                and set(record) == set(prepared_record)
                and type(record.get("ordinal")) is int and record["ordinal"] == ordinal
                and value_equal(record.get("command"), prepared_record.get("command"))
                and isinstance(record.get("bindings"), list),
                "sequential command record is malformed")
        for binding in record["bindings"]:
            boundary = binding.get("boundary", {})
            require(isinstance(boundary, dict), "sequential binding boundary is malformed")
            for attribution in (binding, boundary):
                if "command_ordinal" in attribution:
                    require(type(attribution["command_ordinal"]) is int
                            and attribution["command_ordinal"] == ordinal,
                            "sequential binding command ordinal is invalid")
                if "change_ordinal" in attribution:
                    changes = command.get("args", {}).get("changes", [])
                    require(type(attribution["change_ordinal"]) is int
                            and 0 <= attribution["change_ordinal"] < len(changes),
                            "sequential binding change ordinal is invalid")
                if "effect_ordinal" in attribution:
                    step = next((step for step in records["steps"] if ordinal in step["command_ordinals"]), None)
                    require(step is not None and type(attribution["effect_ordinal"]) is int
                            and 0 <= attribution["effect_ordinal"] < len(step["patch"]),
                            "sequential binding effect ordinal is invalid")
            if "write_range" in binding:
                start, end = binding["write_range"]
                require(type(start) is int and type(end) is int
                        and 0 <= start <= end <= len(record["writes"]),
                        "sequential binding write range is invalid")
        for write in record["derived_writes"]:
            require(type(write["cause"]) is int and 0 <= write["cause"] < len(records["commands"]),
                    "sequential derived write cause is invalid")
        for key in set(record) - {"bindings"}:
            require(value_equal(record[key], prepared_record[key]),
                    "sequential command metadata differs from the prepared candidate")
    expected_steps = cast(list, expected.get("steps"))
    require(isinstance(expected_steps, list) and len(records["steps"]) == len(expected_steps),
            "sequential execution step records are incomplete")
    seen_ordinals = []
    for step, prepared_step in zip(records["steps"], expected_steps):
        require(isinstance(step, dict) and isinstance(prepared_step, dict)
                and isinstance(step.get("command_ordinals"), list)
                and all(type(ordinal) is int for ordinal in step["command_ordinals"]),
                "sequential execution step record is malformed")
        for key in ("id", "label", "intent", "tags", "command_ordinals", "reads"):
            if key in prepared_step or key in step:
                require(key in prepared_step and key in step and value_equal(step[key], prepared_step[key]),
                        "sequential execution step metadata differs from the prepared candidate")
        seen_ordinals.extend(step["command_ordinals"])
    require(seen_ordinals == list(range(len(records["commands"]))),
            "sequential execution step records do not partition commands")
    for key in set(records) - {"commands", "steps"}:
        require(value_equal(records[key], expected[key]),
                "sequential execution metadata differs from the prepared candidate")


def _capture_binding_image(document, binding):
    physical = binding.get("physical_ref")
    require(isinstance(physical, str), "sequential physical binding is malformed")
    boundary = _capture_document_images(document)
    image = boundary.get(physical)
    require(image is not None and binding.get("revision_id") == image.get("revision_id")
            and binding.get("content_digest") == image.get("content_digest"),
            "sequential physical binding differs from its captured image")
    return boundary, image


def _capture_owners(document, physical):
    boundary = _capture_document_images(document)
    owners = []
    parent = boundary["parent"]["payload"]
    for row in parent.get("occurrences", []):
        shot_ref = "shot-revision:" + row["shot_revision_id"]
        shot = boundary.get(shot_ref)
        if physical == shot_ref or (shot is not None
                                    and physical == "internal-revision:" + shot["internal_timeline_revision_id"]):
            owners.append("occurrence:" + row["occurrence_id"] + "/shot")
    require(owners, "sequential physical binding has no authenticated owner")
    return owners


def _capture_step(records, step_id):
    matches = [step for step in records["steps"] if step.get("id") == step_id]
    require(len(matches) == 1, "sequential replay source names an unknown step")
    return matches[0]


def validate_sequential_capture(request, prepared, capture, source, base, continuations=None, history=None):
    """Authenticate the private original/landing execution carrier.

    The returned binding pairs are trusted only for this invocation of
    ``validate``.  They never become accepted-history continuations.
    """
    require(isinstance(capture, dict) and set(capture) == {
        "schema_version", "context", "original", "landing", "replay_bindings", "prepared_digest"
    } and type(capture["schema_version"]) is int and capture["schema_version"] == 1,
            "sequential execution capture is malformed")
    require(capture["prepared_digest"] == digest(prepared),
            "sequential execution capture does not bind the prepared commit")
    expected_base = {"revision_id": request["base_revision_id"],
                     "publication_id": request["base_publication_id"]}
    expected_landing = prepared["expected_head"]
    _capture_head(expected_base)
    _capture_head(expected_landing)
    executions = {}
    for side, expected_head, initial in (("original", expected_base, base),
                                         ("landing", expected_landing, source)):
        execution = capture[side]
        require(isinstance(execution, dict) and set(execution) == {"evaluated_head", "commands", "records"},
                "sequential execution has an invalid envelope")
        require(value_equal(execution["evaluated_head"], expected_head)
                and isinstance(execution["commands"], list)
                and isinstance(execution["records"], dict),
                "sequential execution head or records differ from the authenticated invocation")
        records = execution["records"]
        _capture_records(records, prepared["records"], request)
        commands = execution["commands"]
        require(len(commands) == len(records["commands"]),
                "sequential execution command boundaries are incomplete")
        previous = None
        last_output = None
        by_ordinal = {}
        for ordinal, item in enumerate(commands):
            require(isinstance(item, dict) and set(item) == {"boundary", "input", "output"},
                    "sequential command boundary is malformed")
            boundary = item["boundary"]
            require(isinstance(boundary, dict) and set(boundary) == {
                "base_revision_id", "base_publication_id", "evaluated_head", "step_id",
                "command_ordinal", "phase"
            } and boundary["base_revision_id"] == request["base_revision_id"]
                    and boundary["base_publication_id"] == request["base_publication_id"]
                    and value_equal(boundary["evaluated_head"], expected_head)
                    and type(boundary["command_ordinal"]) is int
                    and boundary["command_ordinal"] == ordinal and boundary["phase"] == "input",
                    "sequential command boundary attribution is invalid")
            step = next((step for step in records["steps"] if ordinal in step["command_ordinals"]), None)
            require(step is not None and boundary["step_id"] == step["id"],
                    "sequential command boundary step is invalid")
            current = _capture_document_images(item["input"])
            output = _capture_document_images(item["output"])
            if ordinal == 0:
                require(_capture_projection_equal(current, images(initial)),
                        "sequential original or landing input does not match its authenticated head")
            else:
                require(_capture_projection_equal(current, previous),
                        "sequential command input does not match the preceding command output")
            previous = output
            last_output = item["output"]
            by_ordinal[ordinal] = item
        require(previous is not None, "sequential execution has no command output")
        if side == "landing":
            require(last_output is not None and value_equal(last_output, prepared["canonical_document"]),
                    "landing execution output differs from the prepared document")
        executions[side] = {"by_ordinal": by_ordinal, "records": records}

    original_records = executions["original"]["records"]
    landing_records = executions["landing"]["records"]
    validate_claims(request, original_records)
    validate_claims(request, landing_records)
    original_document = capture["original"]["commands"][-1]["output"]
    original_prepared = {**prepared, "expected_head": expected_base,
                         "canonical_document": original_document,
                         "document_digest": digest(original_document),
                         "records": original_records}
    validate(request, original_prepared, base, base, {}, history,
             sequential={"landing": executions["original"]["by_ordinal"]})

    binding_pairs = {}
    source_to_landing = {}
    landing_to_source = {}
    for ordinal, (original_record, landing_record) in enumerate(zip(
            original_records["commands"], landing_records["commands"])):
        originals = {}
        for binding in original_record.get("bindings", []):
            if "physical_ref" in binding:
                key = _capture_binding_identity(binding)
                require(key not in originals, "sequential source binding is ambiguous")
                originals[key] = binding
        landings = {}
        for binding in landing_record.get("bindings", []):
            if "physical_ref" in binding:
                key = _capture_binding_identity(binding)
                require(key not in landings, "sequential landing binding is ambiguous")
                landings[key] = binding
        require(set(originals) == set(landings),
                "sequential source and landing physical bindings are incomplete")
        used = set()
        for index, binding in enumerate(landing_record.get("bindings", [])):
            if "physical_ref" not in binding:
                continue
            key = _capture_binding_identity(binding)
            original_binding = originals.get(key)
            require(original_binding is not None and key not in used,
                    "sequential landing binding has no unique original correspondence")
            if original_binding is None:
                raise AssertionError("unreachable")
            used.add(key)
            source_physical = original_binding["physical_ref"]
            landing_physical = binding["physical_ref"]
            source_key = canonical_json({"physical_ref": source_physical, "owner": binding.get("owner"),
                                         "owners": binding.get("owners"), "step_id": binding.get("step_id"),
                                         "command_ordinal": ordinal, "change_ordinal": binding.get("change_ordinal"),
                                         "effect_ordinal": binding.get("effect_ordinal"),
                                         "edge_before": original_binding.get("edge_before"),
                                         "edge_after": original_binding.get("edge_after"),
                                         "revision_id": original_binding.get("revision_id"),
                                         "content_digest": original_binding.get("content_digest")})
            landing_key = canonical_json({"physical_ref": landing_physical, "owner": binding.get("owner"),
                                          "owners": binding.get("owners"), "step_id": binding.get("step_id"),
                                          "command_ordinal": ordinal, "change_ordinal": binding.get("change_ordinal"),
                                          "effect_ordinal": binding.get("effect_ordinal"),
                                          "edge_before": binding.get("edge_before"),
                                          "edge_after": binding.get("edge_after"),
                                          "revision_id": binding.get("revision_id"),
                                          "content_digest": binding.get("content_digest")})
            require(source_to_landing.get(source_key, landing_key) == landing_key
                    and landing_to_source.get(landing_key, source_key) == source_key,
                    "sequential source-to-landing correspondence is ambiguous")
            source_to_landing[source_key] = landing_key
            landing_to_source[landing_key] = source_key
            binding_pairs[(ordinal, index)] = {"original": original_binding, "landing": binding,
                                               "source_physical_ref": source_physical}
        require(used == set(originals),
                "sequential source physical bindings were not consumed exactly once")

    replay = capture["replay_bindings"]
    require(isinstance(replay, list), "sequential replay bindings are malformed")
    expected_map = set()
    replay_required = expected_landing != expected_base
    for ordinal, record in enumerate(original_records["commands"]):
        command = request["commands"][ordinal]
        if replay_required and command.get("op") == "doc.patch":
            changes = command.get("args", {}).get("changes")
            require(isinstance(changes, list), "sequential patch changes are malformed")
            expected_map.update((ordinal, "patch", index) for index in range(len(changes)))
        original_reads = [binding for binding in record["bindings"] if binding.get("key") == "commit.read"]
        landing_reads = [binding for binding in landing_records["commands"][ordinal]["bindings"]
                         if binding.get("key") == "commit.read"]
        for binding in original_reads:
            matches = [candidate for candidate in landing_reads
                       if _capture_binding_identity(candidate) == _capture_binding_identity(binding)]
            require(len(matches) == 1, "sequential read binding correspondence is incomplete")
            phase = binding.get("boundary", {}).get("phase")
            if replay_required and binding.get("physical_ref") != matches[0].get("physical_ref"):
                expected_map.add((ordinal, "read", binding.get("ref"),
                                  tuple(binding.get("path", [])), phase))
    seen_map = set()
    for entry in replay:
        require(isinstance(entry, dict), "sequential replay binding is malformed")
        kind = entry.get("kind")
        binding_candidates = []
        command_ordinal = None
        map_key = None
        if kind == "patch":
            require(set(entry) == {"command_ordinal", "kind", "change_ordinal", "source"}
                    and type(entry.get("command_ordinal")) is int
                    and type(entry.get("change_ordinal")) is int
                    and isinstance(entry.get("source"), (dict, str)),
                    "sequential patch replay binding is malformed")
            command_ordinal = entry["command_ordinal"]
            change_ordinal = entry["change_ordinal"]
            require(0 <= command_ordinal < len(request["commands"]),
                    "sequential patch replay binding ordinal is invalid")
            command = request["commands"][command_ordinal]
            changes = command.get("args", {}).get("changes") if command.get("op") == "doc.patch" else None
            require(isinstance(changes, list) and 0 <= change_ordinal < len(changes),
                    "sequential patch replay binding ordinal is invalid")
            map_key = (command_ordinal, "patch", change_ordinal)
            binding_candidates = [binding for binding in original_records["commands"][command_ordinal]["bindings"]
                                  if binding.get("key") == "doc.patch:" + str(change_ordinal)]
        elif kind == "read":
            require(set(entry) == {"command_ordinal", "kind", "ref", "path", "phase", "source"}
                    and type(entry.get("command_ordinal")) is int
                    and isinstance(entry.get("ref"), str)
                    and isinstance(entry.get("path"), list)
                    and all(isinstance(token, str) for token in entry["path"])
                    and entry.get("phase") in {"input", "batch-read"},
                    "sequential read replay binding is malformed")
            command_ordinal = entry["command_ordinal"]
            require(0 <= command_ordinal < len(original_records["commands"]),
                    "sequential read replay binding ordinal is invalid")
            record = original_records["commands"][command_ordinal]
            require(any(isinstance(read, dict) and read.get("ref") == entry["ref"]
                        and read.get("path") == entry["path"]
                        for read in record["bindings"] if read.get("key") == "commit.read"),
                    "sequential read replay binding differs from the recorded read")
            require(entry["phase"] != "batch-read" or command_ordinal == 0,
                    "sequential batch read replay binding is out of order")
            map_key = (command_ordinal, "read", entry["ref"], tuple(entry["path"]), entry["phase"])
            binding_candidates = [binding for binding in record["bindings"]
                                  if binding.get("key") == "commit.read"
                                  and binding.get("ref") == entry["ref"]
                                  and binding.get("path") == entry["path"]
                                  and binding.get("boundary", {}).get("phase") == entry["phase"]]
        else:
            require(False, "sequential replay binding kind is invalid")
            raise AssertionError("unreachable replay binding kind")
        if command_ordinal is None or map_key is None:
            raise AssertionError("unreachable replay binding coordinates")
        require(map_key in expected_map and map_key not in seen_map,
                "sequential replay binding is duplicated or omitted from the authenticated map")
        seen_map.add(map_key)
        require(len(binding_candidates) == 1,
                "sequential replay binding has no unique original record")
        binding = binding_candidates[0]
        landing_candidates = [candidate for candidate in landing_records["commands"][command_ordinal]["bindings"]
                              if _capture_binding_identity(candidate) == _capture_binding_identity(binding)]
        require(len(landing_candidates) == 1,
                "sequential replay binding has no unique landing record")
        landing_binding = landing_candidates[0]
        chain = _capture_source_chain(entry["source"])
        original_input = executions["original"]["by_ordinal"][command_ordinal]["input"]
        landing_input = executions["landing"]["by_ordinal"][command_ordinal]["input"]
        original_images = _capture_document_images(original_input)
        landing_images = _capture_document_images(landing_input)
        terminal = chain["terminal"]
        require(binding.get("physical_ref") in original_images
                and landing_binding.get("physical_ref") in landing_images,
                "sequential replay binding is absent from its authenticated input")
        source_step_ordinals = []
        node_steps = []
        for node_index, node in enumerate(chain["nodes"]):
            step = _capture_step(landing_records, node["step_id"])
            ordinals = step.get("command_ordinals")
            require(isinstance(ordinals, list) and ordinals
                    and all(type(ordinal) is int for ordinal in ordinals)
                    and ordinals == sorted(ordinals)
                    and ordinals == list(range(ordinals[0], ordinals[-1] + 1)),
                    "sequential replay source step ordering is invalid")
            final_ordinal = ordinals[-1]
            require(final_ordinal < command_ordinal
                    and (not source_step_ordinals or final_ordinal < source_step_ordinals[-1]),
                    "sequential replay source step is future or out of order")
            source_step_ordinals.append(final_ordinal)
            step_input = executions["landing"]["by_ordinal"][ordinals[0]]["input"]
            step_output = executions["landing"]["by_ordinal"][final_ordinal]["output"]
            node_steps.append((node, step, step_input, step_output))
            if node_index + 1 < len(chain["nodes"]):
                require(canonical_json(node["source"]) == canonical_json(chain["nodes"][node_index + 1]),
                        "sequential replay source chain skips a recorded step")
        target_landing = landing_binding.get("physical_ref")
        target_original = binding.get("physical_ref")
        for node_index in range(len(node_steps)):
            node, step, step_input, step_output = node_steps[node_index]
            final_ordinal = step["command_ordinals"][-1]
            candidates = [candidate for candidate in original_records["commands"][final_ordinal]["bindings"]
                          if candidate.get("key") == "commit.materialization"
                          and candidate.get("successor") == target_original
                          and candidate.get("owner") == node["owner"]
                          and set(candidate.get("owners", [])) == set(node["owners"])]
            landing_candidates = [candidate for candidate in landing_records["commands"][final_ordinal]["bindings"]
                                  if candidate.get("key") == "commit.materialization"
                                  and candidate.get("successor") == target_landing
                                  and candidate.get("owner") == node["owner"]
                                  and set(candidate.get("owners", [])) == set(node["owners"])]
            require(len(candidates) == 1 and len(landing_candidates) == 1,
                    "sequential replay source lacks a unique authenticated transition")
            original_transition, landing_transition = candidates[0], landing_candidates[0]
            physical = landing_transition.get("physical_ref")
            original_physical = original_transition.get("physical_ref")
            require(isinstance(physical, str) and isinstance(original_physical, str)
                    and physical in _capture_document_images(step_input),
                    "sequential replay source is absent from its source step input")
            owners = _capture_owners(step_input, physical)
            require(node["owner"] in owners and set(node["owners"]) == set(owners),
                    "sequential replay source owner attribution is incomplete")
            original_owners = _capture_owners(
                executions["original"]["by_ordinal"][final_ordinal]["input"], original_physical)
            require(node["owner"] in original_owners and set(node["owners"]) == set(original_owners),
                    "sequential replay source original owner attribution is incomplete")
            _capture_binding_image(executions["landing"]["by_ordinal"][final_ordinal]["input"], landing_transition)
            _capture_binding_image(executions["original"]["by_ordinal"][final_ordinal]["input"], original_transition)
            require(target_landing in _capture_document_images(step_output),
                    "sequential replay source successor is absent from its materialized output")
            require(target_original in _capture_document_images(
                executions["original"]["by_ordinal"][final_ordinal]["output"]),
                    "sequential replay source successor is absent from its original output")
            target_landing = physical
            target_original = original_physical
        require(target_landing == terminal
                and terminal in _capture_document_images(node_steps[-1][2])
                if node_steps else terminal == landing_binding.get("physical_ref"),
                "sequential replay source has an unbound terminal transition")
        if node_steps:
            require(target_original in _capture_document_images(
                executions["original"]["by_ordinal"][node_steps[-1][1]["command_ordinals"][0]]["input"]),
                    "sequential replay source has no authenticated original base image")
        continued, _ = site(images(source), target_original, [], continuations)
        require(continued == target_landing,
                "sequential replay source terminal differs from authenticated history")
    require(seen_map == expected_map,
            "sequential replay map does not cover every authenticated replay input")
    return {"binding_pairs": binding_pairs,
            "original": executions["original"]["by_ordinal"],
            "landing": executions["landing"]["by_ordinal"]}


def validate(request, prepared, source, base=None, continuations=None, history=None, sequential=None):
    """Check request/record correspondence at authenticated immutable boundaries."""
    records = prepared["records"]
    continuations = copy.deepcopy(continuations or {})
    boundary = images(source)
    original = images(base or source)
    if base is not None:
        for read in request.get("reads", []):
            validate_read(images(base), read)
    batch_reads = []
    for read in request.get("reads", []):
        if sequential is not None and "binding_pairs" in sequential:
            _, read = _sequential_assertion(read, [0], sequential, "dependency")
        batch_reads.append(validate_read(boundary, read, continuations))
    validate_claims(request, records)
    accepted = images(prepared["canonical_document"])
    touched = set()
    manifest = copy.deepcopy(source["dependency_manifest"])
    if records["merge_mode"] == "atomic":
        for record in records["commands"]:
            for capture in [*record["writes"], *record["reads"], *record["derived_writes"]]:
                touched.add(native_site(boundary, capture["ref"], capture["path"])[0])
            touched.update(binding["physical_ref"] for binding in record["bindings"] if "physical_ref" in binding)
    for step in records["steps"]:
        command_inputs = {step["command_ordinals"][0]: boundary}
        input_manifest = copy.deepcopy(manifest)
        command_manifests = {}
        for ordinal in step["command_ordinals"]:
            # Consumed input pins are checked by the request-private port at
            # acceptance. Only earlier commands contribute to this boundary;
            # a following binding cannot allocate a physical identity.
            for dependency in records["commands"][ordinal]["dependencies"]:
                pin = dependency.get("pin", {})
                if dependency.get("kind") == "media":
                    media_id = pin.get("object_id", pin.get("media_id"))
                    if media_id is not None:
                        media = {row["media_id"]: row for row in manifest["media"]}
                        media[media_id] = {"media_id": media_id, "content_digest": media_id}
                        manifest["media"] = sorted(media.values(), key=lambda row: row["media_id"])
                elif dependency.get("kind") in {"source", "transcript"} and pin not in manifest["documents"]:
                    manifest["documents"].append(copy.deepcopy(pin))
                    manifest["documents"].sort(key=lambda row: (row["document_id"], row["version"], row["content_digest"]))
            command_manifests[ordinal] = copy.deepcopy(manifest)
        # Hydrated documents consumed by the first command can rekey the
        # unchanged effect-before parent. Later commands cannot allocate it.
        input_manifest["documents"] = command_manifests[step["command_ordinals"][0]]["documents"]
        input_parent_revision = None
        if input_manifest["documents"] != source["dependency_manifest"]["documents"]:
            input_parent_revision = _authoring_parent_identity(
                boundary, (source["project_id"], source["timeline_id"]), input_manifest)
        for ordinal, next_ordinal in zip(step["command_ordinals"], step["command_ordinals"][1:]):
            command_inputs[next_ordinal] = command_output(
                command_inputs[ordinal], records["commands"][ordinal], records["commands"][next_ordinal],
                accepted=accepted, identity_scope=(source["project_id"], source["timeline_id"]),
                manifest=command_manifests[ordinal])
        if sequential is not None:
            for ordinal in step["command_ordinals"]:
                captured = sequential["landing"].get(ordinal)
                require(captured is not None
                        and _capture_projection_equal(images(captured["input"]), command_inputs[ordinal]),
                        "provider sequential command input differs from its authenticated projection")
                if captured is None:
                    raise AssertionError("unreachable missing sequential command capture")
                next_ordinal = next((next_value for current, next_value in zip(
                    step["command_ordinals"], step["command_ordinals"][1:]) if current == ordinal), None)
                if next_ordinal is not None:
                    require(_capture_projection_equal(images(captured["output"]), command_inputs[next_ordinal]),
                            "provider sequential command output differs from its next input projection")
        validate_step(request, records, step, boundary, batch_reads, continuations, command_inputs, sequential)
        for ref in touched:
            require(covers(step["dependencies"], {"kind": "scope", "ref": ref, "path": []}),
                    "provider atomic dependency union omits a touched scope")
        output = step_output(boundary, step, records, accepted, original)
        if sequential is not None:
            last = sequential["landing"].get(step["command_ordinals"][-1])
            require(last is not None and _capture_projection_equal(images(last["output"]), output),
                    "provider sequential command output differs from its authenticated projection")
        effect_boundaries = _inverse_stage_boundaries(boundary, output, step, records, accepted, original, history)
        for ordinal in step["command_ordinals"]:
            record = records["commands"][ordinal]
            command_input = command_inputs[ordinal]
            if record["command"]["op"] == "doc.patch":
                indices = [binding.get("boundary", {}).get("change_ordinal") for binding in record["bindings"]
                           if binding["key"].startswith("doc.patch:")]
                require(indices == list(range(len(record["command"]["args"]["changes"]))),
                        "provider patch bindings do not cover its ordered changes")
            validate_bindings(request, records, prepared["expected_head"], command_input, output, step, ordinal,
                              continuations, original, boundary, effect_boundaries, input_parent_revision,
                              sequential)
        for ordinal in step["command_ordinals"]:
            for binding in records["commands"][ordinal]["bindings"]:
                if binding.get("key") == "commit.materialization":
                    continuations.setdefault(binding["physical_ref"], set()).add(binding["successor"])
        boundary = output
    # Materialization can reuse a historical parent revision with these exact
    # bytes. Step bindings still name the projected execution image above;
    # immutable destination provenance is checked separately by the store.
    boundary["parent"]["revision_id"] = accepted["parent"]["revision_id"]
    require(value_equal(boundary, accepted), "provider step effects do not reach the accepted closure")

"""Renderer-free persistence for the frozen timeline commit contract.

Callers supply schema/event validation and request-private input captures. Only
this module owns the acceptance transaction; provider execution belongs outside
RealmStore's mutex.
"""
from __future__ import annotations

import base64
import hashlib
import json
import re

from .errors import ConflictError, ProtocolError, ValidationError
from .idempotency import command_result
from .timeline_commit_validation import detached, digest
from .timeline_materialization import has_materialization, item_identity, materialization_join, root_identity
from .util import canonical_json, new_id, now

_METADATA = ("source", "label", "rationale", "group_id")
_DIGEST = re.compile(r"sha256:[0-9a-f]{64}\Z")
_TEXT_BINDING_REF = re.compile(r"occurrence:([^/]+)/text-binding:(prompt|voiceover_script|transcript)(?::([a-z][a-z0-9-]{0,63}))?\Z")


def reject(reason, message=None, *, status=409):
    from .timeline_commit import CommitRejected

    raise CommitRejected({"http_status": status, "code": "conflict" if status == 409 else "validation_error",
                          "message": message or reason, "details": {"status": "refused", "reason": reason,
                          "base": None, "current": None, "conflicts": []}})


def request_identity(context):
    invocation = context["invocation"]
    return hashlib.sha256(canonical_json({"operation": invocation["operation"], "path": invocation["path"],
                          "publisher": context["publisher"], "request": invocation["body"]}).encode()).hexdigest()


def scope(context):
    request = context["request"]
    return canonical_json([request["project_id"], request["timeline_id"]])


def _effective_merge_mode(request):
    """Return the contract's requested mode after the conservative patch rule."""
    requested = request.get("merge", "fields")
    if requested == "atomic":
        return "atomic"

    def contains_document_patch(commands):
        for command in commands:
            if command.get("op") == "doc.patch":
                return True
            if command.get("op") == "timeline.batch" and contains_document_patch(command.get("args", {}).get("commands", [])):
                return True
        return False

    if "reads" not in request and contains_document_patch(request.get("commands", [])):
        return "atomic"
    return requested


def _is_v2_request(request, records=None):
    """Return whether the caller opted into the v2 request annotations.

    ABI-1 requests are intentionally left byte-for-byte compatible: their
    result and legacy history metadata must not acquire synthetic v2 fields.
    Once any v2 control is present, the provider's authoritative step records
    and the effective merge mode are part of the durable result.
    """
    return any(key in request for key in ("label", "steps", "merge", "reads")) or (
        records is not None and "steps" in records
    ) or any(command.get("op") == "doc.patch" for command in request.get("commands", []))


def _history_metadata(request, data):
    """Project request annotations and effective commit facts into one JSON value.

    The value is stored in the existing history row.  In particular, no actor
    value is accepted from the request: ``publisher`` is added to the result and
    history edge from the authenticated execution context by the caller.
    """
    metadata = {key: request[key] for key in _METADATA if key in request}
    if _is_v2_request(request) or "steps" in data:
        metadata["label"] = data["label"]
        metadata["merge"] = request.get("merge", "fields")
        metadata["merge_mode"] = data["merge_mode"]
        if "reads" in request:
            metadata["reads"] = request["reads"]
    return metadata


def _validate_record_metadata(request, records):
    """Require the provider's authoritative v2 metadata, while leaving ABI-1 untouched."""
    if not _is_v2_request(request, records):
        return
    if records.get("label") != request.get("label", "Timeline edit"):
        reject("invalid_records", "provider label differs from the request", status=422)
    if records.get("merge_mode") != _effective_merge_mode(request):
        reject("invalid_records", "provider merge mode differs from the effective request mode", status=422)
    if "steps" not in records:
        reject("invalid_records", "provider did not return authoritative step records", status=422)
    if any("dependencies" not in step for step in records["steps"]):
        reject("invalid_records", "provider step dependencies are missing", status=422)


_SHELL_SCOPE_TABLES = ("timeline_shots", "timeline_references", "timeline_render_publications",
                       "timeline_document_input_links", "timeline_commit_history")


def has_authored_content(value):
    if isinstance(value, dict):
        return any(has_authored_content(item) for item in value.values())
    if isinstance(value, list):
        return any(has_authored_content(item) for item in value)
    return value is not None


def timeline_scope_is_empty(conn, timeline_id, *, project_id=None):
    """True when nothing is authored under the timeline or its legacy document."""
    if project_id is not None:
        document = conn.execute("SELECT content_json FROM project_documents WHERE id=? AND project_id=?",
                                (f"timeline:{timeline_id}", project_id)).fetchone()
        if document is not None:
            # Baseline verification already rejects duplicate/non-finite JSON.
            # Use the same parser here so corrupt legacy bytes cannot hide
            # authored content behind a last-key-wins decode.
            from .timeline_commit_baseline import _json
            try:
                content = _json(document["content_json"])
            except (TypeError, ValueError):
                return False
            if has_authored_content(content):
                return False
    # Any row keyed to the timeline is authored data.
    for table in _SHELL_SCOPE_TABLES:
        if conn.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (table,)).fetchone() and \
                conn.execute(f"SELECT 1 FROM {table} WHERE timeline_id=? LIMIT 1", (timeline_id,)).fetchone():
            return False
    # create_timeline snapshots the empty shell as timeline_revisions v1; only a non-empty snapshot is authored.
    if conn.execute("SELECT 1 FROM timeline_revisions WHERE timeline_id=? AND (shots_json!='[]' OR references_json!='[]') LIMIT 1",
                    (timeline_id,)).fetchone():
        return False
    for child in ("composition_revision_occurrences", "composition_revision_dependencies"):
        if conn.execute(f"SELECT 1 FROM {child} c JOIN parent_composition_revisions r ON r.id=c.parent_revision_id "
                        "WHERE r.timeline_id=? LIMIT 1", (timeline_id,)).fetchone():
            return False
    return True


class TimelineCommitStore:
    def __init__(self, store, *, validate_prepared, validate_event=None):
        self.store = store
        # Validation uses the wire worker's authoritative schema, including
        # Agent-owned leaves. It must raise on invalid data, never normalize it.
        self.validate_prepared = validate_prepared
        self.validate_event = validate_event

    @property
    def conn(self):
        return self.store.conn

    def _membership(self, project_id, timeline_id):
        row = self.conn.execute("SELECT p.realm_id FROM timelines t JOIN projects p ON p.id=t.project_id "
                                "WHERE t.id=? AND t.project_id=? AND t.archived_at IS NULL",
                                (timeline_id, project_id)).fetchone()
        if row is None:
            reject("history_unavailable")
        return row["realm_id"]

    def lookup(self, context, *, authorize):
        with self.store._mutex:
            authorize()
            request = context["request"]
            # Lookup is the only path allowed to inspect an archived scope:
            # it must first authenticate the current actor, then prove the
            # project/timeline row exists, and only then read the exact key.
            # New writes continue through _membership's active-row guard.
            row = self.conn.execute(
                "SELECT p.realm_id FROM timelines t JOIN projects p ON p.id=t.project_id "
                "WHERE t.id=? AND t.project_id=?",
                (request["timeline_id"], request["project_id"]),
            ).fetchone()
            if row is None or row["realm_id"] != context["realm_id"]:
                reject("authority_changed")
            return self._lookup(context)

    def _lookup(self, context):
        row = self.conn.execute("SELECT * FROM command_idempotency WHERE command_kind='timeline.commit' "
                                "AND aggregate_id=? AND idempotency_key=?", (scope(context), context["idempotency_key"])).fetchone()
        if row is None:
            return None
        if row["request_hash"] != context["request_hash"]:
            reject("idempotency_mismatch")
        edge = self.conn.execute("SELECT * FROM timeline_commit_history WHERE publication_id=?", (row["txn_id"],)).fetchone()
        if edge is None or edge["project_id"] != context["request"]["project_id"] or edge["timeline_id"] != context["request"]["timeline_id"]:
            raise ProtocolError("accepted commit history is missing or corrupt")
        self._verify_accepted(row, edge, allow_archived=True)
        return self._envelope(row, edge["project_id"])

    def _verify_accepted(self, row, edge, *, allow_archived=False):
        from .timeline_commit import CommitRejected
        try:
            data, records = json.loads(row["result_json"]), json.loads(edge["records_json"])
            previous = {"revision_id": edge["previous_revision_id"], "publication_id": edge["previous_publication_id"]}
            document = data["canonical_document"]
            valid = (edge["intent"] == "recorded" and row["command_kind"] == "timeline.commit"
                     and row["txn_id"] == edge["publication_id"]
                     and row["aggregate_id"] == canonical_json([edge["project_id"], edge["timeline_id"]])
                     and row["primary_stream_id"] == edge["timeline_id"]
                     and row["first_project_seq"] == row["last_project_seq"] == edge["project_seq"]
                     and data["accepted_revision_id"] == document["parent_revision"]["revision_id"] == edge["revision_id"]
                     and document["project_id"] == edge["project_id"] and document["timeline_id"] == edge["timeline_id"]
                     and data["document_digest"] == digest(document)
                     and canonical_json(data["commands"]) == canonical_json([r["command"] for r in records["commands"]])
                     and data["previous_revision_id"] == previous["revision_id"]
                     and data["previous_publication_id"] == previous["publication_id"]
                     and data["publisher"] == edge["publisher"]
                     and all(data[k] == edge[k] for k in ("provider_version", "compiler_version"))
                     and {k: data[k] for k in json.loads(edge["metadata_json"])
                          if k in data and k in _METADATA} == {
                         k: json.loads(edge["metadata_json"])[k] for k in json.loads(edge["metadata_json"])
                         if k in _METADATA
                     })
            base = {"revision_id": data["base_revision_id"], "publication_id": data["base_publication_id"]}
            historical_status = "accepted" if previous == base else "rebased"
            modern_status = "accepted" if previous == base else "merged"
            valid = valid and data["status"] in {historical_status, modern_status}
            valid = valid and data["rebased_onto"] == (None if previous == base else previous)
            metadata = json.loads(edge["metadata_json"])
            if "merge_mode" in metadata:
                valid = valid and data.get("merge_mode") == metadata["merge_mode"]
            if "merge" in metadata:
                valid = valid and metadata["merge"] in {"fields", "atomic"}
            if "reads" in metadata:
                valid = valid and data.get("reads", metadata["reads"]) == metadata["reads"]
            if "steps" in records:
                valid = valid and data.get("steps") == records["steps"]
            if "label" in records:
                valid = valid and data.get("label") == records["label"]
            if "merge_mode" in records:
                valid = valid and data.get("merge_mode") == records["merge_mode"]
            if "steps" in records:
                from .timeline_commit_auth import validate
                replay_request = {**metadata, "commands": data["commands"],
                                  "base_revision_id": base["revision_id"], "base_publication_id": base["publication_id"]}
                source = self.revision_closure(edge["project_id"], edge["timeline_id"], previous["revision_id"],
                                               allow_archived=allow_archived)
                continuations = self._binding_continuations(
                    edge["project_id"], edge["timeline_id"], base["publication_id"], previous,
                    allow_archived=allow_archived,
                )
                history = self._inverse_stage_history(edge["project_id"], edge["timeline_id"], records,
                                                      allow_archived=allow_archived)
                validate(replay_request, {"records": records, "expected_head": previous, "canonical_document": document},
                         source, continuations=continuations, history=history)
            ids = json.loads(row["event_ids_json"])
            seq = row["resulting_stream_seq"]
            # Replay verifies the accepted prefix, independent of later writes.
            events = self.conn.execute("SELECT * FROM timeline_events WHERE timeline_id=? ORDER BY id LIMIT ?",
                                       (edge["timeline_id"], seq)).fetchall()
            valid = valid and isinstance(ids, list) and 0 < len(ids) <= seq <= len(events)
            valid = valid and ids == [str(e["id"]) for e in events[seq - len(ids):seq]]
            project_seq = self.conn.execute("SELECT next_seq FROM project_sequences WHERE project_id=?",
                                            (edge["project_id"],)).fetchone()
            valid = valid and project_seq is not None and 0 < edge["project_seq"] < project_seq[0]
            previous_hash = ""
            for event in events:
                hashed = {"timeline_id": edge["timeline_id"], "kind": event["kind"],
                          "payload": json.loads(event["payload_json"]), "previous_hash": previous_hash,
                          "created_at": event["created_at"]}
                valid = valid and event["previous_hash"] == previous_hash and event["event_hash"] == digest(hashed)[7:]
                previous_hash = event["event_hash"]
            event = self.conn.execute("SELECT * FROM timeline_events WHERE id=? AND timeline_id=?",
                                      (ids[-1], edge["timeline_id"])).fetchone()
            valid = valid and event is not None and event["kind"] == "timeline.commit.accepted"
            if valid:
                payload = json.loads(event["payload_json"])
                valid = payload == {"project_id": edge["project_id"], "timeline_id": edge["timeline_id"],
                                    "previous": previous, "revision_id": edge["revision_id"],
                                    "publisher": edge["publisher"], "intent": "recorded",
                                    "records_digest": digest(records)}
            if not valid:
                raise ValueError()
            prepared = {**data, "records": records, "expected_head": previous}
            if has_materialization(prepared):
                project, timeline = edge["project_id"], edge["timeline_id"]
                allocations = materialization_join(prepared, project, timeline,
                    lambda revision: self.revision_closure(project, timeline, revision,
                                                           allow_archived=allow_archived))
                if canonical_json(document) != canonical_json(self.revision_closure(
                        project, timeline, edge["revision_id"], allow_archived=allow_archived)):
                    raise ValueError()
                self._check_inherited_allocations(project, timeline, records, allocations, edge["project_seq"],
                                                   allow_archived=allow_archived)
        except (KeyError, TypeError, ValueError, IndexError, ValidationError, CommitRejected) as exc:
            raise ProtocolError("accepted commit record is corrupt") from exc

    def _check_inherited_allocations(self, project, timeline, records, allocations, before_seq=None,
                                     *, allow_archived=False):
        inverse_refs = {d["key"].removeprefix("materialization.source:")
                        for r in records["commands"] if r["command"]["op"] == "timeline.inverse"
                        for d in r["dependencies"] if d["key"].startswith("materialization.source:")}
        if not inverse_refs:
            return
        inherited = {}
        for publication in records["undo_of"]:
            if before_seq is not None:
                row = self.conn.execute("SELECT project_seq FROM timeline_commit_history WHERE publication_id=?",
                                        (publication,)).fetchone()
                if row is None or row[0] >= before_seq:
                    reject("invalid_records")
            entry = self.history_entry(project, timeline, publication, allow_archived=allow_archived)
            data = entry["receipt"]["result"]
            target = {**data, "records": entry["records"], "expected_head": entry["previous"]}
            if has_materialization(target):
                for shot, allocation in materialization_join(target, project, timeline,
                        lambda revision: self.revision_closure(project, timeline, revision,
                                                               allow_archived=allow_archived)).items():
                    if shot in inherited and canonical_json(inherited[shot]) != canonical_json(allocation):
                        reject("invalid_records")
                    inherited[shot] = allocation
        if any(canonical_json(allocations.get(ref.removeprefix("shot:"))) !=
               canonical_json(inherited.get(ref.removeprefix("shot:"))) for ref in inverse_refs):
            reject("invalid_records", "inverse allocation lacks authenticated provenance")

    @staticmethod
    def _envelope(row, project_id):
        data = (json.loads(row["result_json"]) if row["command_kind"] == "parent_composition.publish" else
                command_result(row["result_json"], kind="timeline.commit", created_at=row["created_at"]))
        receipt = {"receipt_id": row["txn_id"], "command_kind": row["command_kind"],
                   "idempotency_key": row["idempotency_key"], "request_hash": row["request_hash"],
                   "project_id": project_id, "project_seq": [row["first_project_seq"], row["last_project_seq"]],
                   "event_ids": json.loads(row["event_ids_json"]), "result": data, "created_at": row["created_at"]}
        return detached({"data": data, "receipt": receipt})

    def head(self, project_id, timeline_id):
        with self.store._mutex:
            self._membership(project_id, timeline_id)
            row = self.conn.execute("SELECT revision_id, publication_id FROM parent_composition_heads "
                                    "WHERE project_id=? AND timeline_id=?", (project_id, timeline_id)).fetchone()
            if row is None or not row["revision_id"] or not row["publication_id"]:
                reject("history_unavailable")
            entry = self.history_entry(project_id, timeline_id, row["publication_id"])
            if entry["revision_id"] != row["revision_id"]:
                reject("history_unavailable")
            from .timeline_commit_baseline import _publication_events, _shot_projection, _text_bindings
            from .timeline_catalog import verify_catalog_tail
            ledger = self.conn.execute("SELECT resulting_stream_seq, last_project_seq FROM command_idempotency WHERE txn_id=?",
                                       (row["publication_id"],)).fetchone()
            try:
                events, _, _ = _publication_events(self.conn, project_id, timeline_id)
                catalog = verify_catalog_tail(self.conn, project_id, timeline_id, events, ledger[0], ledger[1],
                                              legacy=entry["intent"] == "legacy_unknown")
                if catalog:
                    from .cas import ContentAddressedStore
                    document = self.revision_closure(project_id, timeline_id, row["revision_id"])
                    if entry["intent"] == "recorded" and document != entry["receipt"]["result"]["canonical_document"]:
                        reject("history_unavailable", "canonical film differs from accepted publication")
                    for shot in document["shot_revisions"]:
                        _shot_projection(self.conn, project_id, shot["shot_id"])
                        _text_bindings(self.conn, project_id, shot, ContentAddressedStore(self.store.cas_root).read)
            except ConflictError as exc:
                from .timeline_commit import CommitRejected
                raise CommitRejected({"http_status": 409, "code": "conflict",
                                      "message": "timeline has untracked writes",
                                      "details": {"base": None, "current": None, "conflicts": [], **exc.details}}) from exc
            except (KeyError, TypeError, ValueError, IndexError):
                reject("history_unavailable", "timeline catalog facts are corrupt")
            return dict(row)

    def history_entry(self, project_id, timeline_id, publication_id, *, allow_archived=False):
        with self.store._mutex:
            if allow_archived:
                row = self.conn.execute(
                    "SELECT p.realm_id FROM timelines t JOIN projects p ON p.id=t.project_id "
                    "WHERE t.id=? AND t.project_id=?", (timeline_id, project_id)).fetchone()
                if row is None:
                    reject("history_unavailable")
            else:
                self._membership(project_id, timeline_id)
            row = self.conn.execute("SELECT * FROM timeline_commit_history WHERE publication_id=? "
                                    "AND project_id=? AND timeline_id=?", (publication_id, project_id, timeline_id)).fetchone()
            if row is None:
                reject("history_unavailable")
            ledger = self.conn.execute("SELECT * FROM command_idempotency WHERE txn_id=?", (publication_id,)).fetchone()
            if ledger is None or ledger["first_project_seq"] != row["project_seq"]:
                reject("history_unavailable")
            if row["intent"] == "recorded" or ledger["command_kind"] == "timeline.commit":
                self._verify_accepted(ledger, row, allow_archived=allow_archived)
            previous = None if row["previous_publication_id"] is None else {
                "revision_id": row["previous_revision_id"], "publication_id": row["previous_publication_id"]}
            records = json.loads(row["records_json"]) if row["records_json"] is not None else None
            entry = {"publication_id": publication_id, "revision_id": row["revision_id"], "previous": previous,
                     "receipt": self._envelope(ledger, project_id)["receipt"], "intent": row["intent"],
                     "records": records, "provider_version": row["provider_version"],
                     "compiler_version": row["compiler_version"], "publisher": row["publisher"],
                     **json.loads(row["metadata_json"])}
            # Modern records carry the authenticated provider projection.  A
            # legacy edge has no recorder and must remain null/absent rather
            # than receiving invented step or undo authority.
            if records is not None and "steps" in records:
                entry["steps"] = records["steps"]
            return entry

    def history(self, project_id, timeline_id, through, after_publication_id=None, cursor=None, limit=100):
        if type(limit) is not int or not 1 <= limit <= 200:
            raise ValidationError("history limit must be 1–200")
        with self.store._mutex:
            bound = self.history_entry(project_id, timeline_id, through["publication_id"])
            if bound["revision_id"] != through["revision_id"]:
                reject("history_unavailable")
            after = self.history_entry(project_id, timeline_id, after_publication_id) if after_publication_id else None
            low = after["receipt"]["project_seq"][0] if after else 0
            high = bound["receipt"]["project_seq"][0]
            cursor_scope = [project_id, timeline_id, through, after_publication_id]
            start = low
            if cursor is not None:
                try:
                    decoded = json.loads(base64.urlsafe_b64decode(cursor.encode()))
                    if decoded["scope"] != cursor_scope or type(decoded["seq"]) is not int or not low < decoded["seq"] <= high:
                        raise ValueError()
                    start = decoded["seq"]
                except (ValueError, KeyError, TypeError) as exc:
                    raise ValidationError("invalid history cursor") from exc
            if low > high:
                reject("history_unavailable")
            rows = self.conn.execute("SELECT publication_id FROM timeline_commit_history WHERE project_id=? AND timeline_id=? "
                                     "AND project_seq>? AND project_seq<=? ORDER BY project_seq LIMIT ?",
                                     (project_id, timeline_id, start, high, limit + 1)).fetchall()
            items = [self.history_entry(project_id, timeline_id, row[0]) for row in rows[:limit]]
            previous = self.conn.execute("SELECT publication_id, revision_id FROM timeline_commit_history WHERE project_id=? "
                                        "AND timeline_id=? AND project_seq<=? ORDER BY project_seq DESC LIMIT 1",
                                        (project_id, timeline_id, start)).fetchone()
            expected = dict(previous) if previous else None
            for entry in items:
                if entry["previous"] != expected:
                    reject("history_unavailable")
                expected = {"publication_id": entry["publication_id"], "revision_id": entry["revision_id"]}
            if len(rows) <= limit and expected != through:
                reject("history_unavailable")
            next_cursor = None
            if len(rows) > limit:
                next_cursor = base64.urlsafe_b64encode(canonical_json({"scope": cursor_scope,
                    "seq": items[-1]["receipt"]["project_seq"][0]}).encode()).decode()
            return {"items": items, "next_cursor": next_cursor, "head": detached(through)}

    def revision_closure(self, project_id, timeline_id, revision_id, *, allow_archived=False):
        with self.store._mutex:
            if allow_archived:
                row = self.conn.execute(
                    "SELECT 1 FROM timelines WHERE id=? AND project_id=?",
                    (timeline_id, project_id),
                ).fetchone()
                if row is None:
                    reject("history_unavailable")
            else:
                self._membership(project_id, timeline_id)
            parent = self.conn.execute("SELECT * FROM parent_composition_revisions WHERE id=? AND project_id=? AND timeline_id=?",
                                       (revision_id, project_id, timeline_id)).fetchone()
            if parent is None:
                reject("history_unavailable")
            if parent["commit_manifest_json"] is None:
                from .cas import ContentAddressedStore
                from .timeline_commit_baseline import verify_revision_source
                document = verify_revision_source(self.conn, project_id, timeline_id, revision_id,
                                                   read_object=ContentAddressedStore(self.store.cas_root).read)
                self._validate_closure(document, allow_archived=allow_archived)
                return document
            manifest = json.loads(parent["commit_manifest_json"])
            document = {"schema_version": 1, "project_id": project_id, "timeline_id": timeline_id,
                        "parent_revision": self._image(parent), "shot_revisions": [],
                        "internal_timeline_revisions": [], "dependency_manifest": manifest}
            for family, table in (("shot_revisions", "shot_revisions"), ("internal_timeline_revisions", "internal_timeline_revisions")):
                pins = manifest["shots" if family == "shot_revisions" else "internal_timelines"]
                for pin in pins:
                    row = self.conn.execute(f"SELECT * FROM {table} WHERE id=? AND project_id=?", (pin["revision_id"], project_id)).fetchone()
                    if row is None:
                        reject("history_unavailable")
                    image = self._image(row)
                    image.update({key: row[key] for key in ("shot_id", "internal_timeline_revision_id") if key in row.keys()})
                    if family == "internal_timeline_revisions":
                        image["timeline_id"] = row["timeline_id"]
                    document[family].append(image)
            self._validate_closure(document, allow_archived=allow_archived)
            self._verify_inputs(document)
            return document

    def source_revision_closure(self, project_id, timeline_id, revision_id, publication_id,
                                content_digest):
        """Return one authenticated historical source closure.

        The source pair is deliberately checked separately from the request's
        destination head.  A revision ID alone is not a source authority: the
        accepted publication edge and the immutable parent digest must agree
        with the caller's exact reference.
        """
        with self.store._mutex:
            entry = self.history_entry(project_id, timeline_id, publication_id)
            if entry["revision_id"] != revision_id:
                reject("dependency_unavailable", "source publication and revision pins disagree")
            document = self.revision_closure(project_id, timeline_id, revision_id)
            if document is not None:
                parent = document.get("parent_revision")
                if not isinstance(parent, dict) or parent.get("content_digest") != content_digest:
                    reject("dependency_unavailable", "source revision content digest disagrees")
                return document
            reject("dependency_unavailable", "source revision closure is unavailable")

    def _verify_inputs(self, document):
        for pin in document["dependency_manifest"]["documents"]:
            row = self.conn.execute("SELECT c.content_json, c.content_size, b.kind FROM timeline_document_input_contents c "
                "JOIN timeline_document_input_bindings b ON b.content_digest=c.content_digest "
                "JOIN timeline_document_input_links l ON l.project_id=b.project_id AND l.document_id=b.document_id "
                "AND l.document_version=b.document_version AND l.content_digest=b.content_digest "
                "WHERE l.project_id=? AND l.timeline_id=? AND l.revision_id=? AND b.document_id=? "
                "AND b.document_version=? AND b.content_digest=? LIMIT 1",
                (document["project_id"], document["timeline_id"], document["parent_revision"]["revision_id"],
                 pin["document_id"], pin["version"], pin["content_digest"])).fetchone()
            if row is None or digest(json.loads(row["content_json"])) != pin["content_digest"] or len(row["content_json"].encode()) != row["content_size"]:
                reject("dependency_unavailable", "retained input is missing or corrupt")
            from .timeline_commit_inputs import PROJECT_PACK_KIND, validate_pack_snapshot_objects
            if row["kind"] == PROJECT_PACK_KIND:
                validate_pack_snapshot_objects(self.conn, document["project_id"], json.loads(row["content_json"]))

    def integrity_errors(self):
        errors = []
        previous = {}
        for edge in self.conn.execute("SELECT * FROM timeline_commit_history ORDER BY project_id, timeline_id, project_seq"):
            try:
                key = (edge["project_id"], edge["timeline_id"])
                expected = previous.get(key)
                actual = (edge["previous_publication_id"], edge["previous_revision_id"])
                if actual != (expected if expected else (None, None)):
                    raise ValueError("history ancestry mismatch")
                previous[key] = (edge["publication_id"], edge["revision_id"])
                ledger = self.conn.execute("SELECT * FROM command_idempotency WHERE txn_id=?", (edge["publication_id"],)).fetchall()
                if len(ledger) != 1 or ledger[0]["first_project_seq"] != edge["project_seq"]:
                    raise ValueError("history receipt missing or ambiguous")
                if edge["intent"] == "recorded":
                    self._verify_accepted(ledger[0], edge)
                    self._verify_inputs(json.loads(ledger[0]["result_json"])["canonical_document"])
                elif edge["records_json"] is not None or ledger[0]["command_kind"] != "parent_composition.publish":
                    raise ValueError("invented legacy provenance")
            except Exception as exc:
                errors.append({"table": "timeline_commit_history", "id": edge["publication_id"], "reason": str(exc)})
        for key, expected in previous.items():
            head = self.conn.execute("SELECT publication_id, revision_id FROM parent_composition_heads WHERE project_id=? AND timeline_id=?", key).fetchone()
            if head is None or tuple(head) != expected:
                errors.append({"table": "parent_composition_heads", "id": key[1], "reason": "publication head mismatch"})
        for row in self.conn.execute("SELECT * FROM timeline_document_input_contents"):
            try:
                value = detached(json.loads(row["content_json"]))
                if digest(value) != row["content_digest"] or canonical_json(value) != row["content_json"] or len(row["content_json"].encode()) != row["content_size"]:
                    raise ValueError("retained input digest mismatch")
            except Exception as exc:
                errors.append({"table": "timeline_document_input_contents", "id": row["content_digest"], "reason": str(exc)})
        for row in self.conn.execute("SELECT l.* FROM timeline_document_input_links l LEFT JOIN timeline_commit_history h "
                                     "ON h.publication_id=l.publication_id AND h.project_id=l.project_id "
                                     "AND h.timeline_id=l.timeline_id AND h.revision_id=l.revision_id WHERE h.publication_id IS NULL"):
            errors.append({"table": "timeline_document_input_links", "id": row["publication_id"], "reason": "orphan retained input link"})
        return errors

    def shot_closure(self, project_id, shot_id, revision_id):
        with self.store._mutex:
            row = self.conn.execute("SELECT * FROM shot_revisions WHERE id=? AND project_id=? AND shot_id=?",
                                    (revision_id, project_id, shot_id)).fetchone()
            if row is None:
                reject("dependency_unavailable")
            internal = self.conn.execute("SELECT * FROM internal_timeline_revisions WHERE id=? AND project_id=?",
                                         (row["internal_timeline_revision_id"], project_id)).fetchone()
            if internal is None:
                reject("dependency_unavailable")
            shot = {**self._image(row), "shot_id": shot_id, "internal_timeline_revision_id": internal["id"]}
            image = {**self._image(internal), "timeline_id": internal["timeline_id"]}
            if digest(shot["payload"]) != shot["content_digest"] or digest(image["payload"]) != image["content_digest"]:
                reject("dependency_unavailable")
            if shot["payload"].get("internal_timeline_revision_id") != internal["id"]:
                reject("dependency_unavailable")
            manifests = self.conn.execute("SELECT DISTINCT json_extract(p.commit_manifest_json, '$.media'), "
                "json_extract(p.commit_manifest_json, '$.documents') FROM parent_composition_revisions p "
                "JOIN composition_revision_occurrences o ON o.parent_revision_id=p.id "
                "WHERE p.project_id=? AND o.shot_id=? AND o.shot_revision_id=? AND p.commit_manifest_json IS NOT NULL LIMIT 2",
                (project_id, shot_id, revision_id)).fetchall()
            if len(manifests) != 1:
                reject("history_unavailable", "shot input closure is unavailable or ambiguous")
            parent = self.conn.execute("SELECT p.timeline_id, p.id FROM parent_composition_revisions p "
                "JOIN composition_revision_occurrences o ON o.parent_revision_id=p.id "
                "WHERE p.project_id=? AND o.shot_id=? AND o.shot_revision_id=? AND p.commit_manifest_json IS NOT NULL ORDER BY p.id LIMIT 1",
                (project_id, shot_id, revision_id)).fetchone()
            if parent is None:
                reject("history_unavailable")
            document = self.revision_closure(project_id, parent["timeline_id"], parent["id"])
            return {"shot_revision": shot, "internal_timeline_revision": image,
                    "media": document["dependency_manifest"]["media"], "documents": document["dependency_manifest"]["documents"]}

    def _verify_parent_rows(self, document):
        parent_id = document["parent_revision"]["revision_id"]
        occurrences = document["parent_revision"]["payload"]["occurrences"]
        rows = self.conn.execute("SELECT * FROM composition_revision_occurrences WHERE parent_revision_id=? ORDER BY ordinal", (parent_id,)).fetchall()
        if len(rows) != len(occurrences):
            reject("history_unavailable")
        for ordinal, (row, occurrence) in enumerate(zip(rows, occurrences)):
            expected = {"parent_revision_id": parent_id, "project_id": document["project_id"], "ordinal": ordinal,
                        **{k: occurrence[k] for k in ("occurrence_id", "shot_id", "shot_revision_id", "duration_ms", "track")},
                        "gain": occurrence.get("gain", 1),
                        "muted": int(occurrence.get("muted", occurrence.get("mute", False))),
                        "placement_json": canonical_json(occurrence["placement"]),
                        **{k + "_json": canonical_json(occurrence.get(k, default)) for k, default in
                           (("source_offset", 0), ("speed", 1), ("transform", {}), ("provenance", {}))}}
            if dict(row) != expected:
                reject("history_unavailable")
        manifest = document["dependency_manifest"]
        expected = [("shot_revision", p["revision_id"], p["content_digest"]) for p in manifest["shots"]]
        expected += [("internal_timeline_revision", p["revision_id"], p["content_digest"]) for p in manifest["internal_timelines"]]
        expected += [("media", p["media_id"], p["content_digest"]) for p in manifest["media"]]
        rows = self.conn.execute("SELECT dependency_kind, dependency_id, content_digest, ordinal FROM composition_revision_dependencies "
                                 "WHERE parent_revision_id=? ORDER BY ordinal", (parent_id,)).fetchall()
        if [tuple(row) for row in rows] != [(*pin, ordinal) for ordinal, pin in enumerate(expected)]:
            reject("history_unavailable")

    @staticmethod
    def _image(row):
        return {"revision_id": row["id"], "content_digest": row["content_digest"], "payload": json.loads(row["payload_json"])}

    def _validate_closure(self, document, *, allow_archived=False):
        from .visual_seam import parent_clips

        project_id, timeline_id = document["project_id"], document["timeline_id"]
        if allow_archived:
            row = self.conn.execute(
                "SELECT 1 FROM timelines WHERE id=? AND project_id=?",
                (timeline_id, project_id),
            ).fetchone()
            if row is None:
                reject("history_unavailable")
        else:
            self._membership(project_id, timeline_id)
        parent = document["parent_revision"]
        try:
            parent_clips(parent["payload"])
        except (ConflictError, ValidationError) as exc:
            reject("invalid_closure", str(exc), status=422)
        shots, internals = document["shot_revisions"], document["internal_timeline_revisions"]
        manifest = document["dependency_manifest"]
        for clip in parent["payload"]["clips"]:
            if not isinstance(clip, dict) or set(clip) & {"occurrence_id", "shot_revision_id", "parent_revision_id", "composition_revision_id"}:
                reject("invalid_closure", "ordinary clips cannot contain nested compositions", status=422)
        for images, table, identity in (([parent], "parent_composition_revisions", "timeline_id"),
                                        (shots, "shot_revisions", "shot_id"), (internals, "internal_timeline_revisions", "timeline_id")):
            if len({image["revision_id"] for image in images}) != len(images):
                reject("invalid_closure", status=422)
            for image in images:
                if digest(image["payload"]) != image["content_digest"]:
                    reject("invalid_closure", "revision content digest mismatch", status=422)
                owner_id = image.get(identity, timeline_id)
                existing = self.conn.execute(f"SELECT * FROM {table} WHERE id=?", (image["revision_id"],)).fetchone()
                if existing is not None and (existing["project_id"] != project_id or existing[identity] != owner_id
                        or existing["payload_json"] != canonical_json(image["payload"]) or existing["content_digest"] != image["content_digest"]):
                    reject("revision_identity_mismatch")
                if table == "parent_composition_revisions" and existing is not None and existing["commit_manifest_json"] is not None:
                    if existing["commit_manifest_json"] != canonical_json(manifest):
                        reject("revision_identity_mismatch", "revision dependency closure changed")
                if table == "internal_timeline_revisions":
                    payload = image["payload"]
                    nested_fields = {"occurrences", "occurrence_records", "parent_composition", "nested_composition",
                                     "occurrence_id", "shot_revision_id", "parent_revision_id", "composition_revision_id"}
                    # Only authored structure is reserved; params and provenance remain opaque.
                    if set(payload) & nested_fields or any(set(clip) & nested_fields for clip in payload.get("clips", [])):
                        reject("invalid_closure", "internal timeline cannot contain a nested composition", status=422)
                    owner = self.conn.execute("SELECT project_id FROM timelines WHERE id=?", (owner_id,)).fetchone()
                    shot_id = owner_id.removeprefix("shot:") if owner_id.startswith("shot:") else None
                    if owner is None and shot_id:
                        owner = self.conn.execute("SELECT project_id FROM project_shots WHERE id=?", (shot_id,)).fetchone()
                        if owner is None and any(s["shot_id"] == shot_id for s in shots):
                            owner = {"project_id": project_id}
                    if owner is None or owner["project_id"] != project_id:
                        reject("invalid_closure", "internal timeline scope mismatch")
                if table == "shot_revisions":
                    if existing is not None and existing["internal_timeline_revision_id"] != image["internal_timeline_revision_id"]:
                        reject("revision_identity_mismatch")
                    owner = self.conn.execute("SELECT project_id FROM project_shots WHERE id=?", (owner_id,)).fetchone()
                    if owner is not None and owner["project_id"] != project_id:
                        reject("invalid_closure", "shot scope mismatch")
                    if image["payload"].get("internal_timeline_revision_id") != image["internal_timeline_revision_id"]:
                        reject("invalid_closure", status=422)
                    payload = image["payload"]
                    if set(payload) & {"occurrences", "occurrence_records", "parent_composition", "parent_revision_id", "composition_revision_id"}:
                        reject("invalid_closure", "nested shot composition", status=422)
                    if not isinstance(payload.get("items", []), list) or any(not isinstance(item, dict)
                            or not isinstance(item.get("item_id", item.get("id")), str) or not item.get("media_id")
                            for item in payload.get("items", [])):
                        reject("invalid_closure", "shot items cannot be projected", status=422)
        shot_keys = {(s["shot_id"], s["revision_id"]) for s in shots}
        occurrences = parent["payload"]["occurrences"]
        for occurrence in occurrences:
            speed = occurrence.get("speed", 1)
            valid_speed = (type(speed) in (int, float) and speed > 0) or (isinstance(speed, dict)
                and set(speed) == {"numerator", "denominator"} and all(type(v) is int and v > 0 for v in speed.values()))
            if not valid_speed or not occurrence["placement"] or not isinstance(occurrence.get("muted", occurrence.get("mute", False)), bool):
                reject("invalid_closure", "invalid occurrence timing or placement", status=422)
            if "muted" in occurrence and "mute" in occurrence and occurrence["muted"] != occurrence["mute"]:
                reject("invalid_closure", "ambiguous occurrence mute", status=422)
        if shot_keys != {(o["shot_id"], o["shot_revision_id"]) for o in occurrences}:
            reject("invalid_closure", "incomplete or extraneous shot closure", status=422)
        if len({o["occurrence_id"] for o in occurrences}) != len(occurrences):
            reject("invalid_closure", "duplicate occurrences", status=422)
        if {s["internal_timeline_revision_id"] for s in shots} != {i["revision_id"] for i in internals}:
            reject("invalid_closure", "incomplete or extraneous internal closure", status=422)
        for images, key, fields, sort_keys in ((shots, "shots", ("shot_id", "revision_id", "internal_timeline_revision_id", "content_digest"), ("shot_id", "revision_id")),
                (internals, "internal_timelines", ("timeline_id", "revision_id", "content_digest"), ("timeline_id", "revision_id"))):
            ordered = sorted(images, key=lambda image: tuple(image[k] for k in sort_keys))
            if images != ordered or manifest[key] != [{k: image[k] for k in fields} for image in ordered]:
                reject("invalid_closure", "manifest does not equal complete closure", status=422)
        media = manifest["media"]
        if media != sorted(media, key=lambda item: item["media_id"]) or len({m["media_id"] for m in media}) != len(media):
            reject("invalid_closure", status=422)
        for pin in media:
            if not _DIGEST.fullmatch(pin["media_id"]) or pin["content_digest"] != pin["media_id"]:
                reject("invalid_closure", status=422)
            row = self.conn.execute("SELECT o.size FROM objects o JOIN project_objects p ON p.digest=o.digest "
                                    "WHERE p.project_id=? AND p.relation='managed' AND o.digest=?", (project_id, pin["media_id"][7:])).fetchone()
            if row is None:
                reject("dependency_unavailable")
            from .cas import ContentAddressedStore
            data = ContentAddressedStore(self.store.cas_root).read(pin["media_id"][7:])
            if len(data) != row["size"] or "sha256:" + hashlib.sha256(data).hexdigest() != pin["media_id"]:
                reject("dependency_unavailable")
        payload_media = set()
        def collect(value):
            if isinstance(value, dict):
                for key, child in value.items():
                    if key in {"media_id", "object_id"} and isinstance(child, str):
                        normalized = child if child.startswith("sha256:") else "sha256:" + child
                        if _DIGEST.fullmatch(normalized):
                            payload_media.add(normalized)
                    collect(child)
            elif isinstance(value, list):
                for child in value:
                    collect(child)
        for image in [parent, *shots, *internals]:
            collect(image["payload"])
        if not payload_media <= {m["media_id"] for m in media}:
            reject("invalid_closure", "unaccounted media", status=422)
        pins = manifest["documents"]
        if pins != sorted(pins, key=lambda p: (p["document_id"], p["version"], p["content_digest"])) or len({canonical_json(p) for p in pins}) != len(pins):
            reject("invalid_closure", status=422)
        existing = self.conn.execute("SELECT 1 FROM parent_composition_revisions WHERE id=?", (parent["revision_id"],)).fetchone()
        if existing is not None:
            self._verify_parent_rows(document)

    def _binding_continuations(self, project, timeline, base_publication, expected, *, allow_archived=False):
        continuations, cursor = {}, expected
        while cursor["publication_id"] != base_publication:
            entry = self.history_entry(project, timeline, cursor["publication_id"], allow_archived=allow_archived)
            if entry["records"]:
                for record in entry["records"]["commands"]:
                    for binding in record["bindings"]:
                        if binding.get("key") == "commit.materialization":
                            continuations.setdefault(binding["physical_ref"], set()).add(binding["successor"])
            cursor = entry["previous"]
            if cursor is None:
                reject("history_unavailable", "base is outside evaluated head ancestry")
        return continuations

    def _inverse_stage_history(self, project, timeline, records, *, allow_archived=False):
        """Pass only store-authenticated undo sources to inverse-stage auth."""
        if not any(binding.get("key") == "inverse.stage"
                   for record in records.get("commands", []) for binding in record.get("bindings", [])):
            return None
        publications = records.get("undo_of")
        if not isinstance(publications, list):
            reject("history_unavailable", "inverse stage history targets are unavailable")
        return {publication: self.history_entry(project, timeline, publication, allow_archived=allow_archived)
                for publication in publications}

    def _validate(self, context, prepared, inputs):
        # Callers run _check_shot_destinations first, which validates the schema.
        request = context["request"]
        document = prepared["canonical_document"]
        if (document["project_id"], document["timeline_id"]) != (request["project_id"], request["timeline_id"]):
            reject("invalid_closure", status=422)
        if prepared["document_digest"] != digest(document):
            reject("invalid_closure", "whole-document digest mismatch", status=422)
        self._validate_closure(document)
        records = prepared["records"]
        commands = records["commands"]
        if not commands or [r["ordinal"] for r in commands] != list(range(len(commands))):
            reject("invalid_records", status=422)
        recorded_steps = records.get("steps")
        requested_steps = request.get("steps")
        _validate_record_metadata(request, records)
        if _is_v2_request(request) and recorded_steps is None:
            reject("invalid_records", "provider did not return authoritative step records", status=422)
        if recorded_steps is not None:
            ordinals = [ordinal for step in recorded_steps for ordinal in step["command_ordinals"]]
            if ordinals != list(range(len(commands))) or len({step["id"] for step in recorded_steps}) != len(recorded_steps):
                reject("invalid_records", "step records do not partition commands", status=422)
            if requested_steps is not None and [
                    {key: step[key] for key in ("id", "label", "intent", "tags", "command_ordinals")}
                    for step in recorded_steps
                ] != [
                    {key: step[key] for key in ("id", "label", "intent", "tags", "command_ordinals")}
                    for step in requested_steps
                ]:
                reject("invalid_records", "provider step boundaries disagree with the request", status=422)
            from .timeline_commit_auth import validate
            source = self.revision_closure(request["project_id"], request["timeline_id"], prepared["expected_head"]["revision_id"])
            base = self.revision_closure(request["project_id"], request["timeline_id"], request["base_revision_id"])
            continuations = self._binding_continuations(request["project_id"], request["timeline_id"],
                                                       request["base_publication_id"], prepared["expected_head"])
            history = self._inverse_stage_history(request["project_id"], request["timeline_id"], records)
            sequential = None
            if inputs is not None and hasattr(inputs, "_validate_sequential_execution"):
                sequential = inputs._validate_sequential_execution(
                    prepared, source, base, continuations, history,
                )
            from .timeline_commit_auth import sequential_proof_required
            if sequential is None and sequential_proof_required(prepared, source, continuations):
                reject("sequential_proof_unavailable", "moved-head staged physical input requires private sequential proof")
            validate(request, prepared, source, base, continuations, history, sequential=sequential)
        elif any("physical_ref" in binding for record in commands for binding in record["bindings"]):
            reject("invalid_records", "physical bindings require authoritative steps", status=422)
        for record in commands:
            if any(write["cause"] >= len(commands) for write in record["derived_writes"]):
                reject("invalid_records", status=422)
        undo_seqs = [self.history_entry(request["project_id"], request["timeline_id"], publication_id)["receipt"]["project_seq"][0]
                     for publication_id in records["undo_of"]]
        if undo_seqs != sorted(set(undo_seqs)):
            reject("invalid_records", "undo targets must follow acceptance order", status=422)
        restored = records["restored_from"]
        if restored is not None:
            source = self.revision_closure(request["project_id"], request["timeline_id"], restored["revision_id"])
            if source["parent_revision"]["content_digest"] != restored["content_digest"]:
                reject("invalid_records", status=422)
        for event in prepared["semantic_events"]:
            if event["command_ordinal"] >= len(commands) or self.validate_event is None:
                reject("invalid_event", status=422)
            self.validate_event(event)
        if inputs is not None and not has_materialization(prepared):
            inputs.validate(prepared)
        elif inputs is None and (document["dependency_manifest"]["documents"] or any(r["dependencies"] for r in commands)):
            reject("dependency_unavailable", "request-private dependency captures required")
        allocations = self._materializations(context, prepared, inputs)
        self._check_inherited_allocations(request["project_id"], request["timeline_id"], records, allocations)
        return {"canonical_document": document, "document_digest": prepared["document_digest"],
                "commands": [r["command"] for r in commands], "id_map": prepared["id_map"],
                "provider_version": prepared["provider_version"], "compiler_version": prepared["compiler_version"]}

    def _materializations(self, context, prepared, inputs):
        if has_materialization(prepared):
            from .timeline_commit_port import RequestCommitPort
            if not isinstance(inputs, RequestCommitPort) or canonical_json(inputs._provider_context()) != canonical_json(context):
                reject("dependency_unavailable", "request-private materialization captures required")
            return inputs.validate(prepared)
        return materialization_join(prepared, context["request"]["project_id"], context["request"]["timeline_id"],
                                    lambda _: reject("dependency_unavailable"))

    @staticmethod
    def _same_materialization_slot(shot, owner, allocation, prior_allocation, before, after):
        if allocation is None or allocation[0] != owner:
            return False
        pin = allocation[1]
        source = pin["source"]
        edge = [(o["shot_id"], o["shot_revision_id"]) for o in before["parent_revision"]["payload"]["occurrences"]
                if o["occurrence_id"] == owner]
        if edge != [(source["shot_id"], source["revision_id"])]:
            return False
        output = [o["shot_id"] for o in after["parent_revision"]["payload"]["occurrences"] if o["occurrence_id"] == owner]
        members = {i.get("item_id", i.get("id")) for s in after["shot_revisions"]
                   if s["shot_id"] == shot for i in s["payload"].get("items", [])}
        if output != [shot]:
            return False
        if prior_allocation is not None:
            return canonical_json(allocation) == canonical_json(prior_allocation)
        # Frozen M1 edges have no new allocation facts. Their already verified
        # source/binding/read proof remains usable only with this exact closure.
        return (canonical_json(pin["parent"]) == canonical_json({k: before["parent_revision"][k]
                                                                for k in ("revision_id", "content_digest")})
                and members == set(source["item_id_map"].values()))

    def _check_shot_destinations(self, context, prepared, inputs=None):
        # Check the wire shape before inspecting destinations. This preflight
        # precedes closure validation so foreign occupants get the same refusal.
        try:
            self.validate_prepared(prepared)
        except Exception:
            reject("invalid_prepared", "prepared commit does not satisfy the frozen schema", status=422)
        document, records = prepared["canonical_document"], prepared["records"]
        project, timeline = context["request"]["project_id"], context["request"]["timeline_id"]
        # Exact immutable reuse does not write the mutable shot projection.
        writes = [s for s in document["shot_revisions"] if self.conn.execute(
            "SELECT 1 FROM shot_revisions WHERE id=?", (s["revision_id"],)).fetchone() is None]
        if len({s["shot_id"] for s in writes}) != len(writes):
            reject("identity_collision")
        # Agent owns command.created consistency. Reserve the exact recorded
        # reference without interpreting command arguments or inventing ID forms.
        claims = [(item["kind"], item["ref"]) for record in records["commands"]
                  if record["command"]["op"] != "timeline.inverse" for item in record["created"]]
        claims = [(kind, self._reservation_identity(kind, ref)) for kind, ref in claims]
        if len(set(claims)) != len(claims):
            reject("identity_collision")
        self._check_birth_destinations(claims)
        occupied = set()
        for image in writes:
            row = self.conn.execute("SELECT project_id FROM project_shots WHERE id=?", (image["shot_id"],)).fetchone()
            if row is not None:
                if row["project_id"] != project:
                    reject("destination_occupied")
                occupied.add(image["shot_id"])
        allocations = self._materializations(context, prepared, inputs)
        if not writes and not claims:
            return
        current = self.revision_closure(project, timeline, prepared["expected_head"]["revision_id"])
        owned = {s["shot_id"] for s in current["shot_revisions"]}
        fresh = {s["shot_id"] for s in writes} - owned
        for shot in fresh:
            for row in self.conn.execute("SELECT project_id FROM shot_revisions WHERE shot_id=?", (shot,)):
                if row["project_id"] != project:
                    reject("destination_occupied")
                occupied.add(shot)
        heads = {shot: self.conn.execute("SELECT revision_id FROM shot_revision_heads WHERE shot_id=? AND project_id=?",
                                        (shot, project)).fetchone() for shot in occupied}

        def unchanged(shot, revision):
            return heads[shot] is not None and heads[shot]["revision_id"] == revision

        authorized = set()
        for image in current["shot_revisions"]:
            shot = image["shot_id"]
            if shot in occupied and unchanged(shot, image["revision_id"]):
                # A film pin authorizes its own projection, not a newer catalog
                # head written since that pin was accepted.
                occupied.remove(shot)
                authorized.add(shot)
        restored_items = set()
        if occupied:
            from .timeline_commit_port import command_leaves

            requested = [p for c in command_leaves(context["request"]["commands"])
                         if c["op"] == "timeline.inverse" for p in c["args"]["publications"]]
            if requested != prepared["records"]["undo_of"]:
                reject("destination_occupied")

            def edges(value):
                return {o["occurrence_id"]: (o["shot_id"], o["shot_revision_id"])
                        for o in value["parent_revision"]["payload"]["occurrences"]}

            active, output = edges(current), edges(document)
            cursor, remaining = prepared["expected_head"], set(requested)
            while cursor and (occupied or remaining):
                # history_entry authenticates the records against the receipt/event.
                entry = self.history_entry(project, timeline, cursor["publication_id"])
                previous = entry["previous"]
                if entry["intent"] == "recorded":
                    before = self.revision_closure(project, timeline, previous["revision_id"])
                    prior = edges(before)
                    if entry["publication_id"] in remaining:
                        for o, (shot, _) in prior.items():
                            owner, source = "occurrence:" + o, before["parent_revision"]
                            if (shot in occupied and unchanged(shot, prior[o][1])
                                    and output.get(o, (None,))[0] == shot) and any(
                                    w["ref"] == "shot:" + shot or w["ref"] == owner or w["ref"].startswith(owner + "/")
                                    or (w["ref"] == "timeline" and not w["path"] and w["before"] == {
                                        "state": "present", "value": {k: source[k] for k in ("revision_id", "content_digest")}})
                                    for r in entry["records"]["commands"] for w in r["writes"]):
                                occupied.discard(shot)
                                authorized.add(shot)
                                restored_items.update(i.get("item_id", i.get("id"))
                                    for s in before["shot_revisions"] if s["shot_id"] == shot
                                    for i in s["payload"].get("items", []))
                        remaining.remove(entry["publication_id"])
                    accepted_document = self.revision_closure(project, timeline, entry["revision_id"])
                    after = edges(accepted_document)
                    historical = {**entry["receipt"]["result"], "records": entry["records"], "expected_head": previous}
                    prior_allocations = (materialization_join(historical, project, timeline,
                        lambda revision: self.revision_closure(project, timeline, revision))
                        if has_materialization(historical) else {})
                    for o, (shot, _) in after.items():
                        owner = "occurrence:" + o
                        if shot in allocations or shot in prior_allocations:
                            if not self._same_materialization_slot(shot, o, allocations.get(shot),
                                    prior_allocations.get(shot), before, accepted_document):
                                continue
                        if (shot in occupied and unchanged(shot, after[o][1])
                                and output.get(o, (None,))[0] == shot and o in prior
                                and active.get(o) == prior[o]
                                and any(any(b["ref"] == owner for b in r["bindings"])
                                        and any(read["ref"] == owner + "/shot" and read["path"] == ["shot_id"]
                                                and read["state"] == {"state": "present", "value": prior[o][0]}
                                                for read in r["reads"]) for r in entry["records"]["commands"])):
                            occupied.remove(shot)
                            authorized.add(shot)
                cursor = previous
            if occupied or remaining:
                reject("destination_occupied")
        destinations, fresh_items = {}, set()
        old_items = {s["shot_id"]: {i.get("item_id", i.get("id")) for i in s["payload"].get("items", [])}
                     for s in current["shot_revisions"]}
        for image in writes:
            shot = image["shot_id"]
            for item in image["payload"].get("items", []):
                identity = item.get("item_id", item.get("id"))
                if not identity or identity in destinations:
                    reject("identity_collision")
                destinations[identity] = shot
                if identity not in old_items.get(shot, set()):
                    fresh_items.add(identity)
        for identity, shot in destinations.items():
            row = self.conn.execute("SELECT shot_id FROM shot_items WHERE id=?", (identity,)).fetchone()
            if row is not None and (row["shot_id"] != shot or shot not in authorized):
                reject("identity_collision")
            for retained in self.conn.execute(
                    "SELECT DISTINCT s.* FROM shot_revisions s, json_each(s.payload_json, '$.items') i "
                    "WHERE COALESCE(json_extract(i.value, '$.item_id'), json_extract(i.value, '$.id'))=?", (identity,)):
                if (digest(json.loads(retained["payload_json"])) != retained["content_digest"]
                        or retained["project_id"] != project or retained["shot_id"] != shot or shot not in authorized):
                    reject("identity_collision")
        if not fresh and not fresh_items and not claims:
            return
        # Missing history cannot prove that a free ID was never reserved. Exact
        # matching records are authenticated against their durable receipt/event.
        if self.conn.execute("SELECT 1 FROM command_idempotency c LEFT JOIN timeline_commit_history h ON h.publication_id=c.txn_id "
                             "WHERE c.command_kind='timeline.commit' AND h.publication_id IS NULL LIMIT 1").fetchone():
            reject("identity_collision")
        reservations = set(claims) | {("shot", "shot:" + shot) for shot in fresh - authorized}
        reservations.update(("item", identity) for identity in fresh_items - restored_items)
        for kind, ref in reservations:
            rows = self.conn.execute(
                "SELECT DISTINCT h.* FROM timeline_commit_history h, "
                "json_each(h.records_json, '$.commands') r, json_each(r.value, '$.created') i "
                "WHERE json_extract(i.value, '$.kind')=? AND (json_extract(i.value, '$.ref')=? OR ?='item') "
                "AND (h.project_id=? OR ?='item') AND (h.timeline_id=? OR ? IN ('shot', 'item'))",
                (kind, ref, kind, project, kind, timeline, kind)).fetchall()
            for entry in rows:
                if kind == "item" and not any(i["kind"] == "item" and self._reservation_identity("item", i["ref"]) == ref
                        for r in json.loads(entry["records_json"])["commands"]
                        if r["command"]["op"] != "timeline.inverse" for i in r["created"]):
                    continue
                ledger = self.conn.execute("SELECT * FROM command_idempotency WHERE txn_id=?", (entry["publication_id"],)).fetchone()
                if ledger is None:
                    reject("identity_collision")
                self._verify_accepted(ledger, entry)
                reject("identity_collision")

    @staticmethod
    def _reservation_identity(kind, ref):
        if kind == "item":
            member = item_identity(ref)
            if member is None:
                reject("invalid_records", "item reservation requires a canonical item ref", status=422)
            return member[1]
        if kind == "shot" and (root_identity(ref) is None or root_identity(ref)[0] != "shot"):
            reject("invalid_records", "shot reservation requires a canonical shot ref", status=422)
        return ref

    def _check_birth_destinations(self, claims):
        # Native births reserve even if a later command removes the new root.
        # Derived allocations never supply these claims; inverses were excluded.
        for kind, ref in claims:
            if kind == "shot":
                shot = root_identity(ref)[1]
                if (self.conn.execute("SELECT 1 FROM project_shots WHERE id=?", (shot,)).fetchone()
                        or self.conn.execute("SELECT 1 FROM shot_revisions WHERE shot_id=?", (shot,)).fetchone()):
                    reject("destination_occupied")
            elif kind == "item":
                if (self.conn.execute("SELECT 1 FROM shot_items WHERE id=?", (ref,)).fetchone()
                        or self.conn.execute("SELECT 1 FROM shot_revisions s, json_each(s.payload_json, '$.items') i "
                            "WHERE COALESCE(json_extract(i.value, '$.item_id'), json_extract(i.value, '$.id'))=? LIMIT 1", (ref,)).fetchone()):
                    reject("identity_collision")

    def preview(self, context, prepared, *, authorize, inputs=None):
        context, prepared = detached(context), detached(prepared)
        with self.store._mutex:
            authorize()
            if not context["request"].get("dry_run", False):
                reject("preview_requires_dry_run", status=422)
            self._check_context(context)
            self._check_head(context, prepared["expected_head"])
            self._check_shot_destinations(context, prepared, inputs)
            candidate = self._validate(context, prepared, inputs)
            request = context["request"]
            candidate["merge_mode"] = _effective_merge_mode(request)
            if "steps" in prepared["records"]:
                candidate["steps"] = prepared["records"]["steps"]
            base = {"revision_id": request["base_revision_id"], "publication_id": request["base_publication_id"]}
            return {"data": {"status": "preview", "would_status": "accepted" if prepared["expected_head"] == base else "merged",
                            "base_revision_id": request["base_revision_id"],
                            "base_publication_id": request["base_publication_id"],
                            "evaluated_head": prepared["expected_head"], **candidate}, "receipt": None}

    def _check_context(self, context):
        request = context["request"]
        realm = self._membership(request["project_id"], request["timeline_id"])
        if realm != context["realm_id"] or request_identity(context) != context["request_hash"]:
            reject("invocation_mismatch", status=422)
        if context["invocation"]["operation"] == "commitTimeline" and request != context["invocation"]["body"]:
            reject("invocation_mismatch", status=422)
        if self.history_entry(request["project_id"], request["timeline_id"], request["base_publication_id"])["revision_id"] != request["base_revision_id"]:
            reject("history_unavailable")

    def _check_head(self, context, expected):
        from .timeline_commit import StaleHead

        request = context["request"]
        current = self.head(request["project_id"], request["timeline_id"])
        if current != expected:
            raise StaleHead(current)
        base = {"revision_id": request["base_revision_id"], "publication_id": request["base_publication_id"]}
        if any(c["op"] == "timeline.restore" for c in request["commands"]) and expected != base:
            reject("stale_head")

    def accept(self, context, prepared, *, authorize, inputs=None):
        context, prepared = detached(context), detached(prepared)
        with self.store._mutex:
            if self.conn.in_transaction:
                raise ProtocolError("commit acceptance requires the outer transaction")
            with self.store._transaction():
                authorize()
                replay = self._lookup(context)
                if replay is not None:
                    return replay
                if context["request"].get("dry_run", False):
                    reject("dry_run_accept", status=422)
                self._check_context(context)
                self._check_head(context, prepared["expected_head"])
                self._check_shot_destinations(context, prepared, inputs)
                candidate = self._validate(context, prepared, inputs)
                request, previous = context["request"], prepared["expected_head"]
                from .timeline_commit_reference_projection import (
                    ReferenceProjectionError,
                    prepare_reference_projection,
                )
                try:
                    previous_document = self.revision_closure(
                        request["project_id"], request["timeline_id"], previous["revision_id"]
                    )
                    timeline = self.conn.execute(
                        "SELECT version FROM timelines WHERE id=? AND project_id=?",
                        (request["timeline_id"], request["project_id"]),
                    ).fetchone()
                    reference_projection = prepare_reference_projection(
                        self.conn, candidate["canonical_document"], previous_document,
                        next_version=int(timeline["version"]) + 1,
                    )
                except ReferenceProjectionError as exc:
                    reject(exc.reason, exc.message, status=exc.status)
                base = {"revision_id": request["base_revision_id"], "publication_id": request["base_publication_id"]}
                modern = _is_v2_request(request, prepared["records"])
                data = {"status": ("accepted" if previous == base else ("merged" if modern else "rebased")),
                        "base_revision_id": base["revision_id"],
                        "base_publication_id": base["publication_id"], "previous_revision_id": previous["revision_id"],
                        "previous_publication_id": previous["publication_id"],
                        "accepted_revision_id": candidate["canonical_document"]["parent_revision"]["revision_id"],
                        "rebased_onto": None if previous == base else previous, **candidate,
                        "publisher": context["publisher"],
                        **{k: request[k] for k in _METADATA if k in request}}
                if modern:
                    data["merge_mode"] = _effective_merge_mode(request)
                    data.setdefault("label", "Timeline edit")
                if modern and "steps" in prepared["records"]:
                    data["steps"] = prepared["records"]["steps"]
                self._persist_closure(candidate["canonical_document"])
                result = self._publish(context, data, previous, prepared["records"], prepared["semantic_events"])
                from .timeline_commit_reference_projection import (
                    apply_reference_projection,
                )
                if reference_projection is not None:
                    apply_reference_projection(self.conn, reference_projection)
                self._project_text_bindings(candidate["canonical_document"], prepared["records"], result["receipt"]["receipt_id"])
                if inputs is not None:
                    inputs.persist(prepared, result["receipt"]["receipt_id"], data["accepted_revision_id"])
                return result

    def _project_text_bindings(self, document, records, publication_id):
        """Derive live text-binding rows and events from the accepted recorder's writes.

        Runs in the acceptance transaction after _persist_closure; only this commit's
        writes are projected, so historical reuse never repoints a live row.
        """
        project_id = document["project_id"]
        shots = {o["occurrence_id"]: o["shot_id"] for o in document["parent_revision"]["payload"]["occurrences"]}
        for record in records["commands"]:
            for write in record["writes"]:
                if "/text-binding:" not in write["ref"]:
                    continue
                match = _TEXT_BINDING_REF.fullmatch(write["ref"])
                if match is None or write["path"]:
                    reject("invalid_records", "malformed text binding write", status=422)
                occurrence, kind, slot = match.groups()
                owner = "occurrence:" + occurrence
                read = next((r for r in record["reads"] if r["ref"] == owner + "/shot" and r["path"] == ["shot_id"]), None)
                shot_id = shots.get(occurrence)
                if shot_id is None or read is None or read["state"] != {"state": "present", "value": shot_id}:
                    reject("text_binding_owner_changed", "text binding owner differs from the accepted shot")
                self._project_text_binding(project_id, shot_id, kind, slot, write["before"], write["after"], publication_id)

    def _project_text_binding(self, project_id, shot_id, kind, slot, before, after, publication_id):
        from .service import RuntimeService
        from .timeline_commit_port import verify_retained_text_object, verify_text_object
        from .cas import ContentAddressedStore

        owner = self.conn.execute("SELECT project_id FROM project_shots WHERE id=?", (shot_id,)).fetchone()
        if owner is None or owner["project_id"] != project_id:
            reject("dependency_unavailable", "text binding shot is not in this project")
        binding_id = RuntimeService._text_binding_id(project_id, shot_id, kind, slot)
        row = self.conn.execute("SELECT * FROM shot_text_bindings WHERE id=? AND project_id=?", (binding_id, project_id)).fetchone()
        latest = None
        if row is not None:
            events = RuntimeService._text_binding_events(self.conn, row)
            latest = json.loads(events[-1]["payload_json"])
        live = latest is not None and latest.get("state", "present") == "present"
        current = None
        if live:
            media = self.conn.execute("SELECT size, media_type FROM objects WHERE digest=?", (row["media_digest"],)).fetchone()
            if media is None:
                reject("dependency_unavailable", "bound text media is missing")
            current = {"kind": row["kind"], "slot": row["slot"], "media_id": "sha256:" + row["media_digest"],
                       "content_hash": "sha256:" + row["media_digest"], "byte_size": media["size"], "mime_type": media["media_type"]}
        fields = ("kind", "slot", "media_id", "content_hash", "byte_size", "mime_type")
        if (before["state"] == "present") != live or (live and any(
                before["value"].get(field) != current[field] for field in fields)):
            reject("text_binding_mismatch", "recorded text binding state differs from the live binding")
        clearing = after["state"] == "absent"
        if clearing and not live:
            reject("text_binding_mismatch", "cannot clear an absent text binding")
        value = current if clearing else after["value"]
        for descriptor in ([current] if live else []) + ([] if clearing else [value]):
            selection = {"object_id": descriptor.get("media_id"), "digest": descriptor.get("content_hash"),
                         "size": descriptor.get("byte_size"), "media_type": descriptor.get("mime_type")}
            if (descriptor.get("kind"), descriptor.get("slot")) != (kind, slot):
                reject("invalid_records", "text binding row differs from its key", status=422)
            cas = ContentAddressedStore(self.store.cas_root)
            if selection["media_type"] == "text/plain" and row is not None:
                verify_retained_text_object(self.conn, cas, row, selection)
            else:
                verify_text_object(self.conn, cas, project_id, selection)
        object_digest = value["media_id"][7:]
        timestamp = now()
        if row is None:
            self.conn.execute("INSERT INTO shot_text_bindings(id, project_id, shot_id, kind, slot, media_digest, event_stream_id, head_seq, created_at, updated_at) "
                              "VALUES (?, ?, ?, ?, ?, ?, ?, 0, ?, ?)",
                              (binding_id, project_id, shot_id, kind, slot, object_digest, binding_id + ":shot.text_binding", timestamp, timestamp))
            head, previous_hash = 0, ""
        elif live and not clearing and row["media_digest"] == object_digest:
            return
        else:
            head = row["head_seq"]
            previous_hash = self.conn.execute("SELECT event_hash FROM shot_text_binding_events WHERE binding_id=? AND seq=?",
                                              (binding_id, head)).fetchone()["event_hash"]
        event_id, seq = new_id(), head + 1
        event_kind = "shot.text_binding.created" if seq == 1 else "shot.text_binding.rebound"
        payload = {"binding_id": binding_id, "project_id": project_id, "shot_id": shot_id, "kind": kind, "slot": slot,
                   "media_id": value["media_id"], "content_hash": value["content_hash"], "byte_size": value["byte_size"],
                   "mime_type": value["mime_type"], "publication_id": publication_id,
                   "state": "absent" if clearing else "present"}
        event_hash = hashlib.sha256(canonical_json({"event_id": event_id, "binding_id": binding_id, "seq": seq,
                                                    "kind": event_kind, "payload": payload,
                                                    "previous_hash": previous_hash}).encode()).hexdigest()
        self.conn.execute("INSERT INTO shot_text_binding_events(event_id, binding_id, project_id, seq, kind, payload_json, previous_hash, event_hash, created_at) "
                          "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                          (event_id, binding_id, project_id, seq, event_kind, canonical_json(payload), previous_hash, event_hash, timestamp))
        self.conn.execute("UPDATE shot_text_bindings SET media_digest=?, head_seq=?, updated_at=? WHERE id=?",
                          (object_digest, seq, timestamp, binding_id))

    def _persist_closure(self, document):
        project_id, timestamp = document["project_id"], now()
        for image in document["internal_timeline_revisions"]:
            self.conn.execute("INSERT OR IGNORE INTO internal_timeline_revisions(id, project_id, timeline_id, payload_json, content_digest, created_at) "
                              "VALUES (?, ?, ?, ?, ?, ?)", (image["revision_id"], project_id, image["timeline_id"], canonical_json(image["payload"]), image["content_digest"], timestamp))
        for image in document["shot_revisions"]:
            existing = self.conn.execute("SELECT 1 FROM shot_revisions WHERE id=?", (image["revision_id"],)).fetchone()
            if existing:
                continue
            payload, shot_id = image["payload"], image["shot_id"]
            self.conn.execute("INSERT INTO project_shots(id, project_id, name, metadata_json, version, created_at, updated_at, archived_at) "
                              "VALUES (?, ?, ?, ?, 1, ?, ?, ?) ON CONFLICT(id) DO UPDATE SET name=excluded.name, metadata_json=excluded.metadata_json, "
                              "version=project_shots.version+1, updated_at=excluded.updated_at, archived_at=excluded.archived_at",
                              (shot_id, project_id, payload.get("name") or shot_id, canonical_json(payload.get("metadata", {})), timestamp, timestamp,
                               timestamp if payload.get("archived", False) else None))
            self.conn.execute("DELETE FROM shot_items WHERE shot_id=?", (shot_id,))
            for ordinal, item in enumerate(payload.get("items", [])):
                self.conn.execute("INSERT INTO shot_items(id, shot_id, media_id, sort_key, source_frame, metadata_json, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)",
                                  (item.get("item_id", item.get("id")), shot_id, item["media_id"].removeprefix("sha256:"), f"{ordinal:08d}",
                                   item.get("source_frame"), canonical_json(item.get("metadata", {})), timestamp))
            self.conn.execute("INSERT INTO shot_revisions(id, project_id, shot_id, internal_timeline_revision_id, payload_json, content_digest, created_at) "
                              "VALUES (?, ?, ?, ?, ?, ?, ?)", (image["revision_id"], project_id, shot_id, image["internal_timeline_revision_id"],
                                                             canonical_json(payload), image["content_digest"], timestamp))
            self.conn.execute("INSERT INTO shot_revision_heads(shot_id, project_id, revision_id, updated_at) VALUES (?, ?, ?, ?) "
                              "ON CONFLICT(shot_id) DO UPDATE SET revision_id=excluded.revision_id, updated_at=excluded.updated_at",
                              (shot_id, project_id, image["revision_id"], timestamp))
        parent, manifest = document["parent_revision"], document["dependency_manifest"]
        existing = self.conn.execute("SELECT 1 FROM parent_composition_revisions WHERE id=?", (parent["revision_id"],)).fetchone()
        if existing is None:
            self.conn.execute("INSERT INTO parent_composition_revisions(id, project_id, timeline_id, payload_json, content_digest, commit_manifest_json, created_at) "
                              "VALUES (?, ?, ?, ?, ?, ?, ?)", (parent["revision_id"], project_id, document["timeline_id"], canonical_json(parent["payload"]),
                                                             parent["content_digest"], canonical_json(manifest), timestamp))
            for ordinal, occurrence in enumerate(parent["payload"]["occurrences"]):
                self.conn.execute("INSERT INTO composition_revision_occurrences(parent_revision_id, occurrence_id, ordinal, project_id, shot_id, shot_revision_id, "
                                  "placement_json, source_offset_json, duration_ms, speed_json, track, transform_json, gain, muted, provenance_json) "
                                  "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                                  (parent["revision_id"], occurrence["occurrence_id"], ordinal, project_id, occurrence["shot_id"], occurrence["shot_revision_id"],
                                   canonical_json(occurrence["placement"]), canonical_json(occurrence.get("source_offset", 0)), occurrence["duration_ms"],
                                   canonical_json(occurrence.get("speed", 1)), occurrence["track"], canonical_json(occurrence.get("transform", {})), occurrence.get("gain", 1),
                                   int(occurrence.get("muted", occurrence.get("mute", False))), canonical_json(occurrence.get("provenance", {}))))
            dependencies = [("shot_revision", p["revision_id"], p["content_digest"]) for p in manifest["shots"]]
            dependencies += [("internal_timeline_revision", p["revision_id"], p["content_digest"]) for p in manifest["internal_timelines"]]
            dependencies += [("media", p["media_id"], p["content_digest"]) for p in manifest["media"]]
            for ordinal, (kind, identity, content_digest) in enumerate(dependencies):
                self.conn.execute("INSERT INTO composition_revision_dependencies VALUES (?, ?, ?, ?, ?)",
                                  (parent["revision_id"], kind, identity, content_digest, ordinal))
        else:
            self.conn.execute("UPDATE parent_composition_revisions SET commit_manifest_json=? WHERE id=? AND commit_manifest_json IS NULL",
                              (canonical_json(manifest), parent["revision_id"]))

    def _publish(self, context, data, previous, records, semantic_events):
        request = context["request"]
        project_id, timeline_id = request["project_id"], request["timeline_id"]
        revision_id = data["canonical_document"]["parent_revision"]["revision_id"]
        event_ids = []
        for event in semantic_events:
            event_ids.append(self.store._append_timeline_event(timeline_id, event["kind"],
                {"project_id": project_id, "timeline_id": timeline_id, "publisher": context["publisher"], **event}))
        event_ids.append(self.store._append_timeline_event(timeline_id, "timeline.commit.accepted",
            {"project_id": project_id, "timeline_id": timeline_id, "previous": previous, "revision_id": revision_id,
             "publisher": context["publisher"], "intent": "recorded", "records_digest": digest(records)}))
        seq = self.conn.execute("SELECT COUNT(*) FROM timeline_events WHERE timeline_id=?", (timeline_id,)).fetchone()[0]
        publication_id = self.store._record_command_receipt("timeline.commit", scope(context), context["idempotency_key"], context["request_hash"],
            data, project_id=project_id, event_ids=event_ids, primary_stream_id=timeline_id, resulting_stream_seq=seq)
        ledger = self.conn.execute("SELECT * FROM command_idempotency WHERE txn_id=?", (publication_id,)).fetchone()
        metadata = _history_metadata(request, data)
        self.conn.execute("INSERT INTO timeline_commit_history VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (publication_id, project_id, timeline_id, revision_id, previous["publication_id"] if previous else None,
             previous["revision_id"], "recorded", canonical_json(records),
             canonical_json(metadata), data.get("provider_version"), data.get("compiler_version"),
             context["publisher"], ledger["first_project_seq"]))
        changed = self.conn.execute("UPDATE parent_composition_heads SET revision_id=?, publication_id=?, updated_at=? "
            "WHERE project_id=? AND timeline_id=? AND revision_id=? AND publication_id=?", (revision_id, publication_id, now(), project_id, timeline_id,
            previous["revision_id"], previous["publication_id"])).rowcount
        if changed != 1:
            raise ProtocolError("head changed inside acceptance transaction")
        self.conn.execute("UPDATE timelines SET version=version+1 WHERE id=? AND project_id=?", (timeline_id, project_id))
        return self._envelope(ledger, project_id)

    def _install_entries(self, project_id, timeline_id, plan):
        for entry in plan["entries"]:
            previous = entry["previous"]
            self.conn.execute("INSERT INTO timeline_commit_history VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (entry["publication_id"], project_id, timeline_id, entry["revision_id"],
                 previous["publication_id"] if previous else None, previous["revision_id"] if previous else None,
                 entry["intent"], None, canonical_json({k: entry[k] for k in _METADATA if k in entry}),
                 entry["provider_version"], entry["compiler_version"], entry["publisher"], entry["receipt"]["project_seq"][0]))
        changed = self.conn.execute("UPDATE parent_composition_heads SET publication_id=? WHERE project_id=? AND timeline_id=? "
                                   "AND revision_id=? AND publication_id IS NULL", (plan["head"]["publication_id"], project_id,
                                   timeline_id, plan["head"]["revision_id"])).rowcount
        if changed != 1:
            reject("stale_head")

    def install_verified_baseline(self, project_id, timeline_id, *, authorize):
        from .cas import ContentAddressedStore
        from .timeline_commit_baseline import baseline_install_plan, verify_baseline

